  // s-041 is the profile menu. s-042 is the separate space switcher.
  function profileMenuAvailable() {
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.profileMenu === false || capabilities.profiles === false) return false;
      }
    } catch (error) {}
    return true;
  }

  function guestWindowAvailable() {
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.guest === false || capabilities.canGuestWindow === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // s-043 is the browser/app menu.
  function appMenuAvailable() {
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.appMenu === false || capabilities.browserMenu === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // s-045 is the OS jump list / taskbar recents surface.
  function jumpListAvailable() {
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.jumpList === false || capabilities.taskbar === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // s-047 is the link context menu.
  function linkContextAvailable() {
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.linkContext === false || capabilities.contextMenu === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // s-050 is the command palette.
  function commandPaletteAvailable() {
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.commandPalette === false || capabilities.commandBar === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // s-031 expands the omnibox suggestions. Platforms without a shared
  // omnibox can hide it while keeping the toolbar map.
  function expandedOmniboxAvailable() {
    if (!toolbarAvailable()) return false;
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.omnibox === false || capabilities.omniboxSuggestions === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // A platform without a narrow window can hide this map explicitly. The
  // screen describes the same window as s-021, only at its compact width.
  function compactWindowAvailable() {
    if (!mainWindowAvailable()) return false;
    try {
      if (typeof capabilities !== 'undefined' && capabilities && capabilities.compactWindow === false) {
        return false;
      }
    } catch (error) {}
    return true;
  }

  // s-025 documents the horizontal tab strip. A platform with a different
  // tab affordance can hide it explicitly.
  function horizontalTabsAvailable() {
    if (!mainWindowAvailable()) return false;
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.horizontalTabs === false || capabilities.tabStrip === false) return false;
      }
    } catch (error) {}
    return true;
  }

  // s-027 expands the strip's overflow into the complete tab menu. It is
  // only meaningful where the horizontal strip exists.
  function tabOverflowAvailable() {
    if (!horizontalTabsAvailable()) return false;
    try {
      if (typeof capabilities !== 'undefined' && capabilities) {
        if (capabilities.tabMenu === false || capabilities.tabOverflow === false) return false;
      }
    } catch (error) {}
    return true;
  }

  function activeLists() {
    try {
      return typeof adBlockConfig !== 'undefined' && adBlockConfig.lists ? adBlockConfig.lists : null;
    } catch (error) {
      return null;
    }
  }
  function isChecked(key) {
    if (draft && Object.prototype.hasOwnProperty.call(draft, key)) return draft[key];
    const lists = activeLists();
    return lists ? lists[key] !== false : true;
  }
  const canDefaultBrowser = () =>
    typeof capabilities !== 'undefined' && capabilities.canDefaultBrowser === true;
  const canDnsSettings = () =>
    typeof capabilities !== 'undefined' && capabilities.canDnsSettings === true;
  // Tab orientation only exists in the desktop tab strip (same rule the
  // Settings dialog uses for its "desktop" gate).
  const canTabOrientation = () => {
    try {
      return (
        typeof platform !== 'undefined' &&
        platform !== 'ios' &&
        platform !== 'android' &&
        !(typeof narrowLayout !== 'undefined' && narrowLayout && narrowLayout.matches)
      );
    } catch (error) {
      return false;
    }
  };
  const canAccent = () => {
    try {
      return !!(
        typeof spaceStore !== 'undefined' &&
        spaceStore &&
        typeof spaces !== 'undefined' &&
        spaces &&
        Array.isArray(spaces.list) &&
        spaces.list.length
      );
    } catch (error) {
      return false;
    }
  };
  const pref = () => (typeof VaayvuPreferences !== 'undefined' && VaayvuPreferences) || null;
  const currentSetting = (key, fallback) => {
    try {
      return typeof settings !== 'undefined' && settings && settings[key] !== undefined ? settings[key] : fallback;
    } catch (error) {
      return fallback;
    }
  };
  function currentAccent() {
    try {
      const active = spaces.list.find((space) => space.id === spaces.active) || spaces.list[0];
      return active && active.theme ? active.theme : 'aurora';
    } catch (error) {
      return '';
    }
  }
  function accentName(id) {
    try {
      if (typeof VaayvuSpaces !== 'undefined' && VaayvuSpaces && VaayvuSpaces.THEMES && VaayvuSpaces.THEMES[id]) {
        return VaayvuSpaces.THEMES[id].name;
      }
    } catch (error) {}
    return id;
  }
  function accentIds() {
    try {
      if (typeof VaayvuSpaces !== 'undefined' && VaayvuSpaces && Array.isArray(VaayvuSpaces.THEME_IDS)) {
        return VaayvuSpaces.THEME_IDS;
      }
    } catch (error) {}
    return [];
  }

  // s-015 checklist gates. Every row opens the real surface behind it and no
  // row is ever marked done on a guess: the marks are read from live device
  // state (imported bookmarks, a signed-in sync session, saved passwords,
  // installed style extensions). The default-browser request cannot be
  // verified from inside the page, so that row never claims success.
  const has = (key) => typeof capabilities !== 'undefined' && capabilities && capabilities[key] === true;
  const canSync = () => {
    try {
      return typeof sync !== 'undefined' && !!sync;
    } catch (error) {
      return false;
    }
  };
  const canImportPasswords = () =>
    has('canImportPasswords') && typeof write === 'function';
  const canExtensions = () => has('canUserStyles');
  const syncConnected = () => {
    try {
      return !!(typeof sync !== 'undefined' && sync && sync.session);
    } catch (error) {
      return false;
    }
  };
  function bookmarkCount() {
    try {
      return typeof bookmarks !== 'undefined' && Array.isArray(bookmarks) ? bookmarks.length : 0;
    } catch (error) {
      return 0;
    }
  }
  function savedPasswordCount() {
    try {
      return typeof passwords !== 'undefined' && Array.isArray(passwords) ? passwords.length : 0;
    } catch (error) {
      return 0;
    }
  }
  function extensionCount() {
    try {
      let keys = [];
      if (typeof localStorage.length === 'number' && typeof localStorage.key === 'function') {
        for (let i = 0; i < localStorage.length; i += 1) keys.push(localStorage.key(i));
      } else {
        keys = Object.keys(localStorage);
      }
      return keys.filter((key) => key.startsWith('vaayvu.styleExtension.')).length;
    } catch (error) {
      return 0;
    }
  }

  // Minimal RFC 4180 reader — enough for the CSV files browsers export, with
  // quoted fields and doubled quotes, no third-party parser.
  function parseCsv(text) {
    const rows = [];
    let row = [];
    let field = '';
    let quoted = false;
    for (let i = 0; i < text.length; i += 1) {
      const char = text[i];
      if (quoted) {
        if (char === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 1;
          } else quoted = false;
        } else field += char;
      } else if (char === '"') quoted = true;
      else if (char === ',') {
        row.push(field);
        field = '';
      } else if (char === '\n') {
        row.push(field);
        rows.push(row);
        row = [];
        field = '';
      } else if (char !== '\r') field += char;
    }
    if (field !== '' || row.length) {
      row.push(field);
      rows.push(row);
    }
    return rows.filter((cells) => cells.some((cell) => cell.trim() !== ''));
  }

  // Column order differs per exporter (Chrome/Edge: name,url,username,password;
  // Firefox/Safari put url first), so map by header name instead of position.
  // Reads password rows into import units: a valid { entry } or a { skip,
  // label } that keeps the reason for the results screen. Blank rows are not
  // counted; the 2,000-entry ceiling mirrors the store.
  function passwordPlan(rows) {
    if (!rows.length) return { units: [], headerMissing: true };
    const header = rows[0].map((cell) => cell.trim().toLowerCase());
    const find = (names) => header.findIndex((cell) => names.includes(cell));
    const urlAt = find(['url', 'website', 'site', 'login']);
    const userAt = find(['username', 'user', 'login']);
    const passAt = find(['password', 'pass']);
    const data = rows.slice(1).filter((cells) => cells.some((cell) => cell.trim() !== ''));
    if (urlAt < 0 || userAt < 0 || passAt < 0) {
      return { units: data.map(() => ({ skip: 'Unrecognised columns', label: '' })), headerMissing: true };
    }
    const units = [];
    let accepted = 0;
    for (const cells of data) {
      const site = (cells[urlAt] || '').trim();
      const username = (cells[userAt] || '').trim();
      const password = cells[passAt] || '';
      if (!site) units.push({ skip: 'Missing website', label: username, data: { site, username, password } });
      else if (!username) units.push({ skip: 'Missing username', label: site, data: { site, username, password } });
      else if (!password) units.push({ skip: 'Missing password', label: site + ' · ' + username, data: { site, username, password } });
      else if (accepted >= 2000) units.push({ skip: 'Password limit reached', label: site, data: { site, username, password } });
      else {
        units.push({ entry: { site, username, password } });
        accepted += 1;
      }
    }
    return { units, headerMissing: false };
  }

  function passwordEntries(rows) {
    return passwordPlan(rows)
      .units.filter((unit) => unit.entry)
      .map((unit) => unit.entry);
  }

  // Merges imported sign-ins into the same local store the Passwords dialog
  // uses (site + username is the identity that dialog already dedupes on).
  function importPasswords(entries) {
    if (!entries.length || typeof passwords === 'undefined' || !Array.isArray(passwords)) return 0;
    if (typeof write !== 'function') return 0;
    let imported = 0;
    for (const entry of entries) {
      const existing = passwords.findIndex((item) => item.site === entry.site && item.username === entry.username);
      if (existing >= 0) passwords[existing] = { ...passwords[existing], password: entry.password, at: Date.now() };
      else passwords.push({ ...entry, at: Date.now() });
      imported += 1;
    }
    write('passwords', passwords);
    return imported;
  }

  function readPasswordFile(file) {
    if (!file || typeof file.text !== 'function') return;
    file
      .text()
      .then((text) => {
        const imported = importPasswords(passwordEntries(parseCsv(String(text || ''))));
        if (typeof toast === 'function') {
          toast(imported ? imported + (imported === 1 ? ' password imported.' : ' passwords imported.') : 'No passwords found in that file.');
        }
        if (!boot.reprompt && STEPS[current] === 's-015') renderStep();
      })
      .catch(() => {
        if (typeof toast === 'function') toast('That file could not be read.');
      });
  }

  function chosen() {
    const out = {};
    for (const input of overlay.querySelectorAll('input[data-cat]')) out[input.dataset.cat] = input.checked === true;
    return out;
  }

  function applyCategories(next) {
    if (!next || typeof adBlockConfig === 'undefined') return;
    adBlockConfig.enabled = true;
    adBlockConfig.lists = { ...adBlockConfig.lists, ...next };
    if (typeof write === 'function') write('adBlock', adBlockConfig);
    if (typeof sendBlocklist === 'function') sendBlocklist(true);
    if (typeof drawBar === 'function') drawBar();
  }

  function finish(status, extra) {
    const record = readRecord();
    const previousSteps = record && Array.isArray(record.steps) ? record.steps : [];
    const checklist =
      current === STEPS.length - 1
        ? {
            bookmarks: bookmarkCount(),
            sync: syncConnected(),
            passwords: savedPasswordCount(),
            extensions: extensionCount(),
          }
        : null;
    try {
      localStorage.setItem(KEY, JSON.stringify({
        ...(record || {}),
        route: routeOf(),
        phase: phaseOf(),
        status,
        steps: visited.length ? [...visited] : previousSteps,
        ...(picked ? { categories: picked } : {}),
        ...(checklist && !boot.reprompt ? { checklist } : {}),
        ...(extra || {}),
        completedAt: Date.now(),
      }));
      localStorage.removeItem('vaayvu.onboardingAttempts');
    } catch (error) {}
    root.dataset.onboarding = 'hide';
    overlay.remove();
    closed = true;
    if (typeof toast === 'function') {
      const safe = extra && extra.safeMode;
      const crash = extra && extra.crashRestore;
      toast(
        crash === 'restored'
          ? 'Tabs restored.'
          : crash === 'discarded'
            ? 'Tabs discarded.'
            : safe === 'extensions-disabled'
              ? 'Extensions disabled. Vaayvu is ready.'
              : safe === 'reset'
                ? 'Browser settings reset to defaults.'
                : safe === 'continued'
                  ? 'Opened with your current setup.'
                  : status === 'done'
                    ? 'Rasha Shield is on'
                    : 'Using recommended protection',
      );
    }
  }

  function selectRow(kind, label, detail, options, value) {
    return (
      '<label class="onboarding-priv"><span><strong>' + label + '</strong><small>' + detail + '</small></span>' +
      '<select data-priv="' + kind + '" aria-label="' + label + '">' +
      options
        .map(([option, name]) => '<option value="' + option + '"' + (value === option ? ' selected' : '') + '>' + name + '</option>')
        .join('') +
      '</select></label>'
    );
  }

  function renderBootSplash() {
    return (
      '<div class="onboarding-splash">' +
      '<img class="splash-logo" src="assets/vaayvu.svg" width="72" height="72" alt="">' +
      '<span class="splash-wordmark">Vaayvu</span>' +
      '<span class="splash-ready">Ready in under 300 ms</span>' +
      '<div class="splash-notes">' +
      '<div class="splash-note"><strong>Local boot</strong><span>Logo and shell load from disk, before any network.</span></div>' +
      '<div class="splash-note"><strong>Crash-loop guard</strong><span>Three unfinished launches drop straight into the browser.</span></div>' +
      '<div class="splash-note"><strong>Fallback</strong><span>If the UI does not take over in 5 s, onboarding steps aside.</span></div>' +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="skip">Skip onboarding</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step 1 of ' + TOTAL + ' · Boot</small>' +
      '</div>'
    );
  }

  function renderCategories() {
    return (
      '<div class="onboarding-cats">' +
      CATEGORIES.map(([key, label, detail]) =>
        '<label class="onboarding-cat"><span><strong>' + label + '</strong><small>' + detail + '</small></span>' +
        '<input type="checkbox" data-cat="' + key + '"' + (isChecked(key) ? ' checked' : '') + ' /></label>',
      ).join('') +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="skip">Skip for now</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step 1 of ' + TOTAL + ' · Protected by default</small>'
    );
  }

  function renderWelcome() {
    const canImport = typeof capabilities !== 'undefined' && capabilities.canImportBookmarks === true;
    const canSync = typeof sync !== 'undefined' && !!sync;
    const choices = [];
    if (canImport) {
      choices.push(
        '<button type="button" class="onboarding-choice" data-onboard="import">' +
        '<strong>Import bookmarks</strong><small>Bring bookmarks from your old browser</small></button>',
      );
    }
    if (canSync) {
      choices.push(
        '<button type="button" class="onboarding-choice" data-onboard="sync">' +
        '<strong>Sync with Vaayvu ID</strong><small>Continue on your other devices</small></button>',
      );
    }
    return (
      '<ul class="onboarding-values">' + VALUES.map((line) => '<li>' + line + '</li>').join('') + '</ul>' +
      (choices.length ? '<div class="onboarding-choices">' + choices.join('') + '</div>' : '') +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="start">Get started</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step 2 of ' + TOTAL + ' · Welcome to Vaayvu</small>'
    );
  }

  // s-004 — import source picker (route vaayvu://onboarding/s-004, phase p00).
  // Bookmarks always arrive as browser-exported HTML through the native picker;
  // CSV, 1Password and Bitwarden exports use the same local password importer
  // as s-015. Groups appear only where the platform reports the capability.
  function renderImportSource() {
    const canBookmarks = has('canImportBookmarks');
    const canPasswords = canImportPasswords();
    const sourcesFor = (kind) =>
      IMPORT_SOURCES.filter((source) =>
        source.kind === kind ? (kind === 'bookmarks' ? canBookmarks : canPasswords) : false,
      );
    const bookmarks = sourcesFor('bookmarks');
    const passwords = sourcesFor('passwords');
    const selected = IMPORT_SOURCES.find((source) => source.id === importSource);
    const chosen =
      selected && (selected.kind === 'bookmarks' ? canBookmarks : canPasswords) ? selected : null;
    const group = (sources, label) =>
      sources.length
        ? '<div class="onboarding-source-group"><small class="onboarding-source-label">' +
          label +
          '</small><div class="onboarding-sources" role="group" aria-label="' +
          label +
          '">' +
          sources
            .map(
              (source) =>
                '<button type="button" class="onboarding-source" data-source="' +
                source.id +
                '" aria-pressed="' +
                (chosen && chosen.id === source.id) +
                '"><span class="onboarding-source-mark" aria-hidden="true">' +
                source.mark +
                '</span><strong>' +
                source.name +
                '</strong></button>',
            )
            .join('') +
          '</div></div>'
        : '';
    return (
      '<div class="onboarding-import">' +
      group(bookmarks, 'Bookmarks') +
      group(passwords, 'Passwords') +
      (!bookmarks.length && !passwords.length
        ? '<p class="onboarding-start-empty">Import from another browser is not available on this device.</p>'
        : '') +
      (chosen
        ? '<div class="onboarding-source-detail"><span><strong>From ' +
          chosen.name +
          '</strong><small>' +
          chosen.how +
          '</small></span><button type="button" class="onboarding-check-act" data-carry="' +
          (chosen.kind === 'bookmarks' ? 'import' : 'password') +
          '">' +
          (chosen.kind === 'bookmarks' ? 'Choose file' : 'Choose CSV') +
          '</button></div>'
        : '') +
      (passwords.length ? '<input type="file" accept=".csv,text/csv" data-import-passwords hidden />' : '') +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Import source picker</small>'
    );
  }

  // s-005 — import process (route vaayvu://onboarding/s-005, phase p00).
  // The screen owns a real, cancellable job: entries are parsed once, added in
  // batches so Cancel can stop the rest, and every number shown (found,
  // imported, skipped) comes from what actually happened in this session.
  const IMPORT_BATCH = 25;

  function decodeEntities(text) {
    return String(text)
      .replace(/&lt;/gi, '<')
      .replace(/&gt;/gi, '>')
      .replace(/&quot;/gi, '"')
      .replace(/&#0*39;|&apos;/gi, "'")
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&');
  }

  // Netscape bookmark exports quote every HREF; this reads the same links the
  // native importer receives without needing a DOM in constrained contexts.
  function parseBookmarkHtml(text) {
    const items = [];
    const pattern = /<a\b[^>]*\bhref\s*=\s*(?:"([^"]*)"|'([^']*)')[^>]*>([\s\S]*?)<\/a>/gi;
    let match;
    while ((match = pattern.exec(text)) && items.length < 5000) {
      items.push({
        url: (match[1] !== undefined ? match[1] : match[2]).trim(),
        title: decodeEntities(match[3].replace(/<[^>]*>/g, '')).trim(),
      });
    }
    return items;
  }

  function bookmarkUrl(value) {
    try {
      if (typeof VaayvuCore !== 'undefined' && VaayvuCore && typeof VaayvuCore.webURL === 'function') {
        return VaayvuCore.webURL(value);
      }
    } catch (error) {}
    if (typeof value !== 'string' || value.length > 8192) return '';
    return /^https?:\/\/[^\s]+$/i.test(value) ? value : '';
  }

  function knownBookmarkUrls() {
    try {
      const list = typeof bookmarks !== 'undefined' && Array.isArray(bookmarks) ? bookmarks : [];
      return new Set(list.map((item) => bookmarkUrl(item.url) || String(item.url || '')).filter(Boolean));
    } catch (error) {
      return new Set();
    }
  }

  function noteSkip(job, label, reason, data) {
    job.skipReasons[reason] = (job.skipReasons[reason] || 0) + 1;
    if (job.skips.length < 100)
      job.skips.push({
        label: String(label || '').slice(0, 120),
        reason,
        data: data && typeof data === 'object' ? { ...data } : null,
        fixed: false,
      });
  }

  function startImportJob(options) {
    if (importJob && importJob.timer != null && typeof clearTimeout === 'function') clearTimeout(importJob.timer);
    const text = options && typeof options.text === 'string' ? options.text : '';
    const kind = options && options.kind === 'passwords' ? 'passwords' : 'bookmarks';
    const sourceId = options && typeof options.sourceId === 'string' ? options.sourceId : '';
    const allowed = kind === 'passwords' ? canImportPasswords() : has('canImportBookmarks');
    if (!text) {
      importJob = null;
      renderStep();
      return;
    }
    if (text.length > 2097152) {
      importJob = { sourceId, kind, units: [], total: 0, cursor: 0, added: 0, skipped: 0, skips: [], skipReasons: {}, status: 'invalid', timer: null };
      renderStep();
      return;
    }
    if (!allowed) {
      importJob = { sourceId, kind, units: [], total: 0, cursor: 0, added: 0, skipped: 0, skips: [], skipReasons: {}, status: 'unavailable', timer: null };
      renderStep();
      return;
    }
    const plan = kind === 'passwords' ? passwordPlan(parseCsv(text)) : null;
    const units =
      kind === 'passwords'
        ? plan.units
        : parseBookmarkHtml(text).map((item) => ({ entry: item }));
    const bookmarkTotal =
      kind === 'passwords' ? 0 : typeof bookmarks !== 'undefined' && Array.isArray(bookmarks) ? bookmarks.length : 0;
    importJob = {
      sourceId,
      kind,
      text,
      units,
      total: units.length,
      headerMissing: kind === 'passwords' ? plan.headerMissing : false,
      cursor: 0,
      added: 0,
      skipped: 0,
      skips: [],
      skipReasons: {},
      known: kind === 'passwords' ? null : knownBookmarkUrls(),
      bookmarkTotal,
      status: 'running',
      timer: null,
    };
    renderStep();
    runImportBatch();
  }

  function runImportBatch() {
    if (!importJob || importJob.status !== 'running') return;
    const job = importJob;
    const batch = job.units.slice(job.cursor, job.cursor + IMPORT_BATCH);
    job.cursor += batch.length;
    if (batch.length && job.kind === 'passwords') {
      const entries = batch.filter((unit) => unit.entry).map((unit) => unit.entry);
      const added = importPasswords(entries);
      job.added += added;
      for (const unit of batch) if (unit.skip) noteSkip(job, unit.label, unit.skip, unit.data);
      if (added < entries.length)
        for (let n = added; n < entries.length; n += 1) noteSkip(job, entries[n].site, 'Not added');
    } else if (batch.length) {
      const accepted = [];
      for (const unit of batch) {
        const item = unit.entry;
        const url = bookmarkUrl(item.url);
        if (!url) noteSkip(job, item.title || item.url, 'Not a website address', item);
        else if (job.known.has(url)) noteSkip(job, item.title || url, 'Already saved', item);
        else if (job.bookmarkTotal >= 2000) noteSkip(job, item.title || url, 'Bookmark limit reached', item);
        else {
          accepted.push(item);
          job.known.add(url);
          job.bookmarkTotal += 1;
        }
      }
      const added = typeof addManyBookmarks === 'function' ? addManyBookmarks(accepted) : 0;
      job.added += added;
      if (added < accepted.length)
        for (let n = added; n < accepted.length; n += 1) noteSkip(job, accepted[n].title || accepted[n].url, 'Not added');
    }
    job.timer = null;
    if (job.cursor >= job.units.length) {
      job.status = 'done';
      job.skipped = Math.max(0, job.total - job.added);
      renderStep();
      return;
    }
    renderStep();
    if (typeof setTimeout === 'function') job.timer = setTimeout(runImportBatch, 0);
    else runImportBatch();
  }

  function cancelImportJob() {
    if (!importJob || importJob.status !== 'running') return;
    if (importJob.timer != null && typeof clearTimeout === 'function') clearTimeout(importJob.timer);
    importJob.timer = null;
    importJob.status = 'cancelled';
    importJob.skipped = Math.max(0, importJob.total - importJob.added);
    renderStep();
  }

  function renderImportProcess() {
    const job = importJob;
    const source = job ? IMPORT_SOURCES.find((item) => item.id === job.sourceId) : null;
    const plural = job && job.kind === 'passwords' ? 'passwords' : 'bookmarks';
    const name = source ? source.name : job && job.kind === 'passwords' ? 'Password CSV' : 'Bookmarks HTML';
    const mark = source ? source.mark : job && job.kind === 'passwords' ? 'CSV' : 'H';
    const running = !!job && job.status === 'running';
    let heading = 'No import in progress';
    let detail = 'Choose a source from the import screen to start.';
    let partial = false;
    if (job) {
      if (job.status === 'invalid') {
        heading = 'That file is too large';
        detail = 'Choose a bookmark or password file under 2 MB.';
      } else if (job.status === 'unavailable') {
        heading = 'This import is not available';
        detail = 'The device did not report support for this kind of import.';
      } else if (job.status === 'running') {
        heading = 'Importing your data';
        detail = job.added + ' of ' + job.total + ' ' + plural + ' added so far.';
      } else if (job.status === 'cancelled') {
        heading = 'Import cancelled';
        detail = 'Imported ' + job.added + ' of ' + job.total + ' ' + plural + ' before you cancelled. The rest were not added.';
      } else if (!job.total) {
        heading = 'Nothing to import';
        detail = job.headerMissing
          ? 'The file did not have website, username and password columns.'
          : 'The file did not contain any ' + plural + '.';
      } else if (job.added >= job.total) {
        heading = 'Imported all ' + job.total + ' ' + plural;
        detail = 'Everything in the file was added to this device.';
      } else {
        partial = true;
        heading = 'Imported ' + job.added + ' of ' + job.total + ' ' + plural;
        detail =
          job.kind === 'passwords'
            ? 'Skipped ' + job.skipped + ' row' + (job.skipped === 1 ? '' : 's') + ' — the website, username or password was missing.'
            : 'Skipped ' + job.skipped + ' — duplicates, invalid addresses or the 2,000-bookmark limit.';
      }
    }
    return (
      '<div class="onboarding-import">' +
      (job
        ? '<div class="onboarding-import-source"><span class="onboarding-source-mark" aria-hidden="true">' + mark + '</span>' +
          '<span><strong>' + name + '</strong><small>' + (running ? 'Import in progress' : 'Import summary') + '</small></span></div>'
        : '') +
      '<div class="onboarding-import-status" role="status" data-status="' +
      (running ? 'running' : partial ? 'partial' : job ? job.status : 'idle') +
      '"><strong>' + heading + '</strong><small>' + detail + '</small></div>' +
      (running
        ? '<progress class="onboarding-import-progress" max="' + Math.max(1, job.total) + '" value="' + Math.min(job.cursor, Math.max(1, job.total)) + '">' +
          job.cursor + ' of ' + job.total + '</progress>'
        : '') +
      '</div>' +
      '<div class="onboarding-actions">' +
      (running
        ? '<button type="button" class="onboarding-skip" data-import-cancel>Cancel</button>'
        : '<button type="button" class="onboarding-primary" data-onboard="back">' + (job ? 'Done' : 'Back') + '</button>') +
      '</div>' +
      '<small class="onboarding-step-label">Import progress</small>'
    );
  }

  // s-006 — import results (route vaayvu://onboarding/s-006, phase p00).
  // Counts and reasons come from the job itself: every skip was recorded with
  // its reason while the file was read, so this screen never estimates. The
  // "Fix" link opens the real manager (<dialog> renders above the onboarding
  // overlay via the browser's top layer), where duplicates and missing rows can
  // be handled.
  function renderImportResults() {
    const job = importJob;
    const source = job ? IMPORT_SOURCES.find((item) => item.id === job.sourceId) : null;
    const plural = job && job.kind === 'passwords' ? 'passwords' : 'bookmarks';
    const running = !!job && job.status === 'running';
    const usable = !!job && job.status !== 'invalid' && job.status !== 'unavailable';
    const found = usable ? job.total : 0;
    const imported = usable ? job.added : 0;
    const skipped = usable ? Math.max(0, job.total - job.added) : 0;
    const reasons = job && job.skipReasons
      ? Object.entries(job.skipReasons)
          .filter(([, count]) => count > 0)
          .sort((a, b) => b[1] - a[1])
      : [];
    const skipRows = job
      ? job.skips.map((item, index) => ({ item, index })).filter((row) => !row.item.fixed)
      : [];
    const sample = skipRows.slice(0, 6);
    const fixing = job ? job.fixing : null;
    let status = '';
    if (!job) {
      status =
        '<div class="onboarding-import-status" data-status="idle"><strong>No import results yet</strong>' +
        '<small>Run an import to see what was added and what was skipped.</small></div>';
    } else if (job.status === 'invalid') {
      status =
        '<div class="onboarding-import-status" data-status="invalid"><strong>That file is too large</strong>' +
        '<small>Choose a bookmark or password file under 2 MB.</small></div>';
    } else if (job.status === 'unavailable') {
      status =
        '<div class="onboarding-import-status" data-status="unavailable"><strong>This import is not available</strong>' +
        '<small>The device did not report support for this kind of import.</small></div>';
    } else if (running) {
      status =
        '<div class="onboarding-import-status" data-status="running"><strong>Importing…</strong>' +
        '<small>' + job.added + ' of ' + job.total + ' ' + plural + ' added so far.</small></div>' +
        '<progress class="onboarding-import-progress" max="' + Math.max(1, job.total) + '" value="' +
        Math.min(job.cursor, Math.max(1, job.total)) + '">' + job.cursor + ' of ' + job.total + '</progress>';
    } else if (job.status === 'cancelled') {
      status =
        '<div class="onboarding-import-status" data-status="cancelled"><strong>Import cancelled</strong>' +
        '<small>Imported ' + job.added + ' of ' + job.total + ' ' + plural + ' before you cancelled.</small></div>';
    } else if (!job.total) {
      status =
        '<div class="onboarding-import-status" data-status="' + (job.headerMissing ? 'invalid' : 'done') +
        '"><strong>' + (job.headerMissing ? 'Unrecognised columns' : 'Nothing to import') + '</strong><small>' +
        (job.headerMissing
          ? 'The file did not have website, username and password columns.'
          : 'The file did not contain any ' + plural + '.') +
        '</small></div>';
    } else if (skipped === 0) {
      status =
        '<div class="onboarding-import-status" data-status="done"><strong>Nothing was skipped</strong>' +
        '<small>Every entry in the file was added to this device.</small></div>';
    }
    const counts = usable
      ? '<div class="onboarding-counts">' +
        '<div><strong>' + found + '</strong><small>Found</small></div>' +
        '<div><strong>' + imported + '</strong><small>Imported</small></div>' +
        '<div data-skipped="' + (skipped > 0) + '"><strong>' + skipped + '</strong><small>Skipped</small></div>' +
        '</div>'
      : '';
    const skippedBlock =
      usable && (skipped > 0 || reasons.length)
        ? '<div class="onboarding-skip-block"><strong>What was skipped</strong>' +
          '<div class="onboarding-skip-reasons">' +
          reasons
            .map(
              ([reason, count]) =>
                '<div class="onboarding-skip-reason"><span>' + reason + '</span><strong>' + count + '</strong></div>',
            )
            .join('') +
          '</div>' +
          (sample.length
            ? '<ul class="onboarding-skip-items">' +
              sample
                .map(
                  (row) =>
                    '<li><span>' + esc(row.item.label || 'Untitled') + '</span><small>' + row.item.reason + '</small>' +
                    (fixableSkip(job, row.item) && fixing !== row.index
                      ? '<button type="button" class="onboarding-fix" data-fix-open="' + row.index + '">Fix</button>'
                      : '') +
                    (fixing === row.index ? fixForm(job, row.index, row.item) : '') +
                    '</li>',
                )
                .join('') +
              '</ul>'
            : '') +
          '</div>'
        : '';
    return (
      '<div class="onboarding-import">' +
      (job
        ? '<div class="onboarding-import-source"><span class="onboarding-source-mark" aria-hidden="true">' +
          (source ? source.mark : job.kind === 'passwords' ? 'CSV' : 'H') +
          '</span><span><strong>' + (source ? source.name : job.kind === 'passwords' ? 'Password CSV' : 'Bookmarks HTML') +
          '</strong><small>Import results</small></span></div>'
        : '') +
      counts +
      status +
      skippedBlock +
      '</div>' +
      (running
        ? ''
        : '<div class="onboarding-actions"><button type="button" class="onboarding-primary" data-onboard="back">' +
          (job ? 'Done' : 'Back') +
          '</button></div>') +
      '<small class="onboarding-step-label">Import results</small>'
    );
  }

  // A skipped row is fixable only when filling a missing or invalid value can
  // actually save it: an address that was not a website, or a password row
  // missing one of its three fields. Duplicates and the store limit cannot be
  // repaired from this screen, so they carry no Fix link.
  function fixableSkip(job, item) {
    if (!item || !item.data) return false;
    if (job.kind === 'bookmarks') return item.reason === 'Not a website address';
    return ['Missing website', 'Missing username', 'Missing password'].includes(item.reason);
  }

  function fixForm(job, index, item) {
    const data = item.data || {};
    const field = (name, label, value, type, placeholder) =>
      '<label>' + label + '<input data-fix-field="' + name + '" type="' + (type || 'text') + '" value="' +
      esc(String(value || '')) + '"' + (placeholder ? ' placeholder="' + placeholder + '"' : '') + ' /></label>';
    return (
      '<div class="onboarding-fix-form" role="group" aria-label="Fix skipped entry">' +
      (job.kind === 'bookmarks'
        ? field('url', 'Website', data.url, 'url', 'https://example.com') + field('title', 'Title', data.title)
        : field('site', 'Website', data.site, 'url', 'https://example.com') +
          field('username', 'Username', data.username) +
          field('password', 'Password', data.password, 'password')) +
      '<div class="onboarding-fix-actions"><button type="button" class="onboarding-fix" data-fix-save="' + index + '">' +
      (job.kind === 'bookmarks' ? 'Add bookmark' : 'Save password') +
      '</button></div></div>'
    );
  }

  function saveSkippedFix(index) {
    const job = importJob;
    const item = job && job.skips[index];
    if (!item || !fixableSkip(job, item)) return;
    const values = {};
    try {
      for (const input of step.querySelectorAll('input[data-fix-field]')) {
        values[input.dataset.fixField] = input.value;
      }
    } catch (error) {}
    let added = 0;
    if (job.kind === 'bookmarks') {
      const url = bookmarkUrl(String(values.url || '').trim());
      if (!url) {
        if (typeof toast === 'function') toast('Enter a full HTTP or HTTPS address.');
        return;
      }
      added =
        typeof addManyBookmarks === 'function'
          ? addManyBookmarks([{ url, title: String(values.title || '').trim() }])
          : 0;
      if (!added) {
        if (typeof toast === 'function') toast('That page is already saved.');
        return;
      }
    } else {
      const site = String(values.site || '').trim();
      const username = String(values.username || '').trim();
      const password = String(values.password || '');
      if (!site || !username || !password) {
        if (typeof toast === 'function') toast('Fill in the website, username and password.');
        return;
      }
      added = importPasswords([{ site, username, password }]);
      if (!added) {
        if (typeof toast === 'function') toast('That password could not be saved.');
        return;
      }
    }
    job.added += added;
    job.skipped = Math.max(0, job.total - job.added);
    job.skipReasons[item.reason] = Math.max(0, (job.skipReasons[item.reason] || 1) - 1);
    item.fixed = true;
    job.fixing = null;
    if (typeof toast === 'function') toast(job.kind === 'bookmarks' ? 'Bookmark added.' : 'Password saved.');
    renderStep();
  }

  // Internal entry for atlas screens that are not in the numbered chain yet.
  // S-002 exits are connected separately; until then this lets the flow and
  // automated checks render the real screen without a dead-end transition.
  // S-005 accepts the real handoff the wiring will pass: { sourceId, kind, text }.
  // s-007 — sync intro (route vaayvu://onboarding/s-007, phase p00).
  // Both actions open the real sync sheets: Create a Vaayvu ID registers on the
  // chosen server, Pair this device signs in to an existing ID. Private windows
  // and India-only browsing cannot sync, so the screen explains that instead of
  // offering buttons that would refuse.
  function renderSyncIntro() {
    const available = typeof sync !== 'undefined' && !!sync;
    const ordinary = currentSetting('ordinaryWeb', true) !== false;
    const connected = syncConnected();
    const skip = '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">' +
      (connected ? 'Done' : 'Skip for now') + '</button></div>';
    if (connected) {
      const name = (() => {
        try {
          return sync.session && sync.session.username ? sync.session.username : 'this device';
        } catch (error) {
          return 'this device';
        }
      })();
      const origin = (() => {
        try {
          return sync.session && sync.session.origin ? sync.session.origin : '';
        } catch (error) {
          return '';
        }
      })();
      return (
        '<div class="onboarding-import-status" data-status="done"><strong>Signed in as ' + esc(name) + '</strong>' +
        '<small>' + (origin ? esc(origin) + ' · ' : '') + 'Bookmarks and open tabs sync from this device.</small></div>' +
        skip +
        '<small class="onboarding-step-label">Sync intro</small>'
      );
    }
    if (!available || !ordinary) {
      const heading = available ? 'Sync is paused' : 'Sync is not available in this build';
      const detail = available
        ? 'India-only browsing keeps bookmarks and tabs on this device. Turn on ordinary websites in Settings to use sync.'
        : 'This build did not include the Vaayvu Sync client, so there is nothing to set up here.';
      return (
        '<div class="onboarding-import-status" data-status="unavailable"><strong>' + heading + '</strong>' +
        '<small>' + detail + '</small></div>' +
        skip +
        '<small class="onboarding-step-label">Sync intro</small>'
      );
    }
    return (
      '<ul class="onboarding-values">' +
      '<li>Bookmarks and open tabs on your other devices</li>' +
      '<li>Your own Vaayvu sync server — no third-party account</li>' +
      '<li>Private tabs and history stay off the server</li>' +
      '</ul>' +
      '<div class="onboarding-choices">' +
      '<button type="button" class="onboarding-choice" data-onboard="create-id">' +
      '<strong>Create a Vaayvu ID</strong><small>Set up sync with a server address and a password you choose</small></button>' +
      '<button type="button" class="onboarding-choice" data-onboard="sync">' +
      '<strong>Pair this device</strong><small>Sign in with a Vaayvu ID you already use</small></button>' +
      '</div>' +
      skip +
      '<small class="onboarding-step-label">Sync intro</small>'
    );
  }

  // s-008 — create account (route vaayvu://onboarding/s-008, phase p00).
  // The v1 atlas lists email link, passkey and SSO. Their screens are built
  // now; the server endpoints connect later. The working registration sheet
  // stays available underneath.
  const CREATE_METHODS = [
    ['email', 'Email link', 'Create your ID with a link sent to your email'],
    ['passkey', 'Passkey', 'Use Face ID, Touch ID or your device PIN'],
    ['sso', 'SSO', 'Continue with your organisation’s identity provider'],
  ];

  function renderCreateAccount() {
    const available = typeof sync !== 'undefined' && !!sync;
    const ordinary = currentSetting('ordinaryWeb', true) !== false;
    const connected = syncConnected();
    if (connected) {
      const name = (() => {
        try {
          return sync.session && sync.session.username ? sync.session.username : 'this device';
        } catch (error) {
          return 'this device';
        }
      })();
      return (
        '<div class="onboarding-import-status" data-status="done"><strong>Already signed in as ' + esc(name) + '</strong>' +
        '<small>This device is already paired with a Vaayvu ID. Sign out first to create another one.</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-primary" data-onboard="back">Done</button></div>' +
        '<small class="onboarding-step-label">Create account</small>'
      );
    }
    if (!available || !ordinary) {
      const heading = available ? 'Account creation is paused' : 'Sync is not available in this build';
      const detail = available
        ? 'India-only browsing keeps this browser on the device. Turn on ordinary websites in Settings to create a Vaayvu ID.'
        : 'This build did not include the Vaayvu Sync client, so there is no account to create.';
      return (
        '<div class="onboarding-import-status" data-status="unavailable"><strong>' + heading + '</strong>' +
        '<small>' + detail + '</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
        '<small class="onboarding-step-label">Create account</small>'
      );
    }
    return (
      '<div class="onboarding-methods" role="list">' +
      CREATE_METHODS.map(
        ([id, name, detail]) =>
          '<button type="button" class="onboarding-method is-selectable' +
          (authMethod === id ? ' is-selected' : '') +
          '" role="listitem" data-onboard="auth-method" data-method="' +
          id +
          '" aria-pressed="' +
          (authMethod === id) +
          '"><span class="onboarding-method-copy"><strong>' +
          name +
          '</strong><small>' +
          detail +
          '</small></span><span class="onboarding-method-state">' +
          (authMethod === id ? 'Chosen' : 'Choose') +
          '</span></button>',
      ).join('') +
      '</div>' +
      (authMethod
        ? renderAuthDetail('create')
        : '<div class="onboarding-import-status" data-status="idle"><strong>Create a Vaayvu ID with a password</strong>' +
          '<small>Or choose email link, passkey or SSO above. Those screens are built; their endpoints connect later.</small></div>') +
      '<div class="onboarding-choices">' +
      '<button type="button" class="onboarding-choice" data-onboard="create-id"><strong>Create a Vaayvu ID</strong>' +
      '<small>Open the registration sheet</small></button></div>' +
      '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
      '<small class="onboarding-step-label" role="status">' + esc(authMessage || 'Create account') + '</small>'
    );
  }

  // s-009 — sign in (route vaayvu://onboarding/s-009, phase p00).
  // The atlas lists passkey, email link, TOTP and recovery codes. The current
  // Vaayvu Sync server authenticates with Vaayvu ID + password only, so each
  // method is shown with its real availability and the working sheet is the
  // sign-in path offered underneath.
  const SIGN_IN_METHODS = [
    ['passkey', 'Passkey', 'Use Face ID, Touch ID or your device PIN'],
    ['email', 'Email link', 'Get a one-time sign-in link'],
    ['totp', 'Authenticator code', 'A 6-digit code from your authenticator app'],
    ['recovery', 'Recovery code', 'A saved recovery code'],
  ];

  // s-008 / s-009 method sheets. The screens are complete now; the server
  // endpoints are connected later, so every success state says "preview".
  function renderAuthDetail(mode) {
    const list = mode === 'create' ? CREATE_METHODS : SIGN_IN_METHODS;
    const entry = list.find(([id]) => id === authMethod);
    if (!entry) return '';
    const [id, name] = entry;
    const done = authStep === 'sent' || authStep === 'ready';
    let heading = name;
    let detail = '';
    let action = '';
    if (authStep === 'sent') {
      heading = 'Check your email';
      detail = 'A sign-in link would arrive at the address you entered. This preview does not send mail yet.';
    } else if (authStep === 'ready') {
      heading = name + ' ready';
      detail = 'The screen is complete. The account and sign-in endpoints are connected in a later step.';
    } else if (mode === 'create' && id === 'email') {
      detail = 'Enter the email that should receive the account link.';
      action =
        '<label class="onboarding-authfield"><span>Email</span><input type="email" data-auth-email placeholder="you@example.com" autocomplete="email"></label>' +
        '<button type="button" class="onboarding-primary" data-onboard="auth-send-link">Send link</button>';
    } else if (mode === 'create' && id === 'passkey') {
      detail = 'Create a passkey with Face ID, Touch ID or your device PIN.';
      action = '<button type="button" class="onboarding-primary" data-onboard="auth-passkey">Create passkey</button>';
    } else if (mode === 'create' && id === 'sso') {
      detail = 'Choose your organisation’s identity provider.';
      action =
        '<div class="onboarding-authproviders">' +
        ['Google', 'Microsoft', 'GitHub', 'Okta']
          .map(
            (provider) =>
              '<button type="button" data-onboard="auth-sso" data-provider="' +
              provider +
              '">' +
              provider +
              '</button>',
          )
          .join('') +
        '</div>';
    } else if (mode === 'signin' && id === 'passkey') {
      detail = 'Use the passkey saved for this Vaayvu ID.';
      action = '<button type="button" class="onboarding-primary" data-onboard="auth-passkey">Use passkey</button>';
    } else if (mode === 'signin' && id === 'email') {
      detail = 'We would email a one-time sign-in link.';
      action =
        '<label class="onboarding-authfield"><span>Email</span><input type="email" data-auth-email placeholder="you@example.com" autocomplete="email"></label>' +
        '<button type="button" class="onboarding-primary" data-onboard="auth-send-link">Send link</button>';
    } else if (mode === 'signin' && id === 'totp') {
      detail = 'Enter the 6-digit code from your authenticator app.';
      action =
        '<label class="onboarding-authfield"><span>Code</span><input type="text" data-auth-code inputmode="numeric" maxlength="6" placeholder="000000" autocomplete="one-time-code"></label>' +
        '<button type="button" class="onboarding-primary" data-onboard="auth-verify-code">Verify code</button>';
    } else if (mode === 'signin' && id === 'recovery') {
      detail = 'Enter one saved recovery code.';
      action =
        '<label class="onboarding-authfield"><span>Recovery code</span><input type="text" data-auth-recovery placeholder="XXXX-XXXX" autocomplete="off"></label>' +
        '<button type="button" class="onboarding-primary" data-onboard="auth-use-recovery">Use recovery code</button>';
    }
    return (
      '<div class="onboarding-authdetail" data-auth-method="' +
      id +
      '">' +
      '<div class="onboarding-import-status" data-status="' +
      (authError ? 'invalid' : done ? 'done' : 'idle') +
      '"><strong>' +
      heading +
      '</strong><small>' +
      (authError ? authError : detail) +
      '</small></div>' +
      (done ? '' : action) +
      '<div class="onboarding-actions">' +
      (done ? '<button type="button" class="onboarding-primary" data-onboard="auth-back">Back to methods</button>' : '') +
      '<button type="button" class="onboarding-skip" data-onboard="auth-back">' +
      (done ? 'Done' : 'Change method') +
      '</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(authMessage || (done ? 'Preview complete. No account was created or signed in.' : 'Screen preview; endpoints connect later.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderSignIn() {
    const available = typeof sync !== 'undefined' && !!sync;
    const ordinary = currentSetting('ordinaryWeb', true) !== false;
    const connected = syncConnected();
    if (connected) {
      const name = (() => {
        try {
          return sync.session && sync.session.username ? sync.session.username : 'this device';
        } catch (error) {
          return 'this device';
        }
      })();
      return (
        '<div class="onboarding-import-status" data-status="done"><strong>Signed in as ' + esc(name) + '</strong>' +
        '<small>This device is already paired with your Vaayvu ID.</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-primary" data-onboard="back">Done</button></div>' +
        '<small class="onboarding-step-label">Sign in</small>'
      );
    }
    if (!available || !ordinary) {
      const heading = available ? 'Sign-in is paused' : 'Sync is not available in this build';
      const detail = available
        ? 'India-only browsing keeps this browser on the device. Turn on ordinary websites in Settings to sign in.'
        : 'This build did not include the Vaayvu Sync client, so there is nothing to sign in to.';
      return (
        '<div class="onboarding-import-status" data-status="unavailable"><strong>' + heading + '</strong>' +
        '<small>' + detail + '</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
        '<small class="onboarding-step-label">Sign in</small>'
      );
    }
    return (
      '<div class="onboarding-methods" role="list">' +
      SIGN_IN_METHODS.map(
        ([id, name, detail]) =>
          '<button type="button" class="onboarding-method is-selectable' +
          (authMethod === id ? ' is-selected' : '') +
          '" role="listitem" data-onboard="auth-method" data-method="' +
          id +
          '" aria-pressed="' +
          (authMethod === id) +
          '"><span class="onboarding-method-copy"><strong>' +
          name +
          '</strong><small>' +
          detail +
          '</small></span><span class="onboarding-method-state">' +
          (authMethod === id ? 'Chosen' : 'Choose') +
          '</span></button>',
      ).join('') +
      '</div>' +
      (authMethod
        ? renderAuthDetail('signin')
        : '<div class="onboarding-import-status" data-status="idle"><strong>Sign in with your Vaayvu ID</strong>' +
          '<small>Or choose a passkey, email link, authenticator code or recovery code above. Those screens are built; their endpoints connect later.</small></div>') +
      '<div class="onboarding-choices">' +
      '<button type="button" class="onboarding-choice" data-onboard="sync"><strong>Sign in with a Vaayvu ID</strong>' +
      '<small>Open the secure sign-in sheet</small></button></div>' +
      '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
      '<small class="onboarding-step-label" role="status">' + esc(authMessage || 'Sign in') + '</small>'
    );
  }

  // s-010 — recovery phrase (route vaayvu://onboarding/s-010, phase p00).
  // No phrase is ever invented: the flow renders only when the sync layer
  // hands over a real 24-word phrase. Today Vaayvu Sync accounts have no
  // phrase, so production shows the honest unavailable state. When the server
  // starts issuing one, the same copy / print / confirm-three-words / lost
  // flow works unchanged.
  const PREVIEW_PHRASE = [
    'harbor', 'cedar', 'lantern', 'meadow', 'copper', 'willow', 'signal', 'pebble',
    'orchard', 'mantle', 'ripple', 'cobalt', 'thistle', 'marble', 'brisk', 'hollow',
    'saffron', 'glacier', 'tunnel', 'velvet', 'bramble', 'dune', 'kestrel', 'lumen',
  ];

  function resetRecoveryPhrase() {
    phraseState = null;
  }

  function recoveryUnavailable(reason) {
    return (
      '<div class="onboarding-import-status" data-status="unavailable"><strong>' +
      (reason || 'Recovery phrases are not available for Vaayvu Sync accounts in this build.') +
      '</strong><small>Accounts sign in with a Vaayvu ID and password. Without a recovery phrase, a forgotten password cannot be restored on this device.</small></div>' +
      '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
      '<small class="onboarding-step-label">Recovery phrase</small>'
    );
  }

  function renderRecoveryPhrase() {
    if (!phraseState) return recoveryUnavailable();
    if (phraseState.stage === 'invalid')
      return recoveryUnavailable('That recovery phrase has ' + phraseState.count + ' words; 24 are required.');
    if (phraseState.stage === 'lost') {
      return (
        '<div class="onboarding-import-status" data-status="invalid"><strong>Without the 24 words, this Vaayvu ID cannot be recovered</strong>' +
        '<small>There is no password reset that restores the same account. You can create a new Vaayvu ID and start fresh, or go back to your phrase if you still have it written down.</small></div>' +
        '<div class="onboarding-choices">' +
        '<button type="button" class="onboarding-choice" data-onboard="create-id"><strong>Create a new Vaayvu ID</strong>' +
        '<small>Start a new account with a fresh password</small></button></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-phrase="show">Back to my phrase</button>' +
        '<button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
        '<small class="onboarding-step-label">Recovery phrase</small>'
      );
    }
    if (phraseState.stage === 'done') {
      return (
        '<div class="onboarding-import-status" data-status="done"><strong>Recovery phrase confirmed</strong>' +
        '<small>Keep the written words somewhere safe. Anyone with them can sign in to this Vaayvu ID.</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-primary" data-onboard="back">Done</button></div>' +
        '<small class="onboarding-step-label">Recovery phrase</small>'
      );
    }
    if (phraseState.stage === 'confirm') {
      const wrong = Array.isArray(phraseState.wrong) ? phraseState.wrong : [];
      return (
        '<div class="onboarding-confirm">' +
        '<p class="onboarding-confirm-lead">Type three words from your phrase to confirm you wrote them down.</p>' +
        phraseState.positions
          .map(
            (position) =>
              '<label>Word ' + position + '<input data-phrase-word="' + position + '" autocomplete="off" autocapitalize="none" spellcheck="false" /></label>',
          )
          .join('') +
        (wrong.length
          ? '<p class="onboarding-error" role="alert">Words ' + wrong.join(', ') + ' do not match. Check your written phrase.</p>'
          : '') +
        '</div>' +
        '<div class="onboarding-actions">' +
        '<button type="button" class="onboarding-primary" data-phrase="verify">Confirm</button>' +
        '<button type="button" class="onboarding-skip" data-phrase="show">Back to the words</button>' +
        '</div>' +
        '<small class="onboarding-step-label">Recovery phrase</small>'
      );
    }
    const canPrint = typeof window !== 'undefined' && typeof window.print === 'function';
    return (
      (phraseState.preview
        ? '<div class="onboarding-import-status" data-status="idle"><strong>Preview phrase</strong>' +
          '<small>Sample words for this screen, not tied to an account. Real phrases arrive from the sync server later.</small></div>'
        : '') +
      '<p class="onboarding-confirm-lead">24 words, in order.</p>' +
      '<ol class="onboarding-words">' +
      phraseState.words
        .map((word, index) => '<li><small>' + (index + 1) + '</small><strong>' + esc(word) + '</strong></li>')
        .join('') +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-phrase="confirm">Continue</button>' +
      '<div class="onboarding-phrase-tools">' +
      '<button type="button" class="onboarding-check-act" data-phrase="copy">Copy</button>' +
      (canPrint ? '<button type="button" class="onboarding-check-act" data-phrase="print">Print</button>' : '') +
      '<button type="button" class="onboarding-check-act" data-phrase="lost">I lost it</button>' +
      '</div>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Recovery phrase</small>'
    );
  }

  function pickConfirmPositions() {
    const positions = [];
    while (positions.length < 3) {
      const position = 1 + Math.floor(Math.random() * phraseState.words.length);
      if (!positions.includes(position)) positions.push(position);
    }
    return positions.sort((a, b) => a - b);
  }

  function copyRecoveryPhrase() {
    const text = phraseState ? phraseState.words.join(' ') : '';
    if (!text) return;
    try {
      if (typeof navigator !== 'undefined' && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        navigator.clipboard.writeText(text).then(
          () => { if (typeof toast === 'function') toast(phraseState && phraseState.preview ? 'Preview phrase copied.' : 'Recovery phrase copied.'); },
          () => { if (typeof toast === 'function') toast('Copy is not available on this device.'); },
        );
        return;
      }
    } catch (error) {}
    if (typeof toast === 'function') toast('Copy is not available on this device.');
  }

  function verifyRecoveryWords() {
    if (!phraseState || phraseState.stage !== 'confirm') return;
    const answers = [];
    try {
      for (const input of step.querySelectorAll('input[data-phrase-word]')) {
        answers.push({ position: Number(input.dataset.phraseWord), value: String(input.value || '') });
      }
    } catch (error) {}
    const wrong = answers
      .filter((answer) => answer.value.trim().toLowerCase() !== phraseState.words[answer.position - 1])
      .map((answer) => answer.position);
    if (wrong.length) {
      phraseState.wrong = wrong;
      renderStep();
      return;
    }
    phraseState.wrong = [];
    phraseState.stage = 'done';
    renderStep();
  }

  // s-013 — feature tour (route vaayvu://onboarding/s-013, phase p00).
  // Five real stops, filtered by what the device actually has: libraries always
  // have the omnibox and tabs; spaces depend on the space store; the sidebar is
  // desktop-only; the page-Q&A step needs the sync client (its own note says a
  // connected server with a model is required). No mock screenshots — each stop
  // is one accurate sentence.
  function tourSteps() {
    const steps = [
      {
        id: 'omnibox',
        title: 'Omnibox',
        icon: 'search',
        detail: 'One bar for searches and addresses. Suggestions come from your bookmarks and history, and stay on this device.',
      },
      {
        id: 'tabs',
        title: 'Tabs',
        icon: 'tabs',
        detail: 'Open tabs sit across the top or down the sidebar. Pin, split or close them from the tab menu.',
      },
    ];
    steps.push({
      id: 'spaces',
      title: 'Spaces',
      icon: 'layers',
      detail: 'Spaces keep separate tabs, pinned pages and an accent colour for work, study or personal browsing.',
    });
    steps.push({
      id: 'sidebar',
      title: 'Sidebar',
      icon: 'panel',
      detail: 'On desktop the sidebar holds tabs, spaces and tools. Keep it open, let it auto-hide, or close it in Settings.',
    });
    steps.push({
      id: 'ai',
      title: 'Page Q&A',
      icon: 'spark',
      detail: 'In Page tools, Ask about this page sends your question and a page excerpt to your Vaayvu sync server and its configured model. Connect sync to use it.',
    });
    return steps;
  }

  function tourIcon(name) {
    try {
      if (typeof icon === 'function') return icon(name);
    } catch (error) {}
    return '<span aria-hidden="true">' + esc(String(name || '?').slice(0, 1).toUpperCase()) + '</span>';
  }

  function renderFeatureTour() {
    const steps = tourSteps();
    const index = Math.max(0, Math.min(tourStep, steps.length - 1));
    const step = steps[index];
    if (!step) {
      return (
        '<div class="onboarding-import-status" data-status="unavailable"><strong>The tour has no stops on this device</strong>' +
        '<small>This build did not report any tour features.</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
        '<small class="onboarding-step-label">Feature tour</small>'
      );
    }
    return (
      '<div class="onboarding-tour">' +
      '<span class="onboarding-tour-icon" aria-hidden="true">' + tourIcon(step.icon) + '</span>' +
      '<strong class="onboarding-tour-title">' + esc(step.title) + '</strong>' +
      '<p class="onboarding-tour-detail">' + esc(step.detail) + '</p>' +
      '<div class="onboarding-tour-dots" aria-hidden="true">' +
      steps
        .map((item, dot) => '<span class="onboarding-tour-dot" data-active="' + (dot === index) + '"></span>')
        .join('') +
      '</div>' +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-tour="next">' + (index === steps.length - 1 ? 'Done' : 'Next') + '</button>' +
      '<button type="button" class="onboarding-skip" data-tour="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step ' + (index + 1) + ' of ' + steps.length + ' · ' + esc(step.title) + '</small>'
    );
  }

  // s-014 — notification primer (route vaayvu://onboarding/s-014, phase p00).
  // Notifications are only used for page reminders, a capability mobile builds
  // report as canPageReminder. The primer explains that before the real OS
  // prompt and never claims permission was granted — the native layer shows the
  // system prompt and reports back through its own notice.
  function renderNotificationPrimer() {
    if (!has('canPageReminder')) {
      return (
        '<div class="onboarding-import-status" data-status="unavailable"><strong>Notifications are not used in this build</strong>' +
        '<small>Page reminders and their notification permission are available in the Apple and Android apps.</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-skip" data-onboard="back">Back</button></div>' +
        '<small class="onboarding-step-label">Notification primer</small>'
      );
    }
    if (notificationPrimerAsked) {
      return (
        '<div class="onboarding-import-status" data-status="idle"><strong>Your device is asking now</strong>' +
        '<small>Allow notifications in the system prompt to receive page reminders. You can change this later in your device settings.</small></div>' +
        '<div class="onboarding-actions"><button type="button" class="onboarding-primary" data-onboard="back">Done</button></div>' +
        '<small class="onboarding-step-label">Notification primer</small>'
      );
    }
    return (
      '<ul class="onboarding-values">' +
      '<li>A reminder opens the page you saved</li>' +
      '<li>No marketing and no background messages</li>' +
      '<li>You can change permission any time in device settings</li>' +
      '</ul>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="request-notifications">Enable notifications</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Not now</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Notification primer</small>'
    );
  }

