  function renderPrivacy() {
    const search = String(currentSetting('searchProvider', 'duckduckgo'));
    const strong = !!(activeLists() && activeLists().aggressive === true);
    const telemetry = currentSetting('telemetryConsent', false) === true;
    return (
      '<div class="onboarding-privacy">' +
      selectRow('search', 'Search engine', 'Used from the address bar', ENGINES, search) +
      '<div class="onboarding-priv"><span><strong>Shield level</strong><small>Strong also blocks same-site ad paths and YouTube ads</small></span>' +
      '<span class="onboarding-seg" role="group" aria-label="Shield level">' +
      '<button type="button" data-shield="standard" aria-pressed="' + (!strong) + '">Standard</button>' +
      '<button type="button" data-shield="strong" aria-pressed="' + strong + '">Strong</button>' +
      '</span></div>' +
      '<label class="onboarding-priv"><span><strong>Anonymous usage data</strong>' +
      '<small>Saved on this device. Reporting will begin with a future Vaayvu update.</small></span>' +
      '<input type="checkbox" data-priv="telemetry" aria-label="Anonymous usage data"' + (telemetry ? ' checked' : '') +
      ' /></label>' +
      (canDnsSettings()
        ? '<button type="button" class="onboarding-choice" data-onboard="dns">' +
          '<strong>DNS settings</strong><small>Open your device’s DNS settings</small></button>'
        : '') +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="next">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step 3 of ' + TOTAL + ' · Privacy setup</small>'
    );
  }

  function renderAppearance() {
    const theme = String(currentSetting('theme', 'system'));
    const tabPos = String(currentSetting('tabPosition', 'top'));
    const wallpaper = String(currentSetting('wallpaper', 'observatory'));
    const accents = accentIds();
    const showAccent = canAccent() && accents.length > 0;
    return (
      '<div class="onboarding-privacy">' +
      selectRow('theme', 'Theme', 'Light, dark or follow your device', THEMES, theme) +
      (canTabOrientation()
        ? selectRow('tab', 'Tab position', 'Where the desktop tab strip sits', POSITIONS, tabPos)
        : '') +
      (showAccent
        ? selectRow('accent', 'Accent', 'The colour theme of this space', accents.map((id) => [id, accentName(id)]), currentAccent())
        : '') +
      selectRow('wallpaper', 'Wallpaper', 'Background behind your start page', WALLPAPERS, wallpaper) +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="next">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step 4 of ' + TOTAL + ' · Appearance setup</small>'
    );
  }

  function checklistRows() {
    const rows = [];
    rows.push({
      key: 'import',
      title: 'Import bookmarks',
      detail: 'Bring bookmarks over from your old browser',
      action: 'import',
      label: 'Import',
      done: bookmarkCount() > 0,
      doneLabel: 'Imported',
    });
    if (canSync()) {
      rows.push({
        key: 'sync',
        title: 'Sync with Vaayvu ID',
        detail: 'Keep bookmarks and open tabs on your other devices',
        action: 'sync',
        label: 'Sign in',
        done: syncConnected(),
        doneLabel: 'Signed in',
      });
    }
    if (canDefaultBrowser()) {
      rows.push({
        key: 'default',
        title: 'Set Vaayvu as default',
        detail: 'Links from apps and messages open in Vaayvu',
        action: 'default',
        label: 'Open settings',
        // The OS owns this setting and the page cannot read it back, so this
        // row never shows a completion mark.
        done: false,
        doneLabel: '',
      });
    }
    if (canImportPasswords()) {
      const saved = savedPasswordCount();
      rows.push({
        key: 'password',
        title: 'Import passwords',
        detail: 'Add sign-ins from a browser password CSV file',
        action: 'password',
        label: saved ? 'Import more' : 'Choose file',
        done: saved > 0,
        doneLabel: saved + ' saved',
      });
    }
    if (canExtensions()) {
      rows.push({
        key: 'extension',
        title: 'Add an extension',
        detail: 'Change how sites look with a style extension',
        action: 'extension',
        label: 'Browse',
        done: extensionCount() > 0,
        doneLabel: 'Added',
      });
    }
    return rows;
  }

  function renderChecklist() {
    const rows = checklistRows();
    return (
      '<div class="onboarding-checklist" role="list">' +
      rows
        .map(
          (row) =>
            '<div class="onboarding-check" role="listitem" data-done="' + (row.done ? 'true' : 'false') + '">' +
            '<span class="onboarding-check-mark" aria-hidden="true">' + (row.done ? '✓' : '') + '</span>' +
            '<span class="onboarding-check-copy"><strong>' + row.title + '</strong><small>' + row.detail + '</small></span>' +
            (row.done
              ? '<span class="onboarding-check-state">' + row.doneLabel + '</span>'
              : '<button type="button" class="onboarding-check-act" data-carry="' + row.action + '">' + row.label + '</button>') +
            '</div>',
        )
        .join('') +
      '</div>' +
      '<input type="file" accept=".csv,text/csv" data-import-passwords hidden />' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="next">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step 5 of ' + TOTAL + ' · Onboarding checklist</small>'
    );
  }

  function esc(value) {
    return String(value).replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  }
  function siteName(url) {
    const match = String(url).match(/^[a-z][a-z0-9+.-]*:\/\/([^/?#]+)/i);
    return match ? match[1].replace(/^www\./i, '') : '';
  }
  function readingCount() {
    try {
      const list = typeof read === 'function' ? read('reading', []) : [];
      return Array.isArray(list) ? list.length : 0;
    } catch (error) {
      return 0;
    }
  }
  function favoriteTiles() {
    try {
      if (typeof favorites === 'undefined' || !Array.isArray(favorites)) return [];
      return favorites.filter((item) => item && typeof item.url === 'string').slice(0, 6);
    } catch (error) {
      return [];
    }
  }

  // s-051 previews the real start page: the logo and wordmark, the chosen
  // search engine, the actual favorite tiles (favorites default to the four
  // built-in shortcuts) and the real saved-page count. Nothing here is a
  // placeholder control — the only input is the search engine, which commits
  // through VaayvuPreferences exactly like s-011.
  function renderStart() {
    const search = String(currentSetting('searchProvider', 'duckduckgo'));
    const showSearch = !!pref();
    const tiles = favoriteTiles();
    const showShortcuts = typeof favorites !== 'undefined' && Array.isArray(favorites);
    const showReading = typeof read === 'function';
    const saved = readingCount();
    return (
      '<div class="onboarding-start">' +
      '<div class="onboarding-start-hero">' +
      '<img src="assets/vaayvu.svg" width="40" height="40" alt="" />' +
      '<span class="onboarding-start-word">Vaayvu</span>' +
      '</div>' +
      (showSearch
        ? selectRow('search', 'Search engine', 'Used by the start page and the address bar', ENGINES, search)
        : '') +
      (showShortcuts
        ? '<div class="onboarding-start-block"><span class="onboarding-start-head"><strong>Shortcuts</strong>' +
          '<small>Your favorites sit under the search bar</small></span>' +
          (tiles.length
            ? '<div class="onboarding-tiles">' +
              tiles
                .map(
                  (item) =>
                    '<span class="onboarding-tile"><span class="onboarding-tile-mark" aria-hidden="true">' +
                    esc((item.title || siteName(item.url) || '?').slice(0, 1).toUpperCase()) +
                    '</span><small>' + esc(item.title || siteName(item.url)) + '</small></span>',
                )
                .join('') +
              '</div>'
            : '<small class="onboarding-start-empty">Add favorites from the start page at any time.</small>') +
          '</div>'
        : '') +
      (showReading
        ? '<div class="onboarding-start-block"><span class="onboarding-start-head"><strong>Reading list</strong>' +
          '<small>' +
          (saved
            ? saved + (saved === 1 ? ' page saved' : ' pages saved') + ' · open it from the start page'
            : 'Save pages to read later from any site') +
          '</small></span></div>'
        : '') +
      '</div>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="finish">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="back">Back</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Step ' + TOTAL + ' of ' + TOTAL + ' · Start default</small>'
    );
  }

  function renderCrashRestore() {
    const info = crashRestoreInfo();
    if (!info) return '';
    const shown = info.tabs.slice(0, 6);
    const more = info.tabs.length - shown.length;
    const count = info.tabs.length;
    return (
      '<div class="onboarding-restore">' +
      '<div class="onboarding-restore-banner">' +
      '<span class="onboarding-restore-badge" aria-hidden="true">↻</span>' +
      '<div><strong>' +
      count +
      (count === 1 ? ' tab was open' : ' tabs were open') +
      '</strong><small>Vaayvu closed before the last session finished.</small></div>' +
      '</div>' +
      '<div class="onboarding-restore-list" role="list" aria-label="Tabs from the last session">' +
      shown
        .map(
          (item) =>
            '<div class="onboarding-restore-tab" role="listitem">' +
            '<span class="onboarding-restore-mark" aria-hidden="true">' +
            esc((item.title || item.host || '?').slice(0, 1).toUpperCase()) +
            '</span>' +
            '<span class="onboarding-restore-copy"><strong>' +
            esc(item.title) +
            '</strong><small>' +
            esc(item.host) +
            '</small></span>' +
            '</div>',
        )
        .join('') +
      '</div>' +
      (more > 0
        ? '<p class="onboarding-restore-more">and ' + more + (more === 1 ? ' more tab' : ' more tabs') + '</p>'
        : '') +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-crash="restore">Restore ' +
      count +
      (count === 1 ? ' tab' : ' tabs') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-crash="discard">Discard</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Restoring opens these pages in this window. Nothing is restored until you choose.</small>' +
      '</div>'
    );
  }

  function renderSafeMode() {
    const info = safeModeInfo();
    if (!info) return '';
    const detail = info.reason
      ? info.reason
      : info.crashes
        ? 'Vaayvu did not finish starting ' +
          info.crashes +
          (info.crashes === 1 ? ' time' : ' times') +
          ' in a row.'
        : 'The previous session did not close normally.';
    const extensionLine = info.extensions
      ? 'Turn off ' +
        info.extensions +
        (info.extensions === 1 ? ' style extension' : ' style extensions') +
        '. Your packages stay installed.'
      : 'No style extensions are installed.';
    const resetForm = safeConfirm
      ? '<div class="onboarding-safe-confirm" role="alert">' +
        '<strong>Reset browser settings?</strong>' +
        '<p>Settings and Rasha Shield rules return to their defaults, and style extensions are disabled. Bookmarks, passwords, history, tabs and downloads stay.</p>' +
        '<div class="onboarding-safe-confirm-actions">' +
        '<button type="button" class="onboarding-danger" data-safe="reset-confirm">Reset browser</button>' +
        '<button type="button" class="onboarding-skip" data-safe="reset-cancel">Cancel</button>' +
        '</div></div>'
      : '';
    return (
      '<div class="onboarding-safe">' +
      '<div class="onboarding-safe-banner">' +
      '<span class="onboarding-safe-mark" aria-hidden="true">!</span>' +
      '<div><strong>Vaayvu did not start cleanly</strong><small>' +
      esc(detail) +
      '</small></div>' +
      '</div>' +
      (safeConfirm
        ? resetForm
        : '<div class="onboarding-safe-options">' +
          '<button type="button" class="onboarding-safe-option" data-safe="extensions"' +
          (info.extensions ? '' : ' disabled') +
          '>' +
          '<span><strong>Disable extensions</strong><small>' +
          esc(extensionLine) +
          '</small></span>' +
          '<span class="onboarding-safe-arrow" aria-hidden="true">→</span>' +
          '</button>' +
          '<button type="button" class="onboarding-safe-option" data-safe="reset">' +
          '<span><strong>Reset browser settings</strong><small>Restore default settings and shield rules. Your saved pages and passwords stay.</small></span>' +
          '<span class="onboarding-safe-arrow" aria-hidden="true">→</span>' +
          '</button>' +
          '</div>' +
          '<div class="onboarding-actions">' +
          '<button type="button" class="onboarding-primary" data-safe="continue">Continue</button>' +
          '</div>') +
      '<small class="onboarding-step-label">Nothing changes until you choose. Tabs, bookmarks and passwords are still here.</small>' +
      '</div>'
    );
  }

