  const RAIL_ITEMS = ['Figma', 'Notion', 'Linear', 'MDN', 'Ars Technica', 'Observatory', 'GitHub'];

  function renderVerticalRail() {
    const designOpen = railDesignOpen;
    const researchOpen = railResearchOpen;
    const groupHead = (name, open, action, count) =>
      '<button type="button" class="vrail-group-head" data-onboard="' +
      action +
      '" aria-expanded="' +
      open +
      '">' +
      '<span class="vrail-chevron" aria-hidden="true">' +
      (open ? '&#9662;' : '&#9656;') +
      '</span>' +
      '<span class="vrail-label">' +
      name +
      '</span>' +
      '<span class="vrail-count">' +
      count +
      '</span>' +
      '</button>';
    const child = (label, fav, active, index) =>
      '<span class="vrail-child' +
      (active || railSelected === index ? ' is-active' : '') +
      '" role="treeitem" data-rail-item="' + index + '"' +
      (railSelected === index ? ' aria-selected="true"' : '') +
      '><span class="vrail-fav" aria-hidden="true">' +
      fav +
      '</span><span class="vrail-label">' +
      label +
      '</span></span>';
    return (
      '<div class="onboarding-vrail">' +
      '<div class="vrail-stage' +
      (railCollapsed ? ' is-collapsed' : '') +
      '">' +
      '<div class="vrail" role="tree" aria-label="Vertical tab rail" style="width:' + (railCollapsed ? 58 : railWidth) + 'px">' +
      '<div class="vrail-head">' +
      '<span class="vrail-space"><span class="vrail-avatar" aria-hidden="true">W</span><span class="vrail-space-name">Work</span></span>' +
      '<button type="button" class="vrail-collapse" data-onboard="rail-collapse" aria-label="' +
      (railCollapsed ? 'Expand rail' : 'Collapse rail') +
      '">' +
      (railCollapsed ? '&#8250;' : '&#8249;') +
      '</button>' +
      '</div>' +
      '<div class="vrail-resizer" role="separator" aria-orientation="vertical" tabindex="0" data-rail-resize aria-label="Resize rail" aria-valuemin="180" aria-valuemax="360" aria-valuenow="' + railWidth + '"></div>' +
      '<div class="vrail-tree">' +
      '<div class="vrail-group" role="treeitem" aria-expanded="' +
      designOpen +
      '">' +
      groupHead('Design', designOpen, 'rail-design', '3') +
      (designOpen
        ? '<div class="vrail-children" role="group">' +
          child('Figma', 'F', true, 0) +
          child('Notion', 'N', false, 1) +
          child('Linear', 'L', false, 2) +
          '</div>'
        : '') +
      '</div>' +
      '<div class="vrail-group" role="treeitem" aria-expanded="' +
      researchOpen +
      '">' +
      groupHead('Research', researchOpen, 'rail-research', '4') +
      (researchOpen
        ? '<div class="vrail-children" role="group">' +
          child('MDN', 'M', false, 3) +
          child('Ars Technica', 'A', false, 4) +
          '</div>'
        : '') +
      '</div>' +
      '<span class="vrail-tab' + (railSelected === 5 ? ' is-active' : '') + '" role="treeitem" data-rail-item="5"' + (railSelected === 5 ? ' aria-selected="true"' : '') + '><span class="vrail-fav" aria-hidden="true">O</span><span class="vrail-label">Observatory</span></span>' +
      '<span class="vrail-tab' + (railSelected === 6 ? ' is-active' : '') + '" role="treeitem" data-rail-item="6"' + (railSelected === 6 ? ' aria-selected="true"' : '') + '><span class="vrail-fav" aria-hidden="true">G</span><span class="vrail-label">GitHub</span></span>' +
      '</div>' +
      '<div class="vrail-spaces" aria-label="Spaces">' +
      '<span class="vrail-space-dot is-active" title="Personal">P</span>' +
      '<span class="vrail-space-dot" title="Work">W</span>' +
      '<span class="vrail-space-dot" title="Study">S</span>' +
      '</div>' +
      '</div>' +
      '<div class="vrail-content" aria-hidden="true">' +
      '<span class="vrail-content-pill">Page content</span>' +
      '<span class="vrail-content-line"></span>' +
      '<span class="vrail-content-line short"></span>' +
      '</div>' +
      '</div>' +
            '<div class="vrail-sheet"' + (railSheetOpen ? '' : ' hidden') + '><strong>Compact rail sheet</strong><span>Saved location: ' + (railSavedLocation ? esc(railSavedLocation) : 'none yet') + '</span></div>' +
      (railMessage ? '<div class="sx-note"><strong>Rail</strong><span>' + esc(railMessage) + '</span></div>' : '') +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Tree</strong><span>Tabs sit under the page that opened them.</span></li>' +
      '<li><strong>02 Groups</strong><span>Fold a group without losing its tabs.</span></li>' +
      '<li><strong>03 Spaces</strong><span>Switch Personal, Work and Study at the foot.</span></li>' +
      '<li><strong>04 Collapse</strong><span>Narrow the rail to icons; every target stays.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" data-onboard="rail-narrow">Narrow rail</button>' +
      '<button type="button" data-onboard="rail-wide">Widen rail</button>' +
      '<button type="button" data-onboard="rail-save-location">Save selected location</button>' +
      '<button type="button" data-onboard="rail-sheet">' + (railSheetOpen ? 'Hide compact sheet' : 'Open compact sheet') + '</button>' +
      '<button type="button" class="onboarding-primary" data-onboard="rail-collapse">' +
      (railCollapsed ? 'Expand rail' : 'Collapse rail') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="rail-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Groups and collapse work in this preview.</small>' +
      '</div>'
    );
  }

