  function renderJumpList() {
    const status = jumpListMessage || 'Recent pages and tasks, one click from the taskbar.';
    const recentRow = (item) =>
      '<button type="button" class="jl-row" data-onboard="jl-recent" data-jl-name="' +
      esc(item.title) +
      '"><span class="jl-icon" aria-hidden="true">' +
      tourIcon('clock') +
      '</span><span class="jl-copy"><strong>' +
      esc(item.title) +
      '</strong><small>' +
      esc(item.host) +
      '</small></span></button>';
    const taskRow = (id, icon, name) =>
      '<button type="button" class="jl-row jl-task" data-onboard="jl-task" data-jl-task="' +
      id +
      '"><span class="jl-icon" aria-hidden="true">' +
      tourIcon(icon) +
      '</span><span class="jl-copy"><strong>' +
      name +
      '</strong></span></button>';
    return (
      '<div class="onboarding-jumplist">' +
      '<div class="jl-stage">' +
      (jumpListOpen
        ? '<div class="jl-menu" role="group" aria-label="Vaayvu jump list">' +
          '<div class="jl-head"><span class="jl-app-icon" aria-hidden="true">V</span>' +
          '<span class="jl-head-copy"><strong>Vaayvu</strong><small>Jump list</small></span></div>' +
          '<span class="jl-title">Recent</span>' +
          JUMP_LIST_RECENT.map(recentRow).join('') +
          '<span class="jl-title">Tasks</span>' +
          taskRow('newwindow', 'tabs', 'New window') +
          taskRow('private', 'private', 'New private window') +
          taskRow('newtab', 'plus', 'New tab') +
          '</div>'
        : '<button type="button" class="jl-reopen" data-onboard="jl-open">Open jump list</button>') +
      '<div class="jl-taskbar">' +
      '<button type="button" class="jl-task-icon" data-onboard="jl-taskbar" aria-expanded="' +
      jumpListOpen +
      '" aria-label="Vaayvu taskbar button"><span aria-hidden="true">V</span></button>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-jumplist">' +
      '<li><strong>01 Recent</strong><span>Recently visited pages, ready to reopen.</span></li>' +
      '<li><strong>02 Tasks</strong><span>New window, private window and a fresh tab.</span></li>' +
      '<li><strong>03 Taskbar</strong><span>The jump list belongs to the app icon, not the page.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="jl-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderMediaContext() {
    const kind = mediaKind();
    const isVideo = kind === 'video';
    const canPip = isVideo && !(
      typeof capabilities !== 'undefined' && capabilities && capabilities.canPictureInPicture === false
    );
    const canCast = !(
      typeof capabilities !== 'undefined' && capabilities && capabilities.canCast === false
    );
    const row = (id, label, key) =>
      '<button type="button" class="ctx-item" role="menuitem" data-onboard="media-item" data-media="' +
      id +
      '"><span>' +
      label +
      '</span>' +
      (key ? '<kbd>' + key + '</kbd>' : '') +
      '</button>';
    return (
      '<div class="onboarding-media">' +
      '<div class="media-stage">' +
      '<div class="media-thumb' +
      (isVideo ? ' is-video' : '') +
      '" role="img" aria-label="' +
      (isVideo ? 'Video' : 'Image') +
      ' preview">' +
      (isVideo ? '<span class="media-play" aria-hidden="true">&#9654;</span>' : '') +
      '</div>' +
      '<div class="ctx-menu media-menu" role="menu" aria-label="' +
      (isVideo ? 'Video' : 'Image') +
      ' context menu">' +
      row('save', 'Save ' + kind + '…', '⌘S') +
      row('copy', 'Copy ' + kind, '') +
      row('open', 'Open ' + kind + ' in new tab', '') +
      row('search', 'Search with DuckDuckGo', '') +
      '<span class="ctx-sep" role="separator"></span>' +
      (canPip
        ? row('pip', mediaPip ? 'Exit Picture-in-Picture' : 'Picture-in-Picture', '')
        : '') +
      (canCast ? row('cast', 'Cast…', '') : '') +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Media</strong><span>The menu belongs to the image or video under the pointer.</span></li>' +
      '<li><strong>02 Actions</strong><span>Save, copy, open and search act on that media only.</span></li>' +
      '<li><strong>03 Playback</strong><span>Picture-in-Picture and Cast stay with the video.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="media-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(mediaMessage || (isVideo ? 'Video context menu.' : 'Image context menu.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderLinkContext() {
    const status = linkContextMessage || 'Open, copy, share or send the link without leaving the page.';
    const row = (id, iconName, name, section) =>
      '<button type="button" class="lc-row" data-onboard="lc-action" data-lc="' +
      id +
      '"><span class="lc-icon" aria-hidden="true">' +
      tourIcon(iconName) +
      '</span><span class="lc-name">' +
      name +
      '</span></button>';
    return (
      '<div class="onboarding-linkcontext">' +
      '<div class="lc-stage">' +
      '<div class="lc-page">' +
      '<span class="lc-kicker">Page</span>' +
      '<p class="lc-line">Read the <span class="lc-link is-target">Vaayvu documentation</span> for shortcuts and sync.</p>' +
      '<p class="lc-line is-short">The rest of the page stays in place.</p>' +
      '<div class="lc-menu" role="menu" aria-label="Link context menu">' +
      '<span class="lc-head">vaayvu.com/docs</span>' +
      '<span class="lc-title">Open</span>' +
      row('newtab', 'tabs', 'Open link in new tab') +
      row('newwindow', 'panel', 'Open link in new window') +
      row('private', 'private', 'Open link in private window') +
      row('split', 'split', 'Open link in split view') +
      '<span class="lc-title">Link</span>' +
      row('copy', 'link', 'Copy link') +
      row('share', 'share', 'Share link') +
      '<span class="lc-title">Send</span>' +
      row('send', 'devices', 'Send to your device') +
      '</div>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-linkcontext">' +
      '<li><strong>01 Open</strong><span>Tab, window, private window or split view.</span></li>' +
      '<li><strong>02 Link</strong><span>Copy or share the address without leaving the menu.</span></li>' +
      '<li><strong>03 Send</strong><span>Send the link to another signed-in device.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="lc-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderToastHost() {
    const item = TOAST_EXAMPLES[toastKind] || TOAST_EXAMPLES.close;
    const chips = Object.keys(TOAST_EXAMPLES)
      .map(
        (key) =>
          '<button type="button" class="toast-kind' +
          (key === toastKind ? ' is-active' : '') +
          '" data-onboard="toast-kind" data-kind="' +
          key +
          '">' +
          TOAST_EXAMPLES[key].label +
          '</button>',
      )
      .join('');
    return (
      '<div class="onboarding-toasts">' +
      '<div class="toast-stage">' +
      '<div class="toast-page" aria-hidden="true">' +
      '<span class="toast-line"></span><span class="toast-line short"></span>' +
      '<span class="toast-line"></span><span class="toast-line short"></span>' +
      '</div>' +
      (toastVisible
        ? '<div class="toast" role="status" data-tone="' +
          item.tone +
          '"><span class="toast-icon" aria-hidden="true">' +
          tourIcon(item.icon) +
          '</span><span class="toast-text"><strong>' +
          esc(item.title) +
          '</strong><small>' +
          esc(toastMessage || item.detail) +
          '</small></span><button type="button" class="toast-action" data-onboard="toast-action">' +
          item.action +
          '</button><button type="button" class="toast-close" data-onboard="toast-dismiss" aria-label="Dismiss">&#215;</button></div>'
        : '') +
      '</div>' +
      '<div class="toast-kinds" role="group" aria-label="Toast examples">' +
      chips +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Toast</strong><span>One notice at a time, never blocking the page.</span></li>' +
      '<li><strong>02 Undo</strong><span>Closing a tab or saving a bookmark can be reversed.</span></li>' +
      '<li><strong>03 Error</strong><span>Failures stay until dismissed or retried.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="toast-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(toastMessage || (toastVisible ? item.title + '.' : 'Toast dismissed.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderCommandPalette() {
    let rowIndex = 0;
    const sections = COMMAND_SECTIONS.map((section, sectionIndex) => {
      const rows = section.items
        .map((item) => {
          const index = rowIndex++;
          return (
            '<button type="button" class="cp-row' +
            (index === commandIndex ? ' is-active' : '') +
            '" role="option" aria-selected="' +
            (index === commandIndex) +
            '" data-onboard="cp-run" data-cp-index="' +
            index +
            '"><span class="cp-icon" aria-hidden="true">' +
            tourIcon(item.icon) +
            '</span><span class="cp-copy"><strong>' +
            esc(item.title) +
            '</strong><small>' +
            esc(item.detail) +
            '</small></span><span class="cp-kind">' +
            esc(section.label) +
            '</span></button>'
          );
        })
        .join('');
      return (
        '<div class="cp-section" role="group" aria-labelledby="cp-head-' +
        sectionIndex +
        '"><span class="cp-title" id="cp-head-' +
        sectionIndex +
        '">' +
        esc(section.label) +
        '</span>' +
        rows +
        '</div>'
      );
    }).join('');
    const status = commandMessage || '⌘K / Ctrl+K opens this from anywhere.';
    return (
      '<div class="onboarding-commandpalette">' +
      '<div class="cp-stage">' +
      (commandOpen
        ? '<div class="cp-panel" role="dialog" aria-label="Command palette">' +
          '<div class="cp-input"><span class="cp-search" aria-hidden="true">' +
          tourIcon('search') +
          '</span><span class="cp-query">vaayvu</span><span class="cp-caret"></span>' +
          '<kbd>⌘K / Ctrl+K</kbd><button type="button" class="cp-close" data-onboard="cp-close" aria-label="Close command palette">&#215;</button></div>' +
          '<div class="cp-list" role="listbox" aria-label="Command palette results">' +
          sections +
          '</div>' +
          '<div class="cp-keys" aria-hidden="true"><span><kbd>↑</kbd><kbd>↓</kbd> move</span>' +
          '<span><kbd>↵</kbd> run</span><span><kbd>esc</kbd> close</span></div>' +
          '</div>'
        : '<div class="cp-closed"><strong>Command bar closed</strong>' +
          '<small>Press ⌘K / Ctrl+K or the button below to reopen it.</small>' +
          '<button type="button" data-onboard="cp-open">Open command bar</button></div>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-commandpalette">' +
      '<li><strong>01 Shortcut</strong><span>⌘K or Ctrl+K opens the palette from any page.</span></li>' +
      '<li><strong>02 Sections</strong><span>Actions, tabs, history, settings and AI stay grouped.</span></li>' +
      '<li><strong>03 Keyboard</strong><span>Move with ↑ ↓ and run the highlighted row with Enter.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      (commandOpen
        ? '<button type="button" class="onboarding-primary" data-onboard="cp-run" data-cp-index="' +
          commandIndex +
          '">Run selected</button>'
        : '<button type="button" class="onboarding-primary" data-onboard="cp-open">Open command bar</button>') +
      '<button type="button" class="onboarding-skip" data-onboard="cp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderStartPageCustomize() {
    const wallpapers = START_WALLPAPERS.map(
      (item) =>
        '<button type="button" class="stp-swatch stp-wall-' +
        item.id +
        (item.id === startWallpaper ? ' is-active' : '') +
        '" data-onboard="stp-wallpaper" data-wallpaper="' +
        item.id +
        '" aria-label="' +
        item.name +
        ' wallpaper" aria-pressed="' +
        (item.id === startWallpaper) +
        '"></button>',
    ).join('');
    const layouts = START_LAYOUTS.map(
      ([id, label]) =>
        '<button type="button" class="stp-option' +
        (id === startLayout ? ' is-active' : '') +
        '" data-onboard="stp-layout" data-layout="' +
        id +
        '" aria-pressed="' +
        (id === startLayout) +
        '">' +
        label +
        '</button>',
    ).join('');
    const widgets = START_WIDGETS.map(
      ([id, label]) =>
        '<button type="button" class="stp-toggle' +
        (startWidgets[id] ? ' is-active' : '') +
        '" data-onboard="stp-widget" data-widget="' +
        id +
        '" aria-pressed="' +
        !!startWidgets[id] +
        '">' +
        label +
        '</button>',
    ).join('');
    const widgetCards = [
      startWidgets.clock
        ? '<span class="stp-widget stp-clock"><strong>9:41</strong><small>Thursday</small></span>'
        : '',
      startWidgets.weather
        ? '<span class="stp-widget stp-weather"><strong>18°</strong><small>Clear</small></span>'
        : '',
      startWidgets.reading
        ? '<span class="stp-widget stp-reading"><strong>3</strong><small>saved to read</small></span>'
        : '',
      startWidgets.spaces
        ? '<span class="stp-widget stp-spaces"><strong>3</strong><small>spaces</small></span>'
        : '',
    ].join('');
    return (
      '<div class="onboarding-startpage">' +
      '<div class="stp-stage" data-wallpaper="' +
      startWallpaper +
      '" data-layout="' +
      startLayout +
      '">' +
      '<div class="stp-search" aria-hidden="true"></div>' +
      '<div class="stp-widgets">' +
      widgetCards +
      '</div>' +
      '</div>' +
      '<div class="stp-controls">' +
      '<div class="stp-group"><span class="stp-label">Wallpaper</span><div class="stp-swatches">' +
      wallpapers +
      '</div></div>' +
      '<div class="stp-group"><span class="stp-label">Layout</span><div class="stp-options">' +
      layouts +
      '</div></div>' +
      '<div class="stp-group"><span class="stp-label">Widgets</span><div class="stp-toggles">' +
      widgets +
      '</div></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Wallpaper</strong><span>Four grounds; the choice applies to the start page.</span></li>' +
      '<li><strong>02 Widgets</strong><span>Clock, weather, reading list and spaces, on or off.</span></li>' +
      '<li><strong>03 Layout</strong><span>Centered, sidebar or compact.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="stp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(startMessage || 'Start page: ' + startWallpaper + ', ' + startLayout + ' layout.') +
      '</small>' +
      '</div>'
    );
  }

  function renderStartPageZero() {
    const status =
      startZeroMessage || 'First run: no history, bookmarks or shortcuts yet.';
    return (
      '<div class="onboarding-startzero">' +
      '<div class="sz-stage">' +
      '<div class="sz-hero"><img src="assets/vaayvu.svg" width="34" height="34" alt="" />' +
      '<span class="sz-word">Vaayvu</span></div>' +
      '<div class="sz-search" aria-hidden="true"><span class="sz-search-icon">' +
      tourIcon('search') +
      '</span><span>Search or type an address</span><kbd>⌘L / Ctrl+L</kbd></div>' +
      '<div class="sz-empty">' +
      '<span class="sz-mark" aria-hidden="true">' +
      tourIcon('bookmark') +
      '</span>' +
      '<strong>No history or shortcuts yet</strong>' +
      '<p>Import bookmarks from another browser to fill the start page, or keep it quiet for now.</p>' +
      '<div class="sz-tiles" aria-hidden="true"><i></i><i></i><i></i><i></i></div>' +
      '<div class="sz-actions">' +
      '<button type="button" class="sz-import" data-onboard="sz-import">Import bookmarks</button>' +
      '<button type="button" class="sz-skip" data-onboard="sz-skip">Start fresh</button>' +
      '</div>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-startzero">' +
      '<li><strong>01 First run</strong><span>Nothing has been visited on this profile yet.</span></li>' +
      '<li><strong>02 No history</strong><span>No shortcuts, favorites or recent pages to show.</span></li>' +
      '<li><strong>03 Import</strong><span>Bring bookmarks in, or start with a clean page.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="sz-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderFrequentVisited() {
    const visible = frequentItems;
    const hiddenCount = [...frequentHidden].length;
    const status =
      frequentMessage ||
      (frequentAuto
        ? 'Built automatically from this profile’s history.'
        : 'Automatic updates are off; the tiles stay as they are.');
    const tile = (item) => {
      const hidden = frequentHidden.has(item.id);
      return (
        '<div class="fv-tile' +
        (hidden ? ' is-hidden' : '') +
        '"><button type="button" class="fv-open" data-onboard="fv-open" data-fv-name="' +
        esc(item.name) +
        '"><span class="fv-mark" aria-hidden="true">' +
        item.mark +
        '</span><span class="fv-name">' +
        esc(item.name) +
        '</span><span class="fv-host">' +
        esc(item.host) +
        '</span></button>' +
        (frequentEdit
          ? '<div class="fv-tools"><button type="button" class="fv-tool" data-onboard="fv-hide" data-fv-id="' +
            item.id +
            '" aria-label="' +
            (hidden ? 'Show ' : 'Hide ') +
            esc(item.name) +
            '">' +
            tourIcon(hidden ? 'eye' : 'eye') +
            (hidden ? 'Show' : 'Hide') +
            '</button><button type="button" class="fv-tool is-danger" data-onboard="fv-remove" data-fv-id="' +
            item.id +
            '" aria-label="Remove ' +
            esc(item.name) +
            '">' +
            tourIcon('trash') +
            'Remove</button></div>'
          : '') +
        '</div>'
      );
    };
    return (
      '<div class="onboarding-frequent">' +
      '<div class="fv-stage">' +
      '<div class="fv-hero"><img src="assets/vaayvu.svg" width="30" height="30" alt="" />' +
      '<span>Vaayvu</span></div>' +
      '<div class="fv-search" aria-hidden="true"><span aria-hidden="true">' +
      tourIcon('search') +
      '</span>Search or type an address</div>' +
      '<div class="fv-head"><strong>Frequently visited</strong>' +
      '<button type="button" class="fv-auto" data-onboard="fv-auto" role="switch" aria-checked="' +
      frequentAuto +
      '"><span class="fv-auto-dot" aria-hidden="true"></span>Auto</button>' +
      '<button type="button" class="fv-edit" data-onboard="fv-edit">' +
      (frequentEdit ? 'Done' : 'Edit') +
      '</button></div>' +
      (visible.length
        ? '<div class="fv-grid">' + visible.map(tile).join('') + '</div>'
        : '<p class="fv-empty">No frequently visited sites. They will appear as you browse.</p>') +
      (frequentEdit
        ? '<div class="fv-foot"><span>' +
          (hiddenCount ? hiddenCount + ' hidden from the page' : 'Hide keeps the site in history') +
          '</span><button type="button" class="fv-reset" data-onboard="fv-reset">Reset</button></div>'
        : '') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-frequent">' +
      '<li><strong>01 Auto</strong><span>History fills the grid; no setup or extra data.</span></li>' +
      '<li><strong>02 Hide</strong><span>Hide removes the tile but keeps the visit in history.</span></li>' +
      '<li><strong>03 Remove</strong><span>Remove deletes the shortcut from this page.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="fv-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderShortcutEditor() {
    const selected = shortcutSelectedItem();
    const tiles = shortcutItems
      .map(
        (item, index) =>
          '<div class="sc-item' +
          (item.id === shortcutSelected ? ' is-active' : '') +
          '"><button type="button" class="sc-tile" data-onboard="shortcut-select" data-id="' +
          esc(item.id) +
          '" aria-pressed="' +
          (item.id === shortcutSelected) +
          '"><span class="sc-fav" aria-hidden="true" style="--sc-color:' +
          item.color +
          '">' +
          esc(item.name.slice(0, 1).toUpperCase()) +
          '</span><span class="sc-name">' +
          esc(item.name) +
          '</span></button><span class="sc-handle">' +
          (index > 0
            ? '<button type="button" data-onboard="shortcut-move" data-id="' +
              esc(item.id) +
              '" data-dir="up" aria-label="Move ' +
              esc(item.name) +
              ' up">&#8593;</button>'
            : '') +
          (index < shortcutItems.length - 1
            ? '<button type="button" data-onboard="shortcut-move" data-id="' +
              esc(item.id) +
              '" data-dir="down" aria-label="Move ' +
              esc(item.name) +
              ' down">&#8595;</button>'
            : '') +
          '</span></div>',
      )
      .join('');
    const editor = selected
      ? '<div class="sc-editor"><div class="sc-editor-head"><span class="sc-fav" aria-hidden="true" style="--sc-color:' +
        selected.color +
        '">' +
        esc(selected.name.slice(0, 1).toUpperCase()) +
        '</span><strong>Editing ' +
        esc(selected.name) +
        '</strong></div>' +
        '<label class="sc-field"><span>Name</span><input data-shortcut-field="name" value="' +
        esc(shortcutDraft.name) +
        '" maxlength="40" autocomplete="off"></label>' +
        '<label class="sc-field"><span>URL</span><input data-shortcut-field="url" value="' +
        esc(shortcutDraft.url) +
        '" inputmode="url" autocomplete="off"></label>' +
        '<div class="sc-editor-actions"><button type="button" class="onboarding-primary" data-onboard="shortcut-save">Save</button>' +
        '<button type="button" class="onboarding-skip" data-onboard="shortcut-delete">Delete</button></div></div>'
      : '<p class="sc-empty">Add a shortcut to begin.</p>';
    return (
      '<div class="onboarding-shortcuts">' +
      '<div class="sc-grid" role="list">' +
      tiles +
      '<button type="button" class="sc-add" data-onboard="shortcut-add" aria-label="Add shortcut">+</button>' +
      '</div>' +
      editor +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Add</strong><span>A new tile appears in the next free spot.</span></li>' +
      '<li><strong>02 Edit</strong><span>Name and URL save together.</span></li>' +
      '<li><strong>03 Delete / reorder</strong><span>Remove a tile or move it with the arrows.</span></li>' +
      '<li><strong>04 Favicon</strong><span>The mark and colour identify the site.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="shortcut-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(shortcutMessage || shortcutItems.length + ' shortcuts.') +
      '</small>' +
      '</div>'
    );
  }

  function renderContinueBrowsing() {
    const rows = recentTabItems
      .map(
        (item) =>
          '<button type="button" class="cb-row" data-onboard="cb-restore" data-id="' +
          esc(item.id) +
          '"><span class="cb-fav" aria-hidden="true">' +
          esc((item.title || '?').slice(0, 1).toUpperCase()) +
          '</span><span class="cb-text"><strong>' +
          esc(item.title) +
          '</strong><small>' +
          esc(item.host) +
          '</small></span><span class="cb-action">Restore</span></button>',
      )
      .join('');
    return (
      '<div class="onboarding-continue">' +
      '<div class="cb-card">' +
      '<div class="cb-head"><span class="cb-icon" aria-hidden="true">' +
      tourIcon('history') +
      '</span><span class="cb-text"><strong>Continue browsing</strong><small>' +
      (recentTabItems.length
        ? recentTabItems.length + ' tabs from your last session'
        : 'No recent tabs') +
      '</small></span>' +
      (recentTabItems.length
        ? '<button type="button" class="cb-dismiss" data-onboard="cb-dismiss">Dismiss</button>'
        : '') +
      '</div>' +
      (recentTabItems.length
        ? '<div class="cb-list">' + rows + '</div>'
        : '<p class="cb-empty">Your next session starts with a clean start page.</p>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Recent tabs</strong><span>Pages from the last session, with their real hosts.</span></li>' +
      '<li><strong>02 Restore</strong><span>One row restores one tab; the primary restores all.</span></li>' +
      '<li><strong>03 Dismiss</strong><span>Clears the list without opening anything.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      (recentTabItems.length
        ? '<button type="button" class="onboarding-primary" data-onboard="cb-restore-all">Restore all</button>'
        : '') +
      '<button type="button" class="onboarding-skip" data-onboard="cb-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(recentTabMessage || (recentTabItems.length ? 'Ready to restore.' : 'Nothing to restore.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderSpacesOverview() {
    const status =
      spacesOverviewMessage || 'Each card keeps its own tabs, pins and recent pages.';
    const card = (space) =>
      '<button type="button" class="so-card' +
      (space.id === spacesOverviewSelected ? ' is-active' : '') +
      '" data-onboard="so-open" data-so-id="' +
      space.id +
      '"><span class="so-head"><span class="so-icon" aria-hidden="true">' +
      space.icon +
      '</span><span class="so-title"><strong>' +
      esc(space.name) +
      '</strong><small>' +
      space.count +
      (space.count === 1 ? ' tab' : ' tabs') +
      '</small></span><span class="so-arrow" aria-hidden="true">&rsaquo;</span></span>' +
      '<span class="so-recents">' +
      space.recents
        .map(
          (item) =>
            '<span class="so-recent"><span>' +
            esc(item.title) +
            '</span><small>' +
            esc(item.host) +
            '</small></span>',
        )
        .join('') +
      '</span></button>';
    return (
      '<div class="onboarding-spaces-overview">' +
      '<div class="so-stage">' +
      '<div class="so-heading"><strong>Spaces</strong><span>' +
      SPACES_OVERVIEW.length +
      ' workspaces</span></div>' +
      '<div class="so-grid">' +
      SPACES_OVERVIEW.map(card).join('') +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-spacesoverview">' +
      '<li><strong>01 Cards</strong><span>Each space has its own icon, accent and tab count.</span></li>' +
      '<li><strong>02 Recents</strong><span>The last pages stay with the space that opened them.</span></li>' +
      '<li><strong>03 Switch</strong><span>Opening a card moves to that space without mixing tabs.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="so-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderAiPrompt() {
    const status =
      aiPromptMessage ||
      (aiPromptSync
        ? 'Uses your Vaayvu sync server and its configured model.'
        : 'Connect to a Vaayvu sync server with Ollama enabled to ask about pages.');
    return (
      '<div class="onboarding-aiprompt">' +
      '<div class="ai-stage">' +
      '<div class="ai-hero"><img src="assets/vaayvu.svg" width="30" height="30" alt="" />' +
      '<span>Vaayvu</span></div>' +
      '<h3 class="ai-title">Ask about anything</h3>' +
      '<p class="ai-sub">Questions, page excerpts and answers stay on the server you configured.</p>' +
      '<div class="ai-bar"><span class="ai-spark" aria-hidden="true">' +
      tourIcon('spark') +
      '</span><span class="ai-query' +
      (aiPromptQuery ? '' : ' is-empty') +
      '">' +
      esc(aiPromptQuery || 'Ask about anything…') +
      '</span><button type="button" class="ai-send" data-onboard="ai-send" aria-label="Ask">' +
      tourIcon('arrow') +
      '</button></div>' +
      '<div class="ai-suggestions" role="group" aria-label="Suggestions">' +
      AI_PROMPT_SUGGESTIONS.map(
        (item) =>
          '<button type="button" class="ai-chip" data-onboard="ai-suggest" data-ai-id="' +
          item.id +
          '">' +
          esc(item.label) +
          '</button>',
      ).join('') +
      '</div>' +
      '<div class="ai-note"><span class="ai-note-dot" aria-hidden="true"></span>' +
      (aiPromptSync
        ? 'Sync connected · your server and model'
        : 'Sync not connected') +
      (aiPromptSync ? '' : '<button type="button" data-onboard="ai-connect">Connect to sync</button>') +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-aiprompt">' +
      '<li><strong>01 Prompt</strong><span>Ask about a page, code, tabs or anything in the space.</span></li>' +
      '<li><strong>02 Suggestions</strong><span>One tap fills a useful starting question.</span></li>' +
      '<li><strong>03 Source</strong><span>The question and excerpt go to your sync server, not a Vaayvu cloud.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ai-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderReadingList() {
    const rows = readingItems
      .map(
        (item) =>
          '<button type="button" class="rl-row" data-onboard="rl-open" data-id="' +
          esc(item.id) +
          '"><span class="rl-fav" aria-hidden="true">' +
          esc((item.title || '?').slice(0, 1).toUpperCase()) +
          '</span><span class="rl-text"><strong>' +
          esc(item.title) +
          '</strong><small>' +
          esc(item.host) +
          ' · ' +
          item.minutes +
          ' min read</small></span><span class="rl-arrow" aria-hidden="true">&#8250;</span></button>',
      )
      .join('');
    return (
      '<div class="onboarding-reading">' +
      '<div class="rl-card">' +
      '<div class="rl-head"><span class="rl-icon" aria-hidden="true">' +
      tourIcon('book') +
      '</span><span class="rl-text"><strong>Reading list</strong><small>' +
      readingItems.length +
      ' saved</small></span>' +
      (readingItems.length
        ? '<button type="button" class="rl-open-all" data-onboard="rl-open-all">Open all</button>'
        : '') +
      '</div>' +
      (readingItems.length
        ? '<div class="rl-list">' + rows + '</div>'
        : '<p class="rl-empty">No saved pages yet.</p>' +
          '<button type="button" class="rl-open-all" data-onboard="rl-bookmarks">Open bookmarks</button>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Saved pages</strong><span>Three items with host and reading time.</span></li>' +
      '<li><strong>02 Open</strong><span>One row opens one saved page.</span></li>' +
      '<li><strong>03 Open all</strong><span>Every saved page opens in order.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      (readingItems.length
        ? '<button type="button" class="onboarding-primary" data-onboard="rl-open-all">Open all</button>'
        : '') +
      '<button type="button" class="onboarding-skip" data-onboard="rl-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(readingMessage || (readingItems.length ? 'Ready to open.' : 'Nothing saved yet.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderNewsFeed() {
    const topicChips = NEWS_TOPICS.map(
      (topic) =>
        '<button type="button" class="nf-chip' +
        (newsTopics.includes(topic) ? ' is-active' : '') +
        '" data-onboard="news-topic" data-topic="' +
        esc(topic) +
        '" aria-pressed="' +
        newsTopics.includes(topic) +
        '">' +
        topic +
        '</button>',
    ).join('');
    const sourceChips = NEWS_SOURCES.map(
      (name) =>
        '<button type="button" class="nf-chip' +
        (newsSources.includes(name) ? ' is-active' : '') +
        '" data-onboard="news-source" data-source="' +
        esc(name) +
        '" aria-pressed="' +
        newsSources.includes(name) +
        '">' +
        esc(name) +
        '</button>',
    ).join('');
    const visibleStories = NEWS_STORIES.filter(
      (story) => newsSources.includes(story.source) && !newsHidden.has(story.id),
    );
    const stories = visibleStories.length
      ? visibleStories
          .map(
            (story) =>
              '<div class="nf-story"><span class="nf-source">' +
              esc(story.source) +
              '</span><strong>' +
              esc(story.title) +
              '</strong><button type="button" class="nf-hide" data-onboard="news-hide" data-id="' +
              esc(story.id) +
              '" aria-label="Hide ' +
              esc(story.title) +
              '">Hide</button></div>',
          )
          .join('')
      : '<p class="nf-empty">No stories for these choices.</p>';
    return (
      '<div class="onboarding-news">' +
      '<div class="nf-card">' +
      '<div class="nf-head"><span class="nf-icon" aria-hidden="true">' +
      tourIcon('globe') +
      '</span><span class="nf-text"><strong>News feed</strong><small>' +
      (newsEnabled ? 'On · ' + newsTopics.length + ' topics' : 'Off by default') +
      '</small></span><button type="button" class="nf-switch' +
      (newsEnabled ? ' is-on' : '') +
      '" role="switch" data-onboard="news-toggle" aria-checked="' +
      newsEnabled +
      '" aria-label="News feed"><span class="nf-thumb" aria-hidden="true"></span></button></div>' +
      (newsEnabled
        ? '<div class="nf-body">' +
          '<div class="nf-group"><span class="nf-label">Topics</span><div class="nf-chips">' +
          topicChips +
          '</div></div>' +
          '<div class="nf-group"><span class="nf-label">Sources</span><div class="nf-chips">' +
          sourceChips +
          '</div></div>' +
          '<div class="nf-group"><span class="nf-label">Stories</span><div class="nf-stories">' +
          stories +
          '</div></div>' +
          '</div>'
        : '<div class="nf-off"><p>Nothing is fetched until you turn it on. Your reading stays on this device.</p>' +
          '<button type="button" class="onboarding-primary" data-onboard="news-toggle">Turn on news feed</button></div>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Off by default</strong><span>No feed, no fetch, until you opt in.</span></li>' +
      '<li><strong>02 Topics</strong><span>Pick the subjects you want to see.</span></li>' +
      '<li><strong>03 Sources</strong><span>Choose which publications are included.</span></li>' +
      '<li><strong>04 Hide</strong><span>Hide a story without changing the feed.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="news-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(newsMessage || (newsEnabled ? 'News feed on.' : 'News feed is off.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderWidgets() {
    const now = new Date();
    const time = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const date = now.toLocaleDateString([], { weekday: 'long', day: 'numeric', month: 'long' });
    const status =
      widgetMessage ||
      (widgetStocksOn
        ? 'Stocks are on. No provider is configured in this build.'
        : 'Weather, clock and stocks are widgets on the start page.');
    return (
      '<div class="onboarding-widgets">' +
      '<div class="wg-stage">' +
      '<div class="wg-grid">' +
      '<div class="wg-card wg-clock"><span class="wg-kicker">Clock</span>' +
      '<strong class="wg-time">' +
      esc(time) +
      '</strong><small class="wg-date">' +
      esc(date) +
      '</small></div>' +
      '<div class="wg-card wg-weather"><span class="wg-kicker">Weather</span>' +
      '<strong class="wg-temp">—°</strong><small>Choose a city · Open-Meteo</small>' +
      '<button type="button" class="wg-btn" data-onboard="wg-weather">Choose city</button></div>' +
      '<div class="wg-card wg-stocks' +
      (widgetStocksOn ? ' is-on' : '') +
      '"><span class="wg-kicker">Stocks <b>Opt-in</b></span>' +
      '<strong class="wg-temp">' +
      (widgetStocksOn ? 'On' : 'Off') +
      '</strong><small>' +
      (widgetStocksOn
        ? 'No quotes yet · provider not configured'
        : 'Quotes need a provider you choose.') +
      '</small><button type="button" class="wg-btn" data-onboard="wg-stocks">' +
      (widgetStocksOn ? 'Turn off stocks' : 'Enable stocks') +
      '</button></div>' +
      '</div>' +
      '<p class="wg-note">Stocks stay off until you enable them; quotes are never bundled or invented.</p>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-widgets">' +
      '<li><strong>01 Clock</strong><span>The current local time and date.</span></li>' +
      '<li><strong>02 Weather</strong><span>Choose a city; Open-Meteo receives the request.</span></li>' +
      '<li><strong>03 Stocks</strong><span>Opt-in and provider-backed; off by default.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="wg-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderWallpaper() {
    const current =
      WALLPAPER_PRESETS.find((item) => item.id === wallpaperChoice) || WALLPAPER_BUILTIN[0];
    const previewCss = wallpaperImage
      ? 'linear-gradient(160deg,#dcd8ce,#bdb7aa 55%,#8f8a7e)'
      : current.css;
    const status =
      wallpaperMessage ||
      'Built-in scenes work offline; images stay on this device unless sync is on.';
    const swatch = (item) =>
      '<button type="button" class="wp-swatch' +
      (wallpaperChoice === item.id && !wallpaperImage ? ' is-active' : '') +
      '" data-onboard="wp-choose" data-wp-id="' +
      item.id +
      '"><span class="wp-chip" style="background:' +
      item.css +
      '"></span><span class="wp-name">' +
      esc(item.name) +
      '</span></button>';
    return (
      '<div class="onboarding-wallpaper">' +
      '<div class="wp-stage">' +
      '<div class="wp-preview" aria-hidden="true">' +
      '<span class="wp-bg" style="background:' +
      previewCss +
      '; filter: blur(' +
      wallpaperBlur +
      'px)"></span>' +
      '<span class="wp-preview-ui"><img src="assets/vaayvu.svg" width="26" height="26" alt="" />' +
      '<span>Vaayvu</span><i class="wp-search"></i></span>' +
      '</div>' +
      '<div class="wp-groups">' +
      '<span class="wp-title">Built in</span>' +
      '<div class="wp-grid">' +
      WALLPAPER_BUILTIN.map(swatch).join('') +
      '</div>' +
      '<span class="wp-title">Gradients</span>' +
      '<div class="wp-grid">' +
      WALLPAPER_GRADIENTS.map(swatch).join('') +
      '</div>' +
      '<span class="wp-title">Image</span>' +
      '<div class="wp-image-row"><span class="wp-image-mark" aria-hidden="true">' +
      tourIcon('mountain') +
      '</span><span><strong>' +
      (wallpaperImage ? 'Image selected' : 'Choose an image') +
      '</strong><small>JPG, PNG or WebP. Stored on this device.</small></span>' +
      '<button type="button" data-onboard="wp-image">' +
      (wallpaperImage ? 'Replace' : 'Choose') +
      '</button></div>' +
      '<label class="wp-blur"><span>Blur <b>' +
      wallpaperBlur +
      'px</b></span><input type="range" min="0" max="24" step="1" value="' +
      wallpaperBlur +
      '" data-wp-blur aria-label="Wallpaper blur" /></label>' +
      '<div class="wp-sync-row"><span><strong>Sync wallpaper</strong><small>' +
      (wallpaperSync
        ? 'Uses your Vaayvu sync server.'
        : 'Stays on this device.') +
      '</small></span><button type="button" class="wp-sync' +
      (wallpaperSync ? ' is-on' : '') +
      '" data-onboard="wp-sync" role="switch" aria-checked="' +
      wallpaperSync +
      '"><span class="wp-sync-dot" aria-hidden="true"></span>' +
      (wallpaperSync ? 'On' : 'Off') +
      '</button></div>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-wallpaper">' +
      '<li><strong>01 Built-in</strong><span>Six scenes that work without a network.</span></li>' +
      '<li><strong>02 Gradient and image</strong><span>Make a gradient or choose your own image.</span></li>' +
      '<li><strong>03 Blur</strong><span>Soften the background without touching the page.</span></li>' +
      '<li><strong>04 Sync</strong><span>Uses your Vaayvu sync server when enabled.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="wp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderOfflineStart() {
    const status =
      offlineMessage ||
      (offlineRetries
        ? 'Still offline after ' + offlineRetries + ' retries. Cached shortcuts remain available.'
        : 'Showing shortcuts cached on this device.');
    const tile = (item) =>
      '<button type="button" class="of-tile" data-onboard="of-open" data-of-name="' +
      esc(item.name) +
      '"><span class="of-mark" aria-hidden="true">' +
      item.mark +
      '</span><span class="of-copy"><strong>' +
      esc(item.name) +
      '</strong><small>' +
      esc(item.host) +
      '</small></span><span class="of-cached">Cached</span></button>';
    return (
      '<div class="onboarding-offline">' +
      '<div class="of-stage">' +
      '<div class="of-hero"><img src="assets/vaayvu.svg" width="30" height="30" alt="" />' +
      '<span>Vaayvu</span><b class="of-badge">Offline</b></div>' +
      '<div class="of-banner"><span class="of-dot" aria-hidden="true"></span>' +
      '<span class="of-banner-copy"><strong>You are offline</strong><small>Shortcuts below come from this device.</small></span>' +
      '<button type="button" class="of-retry" data-onboard="of-retry">Retry</button></div>' +
      '<div class="of-search" aria-hidden="true"><span class="of-search-icon">' +
      tourIcon('search') +
      '</span><span>Search this device</span><kbd>Offline</kbd></div>' +
      '<div class="of-head"><strong>Cached shortcuts</strong><span>' +
      OFFLINE_SHORTCUTS.length +
      '</span></div>' +
      '<div class="of-grid">' +
      OFFLINE_SHORTCUTS.map(tile).join('') +
      '</div>' +
      '<p class="of-note">Live pages need a connection. Cached copies may be out of date.</p>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-offline">' +
      '<li><strong>01 Offline</strong><span>The page says so plainly; it does not pretend to be online.</span></li>' +
      '<li><strong>02 Cached shortcuts</strong><span>Bookmarks and cached pages stay reachable.</span></li>' +
      '<li><strong>03 Retry</strong><span>Retry checks again; it never fakes a connection.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="of-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderStartSettings() {
    const blocks = [];
    if (startSectionState.spaces)
      blocks.push('<span class="stg-block"><strong>Spaces</strong><span class="stg-chips">🌊 🛠️ 📚</span></span>');
    if (startSectionState.favorites)
      blocks.push('<span class="stg-block"><strong>Favorites</strong><span class="stg-dots"><i></i><i></i><i></i><i></i></span></span>');
    if (startSectionState.recent)
      blocks.push('<span class="stg-block"><strong>Recently visited</strong><span class="stg-lines"><i></i><i class="short"></i></span></span>');
    if (startSectionState.reading)
      blocks.push('<span class="stg-block"><strong>Reading list</strong><span class="stg-lines"><i></i><i class="short"></i></span></span>');
    if (startSectionState.continue)
      blocks.push('<span class="stg-block"><strong>Continue browsing</strong><span class="stg-lines"><i></i></span></span>');
    if (startSectionState.news)
      blocks.push('<span class="stg-block"><strong>News feed</strong><span class="stg-lines"><i></i><i></i><i class="short"></i></span></span>');
    const toggles = START_SECTIONS.map(
      ([id, label]) =>
        '<div class="stg-toggle-row"><span>' +
        label +
        '</span><button type="button" class="stg-switch' +
        (startSectionState[id] ? ' is-on' : '') +
        '" role="switch" data-onboard="stg-section" data-section="' +
        id +
        '" aria-checked="' +
        !!startSectionState[id] +
        '" aria-label="' +
        label +
        ' section"><span class="stg-thumb" aria-hidden="true"></span></button></div>',
    ).join('');
    const layouts = START_LAYOUTS.map(
      ([id, label]) =>
        '<button type="button" class="stg-layout' +
        (id === startSettingsLayout ? ' is-active' : '') +
        '" data-onboard="stg-layout" data-layout="' +
        id +
        '" aria-pressed="' +
        (id === startSettingsLayout) +
        '">' +
        label +
        '</button>',
    ).join('');
    return (
      '<div class="onboarding-startsettings">' +
      '<div class="stg-stage" data-layout="' +
      startSettingsLayout +
      '">' +
      (startSectionState.search ? '<span class="stg-search" aria-hidden="true"></span>' : '') +
      '<div class="stg-blocks">' +
      blocks.join('') +
      '</div>' +
      '</div>' +
      '<div class="stg-panel">' +
      '<div class="stg-group"><span class="stg-label">Sections</span><div class="stg-toggles">' +
      toggles +
      '</div></div>' +
      '<div class="stg-group"><span class="stg-label">Layout</span><div class="stg-layouts">' +
      layouts +
      '</div></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Sections</strong><span>Each block is on or off independently.</span></li>' +
      '<li><strong>02 Layout</strong><span>Centered, sidebar or compact.</span></li>' +
      '<li><strong>03 Preview</strong><span>The stage above follows every change.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="stg-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(startSettingsMessage || 'Start-page settings.') +
      '</small>' +
      '</div>'
    );
  }

  function renderPrivateStart() {
    const checks = [
      'History is not recorded',
      'No bookmark or history suggestions',
      'No sync and no profile',
      'Cookies and site data clear when the window closes',
    ]
      .map((line) => '<li><span class="pv-check" aria-hidden="true">&#10003;</span>' + line + '</li>')
      .join('');
    return (
      '<div class="onboarding-private">' +
      '<div class="pv-card">' +
      '<div class="pv-hero"><span class="pv-icon" aria-hidden="true">' +
      tourIcon('private') +
      '</span><div class="pv-hero-text"><strong>Private window</strong><small>Nothing here follows you to the next window.</small></div><span class="pv-badge">Private</span></div>' +
      '<div class="pv-search" aria-hidden="true"><span class="pv-search-icon">' +
      tourIcon('search') +
      '</span><span class="pv-url">Search or type an address</span></div>' +
      (privateChecked
        ? '<div class="pv-suggest"><strong>No suggestions</strong><span>This window keeps no history or bookmarks to suggest from.</span></div>'
        : '') +
      '<ul class="pv-list">' +
      checks +
      '</ul>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Private</strong><span>One badge states what the window is.</span></li>' +
      '<li><strong>02 No history</strong><span>Visits are not written to History or session restore.</span></li>' +
      '<li><strong>03 Suggestions</strong><span>The omnibox has nothing local to suggest.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="private-check">Check suggestions</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="private-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(privateMessage || 'Private window. No history, no local suggestions.') +
      '</small>' +
      '</div>'
    );
  }

  function renderActiveTab() {
    const color = ACTIVE_TAB_COLORS.find((item) => item.color === activeTabColor) || ACTIVE_TAB_COLORS[0];
    const status =
      activeTabMessage ||
      (activeTabClosed ? 'The active tab is closed.' : 'One tab: favicon, title, audio, close and group colour.');
    const tab = activeTabClosed
      ? '<span class="at-tab at-closed"><span class="at-title">Tab closed</span>' +
        '<button type="button" class="at-reopen" data-onboard="at-reopen">Reopen</button></span>'
      : '<span class="at-tab is-active" style="--tab-color:' +
        activeTabColor +
        '"><span class="at-group-bar" aria-hidden="true"></span>' +
        '<span class="at-favicon" aria-hidden="true">L</span>' +
        '<span class="at-title">Linear — Q4 roadmap</span>' +
        '<button type="button" class="at-audio' +
        (activeTabAudio ? ' is-on' : ' is-muted') +
        '" data-onboard="at-audio" aria-pressed="' +
        activeTabAudio +
        '" aria-label="' +
        (activeTabAudio ? 'Mute tab audio' : 'Unmute tab audio') +
        '">' +
        tourIcon('audio') +
        '</button>' +
        '<button type="button" class="at-close" data-onboard="at-close" aria-label="Close tab">' +
        tourIcon('x') +
        '</button></span>';
    return (
      '<div class="onboarding-activetab">' +
      '<div class="at-stage">' +
      '<div class="at-strip" role="tablist" aria-label="Tabs">' +
      tab +
      '<span class="at-tab at-other" role="tab" aria-selected="false">GitHub</span>' +
      '<span class="at-tab at-other" role="tab" aria-selected="false">Docs</span>' +
      '<span class="at-plus" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="at-detail">' +
      '<span class="at-detail-head">Active tab details</span>' +
      '<div class="at-row"><span>Group colour</span><div class="at-colors" role="group" aria-label="Group colour">' +
      ACTIVE_TAB_COLORS.map(
        (item) =>
          '<button type="button" class="at-color' +
          (item.color === activeTabColor ? ' is-active' : '') +
          '" data-onboard="at-color" data-color="' +
          item.color +
          '" aria-label="' +
          esc(item.name) +
          '" style="--swatch:' +
          item.color +
          '"></button>',
      ).join('') +
      '</div></div>' +
      '<div class="at-row"><span>Audio</span><strong>' +
      (activeTabAudio ? 'Playing' : 'Muted') +
      '</strong></div>' +
      '<div class="at-row"><span>Group</span><strong>Work</strong></div>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-activetab">' +
      '<li><strong>01 Favicon and title</strong><span>The page mark and its name share the row.</span></li>' +
      '<li><strong>02 Audio</strong><span>The speaker shows a playing tab and can mute it.</span></li>' +
      '<li><strong>03 Close</strong><span>The close control is always on the active tab.</span></li>' +
      '<li><strong>04 Group colour</strong><span>The edge and swatch show the tab’s group.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="at-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      ' · ' +
      esc(color.name) +
      '</small>' +
      '</div>'
    );
  }

  function renderInactiveTab() {
    const active = inactiveTabs.find((tab) => tab.id === inactiveActive) || inactiveTabs[0];
    const tabs = inactiveTabs
      .map((tab) => {
        if (tab.id === active.id) {
          return (
            '<button type="button" class="it-tab is-active" role="tab" aria-selected="true">' +
            esc(tab.title) +
            '</button>'
          );
        }
        return (
          '<span class="it-tab-wrap"><button type="button" class="it-tab is-inactive" role="tab" aria-selected="false" data-onboard="it-activate" data-id="' +
          esc(tab.id) +
          '">' +
          esc(tab.title) +
          '</button><span class="it-actions"><button type="button" data-onboard="it-pin" data-id="' +
          esc(tab.id) +
          '" aria-label="Pin ' +
          esc(tab.title) +
          '">' +
          tourIcon('pin') +
          '</button><button type="button" data-onboard="it-close" data-id="' +
          esc(tab.id) +
          '" aria-label="Close ' +
          esc(tab.title) +
          '">&#215;</button></span></span>'
        );
      })
      .join('');
    return (
      '<div class="onboarding-inactivetab">' +
      '<div class="it-strip" role="tablist" aria-label="Tabs">' +
      tabs +
      '<span class="it-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="it-stage">' +
      '<span class="it-kicker">Active tab</span>' +
      '<strong>' +
      esc(active ? active.title : 'No tab') +
      '</strong>' +
      '<span class="it-line"></span><span class="it-line short"></span>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Dimmed</strong><span>A background tab is quieter than the one you are on.</span></li>' +
      '<li><strong>02 Hover actions</strong><span>Pin and close appear without taking space at rest.</span></li>' +
      '<li><strong>03 Activate</strong><span>Clicking the dimmed tab makes it the active one.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="it-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(inactiveMessage || (inactivePinned ? 'Background tab pinned.' : 'Background tab dimmed until hover.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderMutedTab() {
    const status = mutedTabMessage || (mutedTabMuted ? 'This tab is muted. Other tabs keep their audio.' : 'This tab is playing audio.');
    return (
      '<div class="onboarding-mutedtab">' +
      '<div class="mt-stage">' +
      '<div class="mt-strip" role="tablist" aria-label="Tabs">' +
      '<span class="mt-tab is-active" role="tab" aria-selected="true">' +
      '<span class="mt-favicon" aria-hidden="true">Y</span>' +
      '<span class="mt-title">YouTube — Live set</span>' +
      '<button type="button" class="mt-audio' +
      (mutedTabMuted ? ' is-muted' : ' is-on') +
      '" data-onboard="mt-audio" aria-pressed="' +
      !mutedTabMuted +
      '" aria-label="' +
      (mutedTabMuted ? 'Unmute tab audio' : 'Mute tab audio') +
      '">' +
      tourIcon('audio') +
      '</button></span>' +
      '<span class="mt-tab mt-other" role="tab" aria-selected="false">GitHub</span>' +
      '<span class="mt-tab mt-other" role="tab" aria-selected="false">Docs</span>' +
      '<span class="mt-plus" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="mt-panel">' +
      '<span class="mt-status' +
      (mutedTabMuted ? ' is-muted' : ' is-on') +
      '"><span class="mt-dot" aria-hidden="true"></span>' +
      (mutedTabMuted ? 'Audio muted' : 'Audio playing') +
      '</span>' +
      '<p>Muting affects this tab only. Other tabs keep their own sound.</p>' +
      '<button type="button" class="mt-unmute" data-onboard="mt-unmute">' +
      (mutedTabMuted ? 'Unmute tab' : 'Mute tab') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-mutedtab">' +
      '<li><strong>01 Muted icon</strong><span>The speaker with a slash shows this tab is silent.</span></li>' +
      '<li><strong>02 Unmute</strong><span>One action restores sound without reloading the page.</span></li>' +
      '<li><strong>03 Scope</strong><span>Only this tab changes; other tabs keep their audio.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="mt-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderPinnedTab() {
    const pinned = pinnedTabs
      .map(
        (tab) =>
          '<span class="pt-pin-wrap"><button type="button" class="pt-fav' +
          (pinnedActive === tab.id ? ' is-active' : '') +
          '" data-onboard="pt-activate" data-id="' +
          esc(tab.id) +
          '" aria-label="' +
          esc(tab.title) +
          '" title="' +
          esc(tab.title) +
          '">' +
          esc(tab.mark) +
          '</button><button type="button" class="pt-unpin" data-onboard="pt-unpin" data-id="' +
          esc(tab.id) +
          '" aria-label="Unpin ' +
          esc(tab.title) +
          '">&#215;</button></span>',
      )
      .join('');
    const regular = regularTabs
      .map(
        (tab) =>
          '<span class="pt-tab-wrap"><button type="button" class="pt-tab' +
          (pinnedActive === tab.id ? ' is-active' : '') +
          '" data-onboard="pt-activate" data-id="' +
          esc(tab.id) +
          '">' +
          esc(tab.title) +
          '</button><button type="button" class="pt-pin-action" data-onboard="pt-pin" data-id="' +
          esc(tab.id) +
          '" aria-label="Pin ' +
          esc(tab.title) +
          '">' +
          tourIcon('pin') +
          '</button></span>',
      )
      .join('');
    const active = [...pinnedTabs, ...regularTabs].find((tab) => tab.id === pinnedActive);
    return (
      '<div class="onboarding-pinnedtab">' +
      '<div class="pt-strip" role="tablist" aria-label="Tabs">' +
      '<span class="pt-zone" role="group" aria-label="Pinned tabs">' +
      pinned +
      '</span>' +
      '<span class="pt-sep" aria-hidden="true"></span>' +
      regular +
      '<span class="pt-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="pt-stage"><span class="pt-kicker">Active tab</span><strong>' +
      esc(active ? active.title : 'No tab') +
      '</strong><span class="pt-line"></span><span class="pt-line short"></span></div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Favicon only</strong><span>A pinned tab keeps its mark and drops the title.</span></li>' +
      '<li><strong>02 Fixed zone</strong><span>Pinned tabs sit left of the divider and keep their order.</span></li>' +
      '<li><strong>03 Unpin</strong><span>Unpin returns the tab to the regular strip with its title.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="pt-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(pinnedMessage || pinnedTabs.length + ' pinned tabs in the fixed zone.') +
      '</small>' +
      '</div>'
    );
  }

  function renderPlayingAudio() {
    const bars = '<span class="au-bars" aria-hidden="true"><i></i><i></i><i></i></span>';
    return (
      '<div class="onboarding-playingaudio">' +
      '<div class="au-strip" role="tablist" aria-label="Tabs">' +
      '<button type="button" class="au-tab" role="tab" aria-selected="false" data-onboard="au-activate" data-title="Observatory">Observatory</button>' +
      '<span class="au-tab-wrap"><button type="button" class="au-tab is-active" role="tab" aria-selected="true" data-onboard="au-activate" data-title="Music">Music</button>' +
      '<button type="button" class="au-speaker' +
      (audioMuted ? ' is-muted' : ' is-playing') +
      '" data-onboard="au-mute" aria-pressed="' +
      audioMuted +
      '" aria-label="' +
      (audioMuted ? 'Unmute Music' : 'Mute Music') +
      '">' +
      bars +
      '</button></span>' +
      '<span class="au-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="au-stage">' +
      '<span class="au-kicker">Now playing</span>' +
      '<strong>Night drive</strong>' +
      '<small>Ambient · 4:12</small>' +
      '<span class="au-meter' +
      (audioMuted ? ' is-muted' : '') +
      '" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></span>' +
      '<button type="button" class="au-mute" data-onboard="au-mute" aria-pressed="' +
      audioMuted +
      '">' +
      (audioMuted ? 'Unmute' : 'Mute') +
      '</button>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Playing</strong><span>The tab says which page is making sound.</span></li>' +
      '<li><strong>02 Speaker</strong><span>The bars move only while audio is playing.</span></li>' +
      '<li><strong>03 Mute</strong><span>Click the speaker or the Mute button; the bars stop.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="au-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(audioMessage || (audioMuted ? 'Muted.' : 'Playing audio.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderLoadingTab() {
    const loaded = loadProgress >= 100;
    const status = loaded ? 'Loaded' : loadProgress + '%';
    return (
      '<div class="onboarding-loadingtab">' +
      '<div class="lt-strip" role="tablist" aria-label="Tabs">' +
      '<button type="button" class="lt-tab" role="tab" aria-selected="false" data-onboard="lt-activate" data-title="Observatory">Observatory</button>' +
      '<span class="lt-tab-wrap"><button type="button" class="lt-tab is-active is-loading" role="tab" aria-selected="true" data-onboard="lt-activate" data-title="Reading">' +
      (loaded
        ? '<span class="lt-fav" aria-hidden="true">R</span>'
        : '<span class="lt-spinner" aria-hidden="true"></span>') +
      'Reading</button></span>' +
      '<span class="lt-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="lt-stage">' +
      '<div class="lt-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="' +
      loadProgress +
      '" aria-label="Page load progress"><span class="lt-progress-fill" style="width:' +
      loadProgress +
      '%"></span></div>' +
      '<div class="lt-head"><span class="lt-kicker">' +
      (loaded ? 'Loaded' : 'Loading') +
      '</span><strong>' +
      status +
      '</strong></div>' +
      '<span class="lt-line"></span><span class="lt-line"></span><span class="lt-line short"></span>' +
      '<span class="lt-skeleton"><i></i><i></i><i></i></span>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Spinner</strong><span>The tab spins while the page is still arriving.</span></li>' +
      '<li><strong>02 Progress</strong><span>The bar and the tab both show how far the load has come.</span></li>' +
      '<li><strong>03 Settled</strong><span>At 100% the spinner becomes the favicon.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="lt-step">Advance load</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="lt-reload">Reload</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="lt-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(loadMessage || (loaded ? 'Page loaded.' : 'Loading, ' + loadProgress + '%.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderCrashedTab() {
    const info = crashedTabInfo();
    if (!info) return '';
    const status =
      crashedTabMessage ||
      (crashedTabReported
        ? 'Crash report queued on this device.'
        : 'Reload the page or report the crash.');
    return (
      '<div class="onboarding-crashed">' +
      '<div class="ct-strip" role="tablist" aria-label="Tabs">' +
      '<span class="ct-tab" role="tab" aria-selected="false">Observatory</span>' +
      '<span class="ct-tab is-active" role="tab" aria-selected="true"><span class="ct-fav" aria-hidden="true">:(</span>' +
      esc(info.title) +
      '</span>' +
      '<span class="ct-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="ct-stage">' +
      '<span class="ct-face" aria-hidden="true">:(</span>' +
      '<strong class="ct-title">This page crashed</strong>' +
      '<p class="ct-copy">' +
      esc(info.reason) +
      ' Other tabs keep running.</p>' +
      '<div class="ct-actions">' +
      '<button type="button" class="ct-reload" data-onboard="ct-reload">Reload</button>' +
      '<button type="button" class="ct-report' +
      (crashedTabReported ? ' is-reported' : '') +
      '" data-onboard="ct-report" aria-pressed="' +
      crashedTabReported +
      '">' +
      (crashedTabReported ? 'Reported' : 'Report') +
      '</button>' +
      '</div>' +
      '<small class="ct-note" role="status">' +
      esc(status) +
      '</small>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-crashedtab">' +
      '<li><strong>01 Sad tab</strong><span>The tab shows a crash mark instead of a favicon.</span></li>' +
      '<li><strong>02 Reload</strong><span>Reload asks the tab to start again.</span></li>' +
      '<li><strong>03 Report</strong><span>Reports stay on this device; no telemetry backend is configured.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ct-continue">Continue</button>' +
      '</div>' +
      '</div>'
    );
  }

  function renderSleepingTab() {
    const asleep = sleepState === 'sleeping';
    const wanted = sleepState === 'waking';
    const rows = [
      { id: 'reading', title: 'Reading' },
      { id: 'notes', title: 'Notes' },
    ]
      .map((tab) => {
        const isThis = tab.id === 'reading';
        const cls = isThis ? (asleep ? ' is-sleeping' : wanted ? ' is-waking' : ' is-active') : '';
        const glyph = isThis
          ? asleep
            ? '<span class="sl-zzz" aria-hidden="true">z</span>'
            : wanted
              ? '<span class="sl-spinner" aria-hidden="true"></span>'
              : '<span class="sl-fav" aria-hidden="true">R</span>'
          : '<span class="sl-fav" aria-hidden="true">N</span>';
        return (
          '<span class="sl-tab-wrap"><button type="button" class="sl-tab' +
          cls +
          '" data-onboard="sl-wake" data-id="' +
          tab.id +
          '" aria-label="' +
          esc(tab.title) +
          '">' +
          glyph +
          esc(tab.title) +
          (isThis && asleep ? '<span class="sl-badge">Sleeping</span>' : '') +
          (isThis && wanted ? '<span class="sl-badge">Waking</span>' : '') +
          '</button></span>'
        );
      })
      .join('');
    return (
      '<div class="onboarding-sleepingtab">' +
      '<div class="sl-strip" role="tablist" aria-label="Tabs">' +
      rows +
      '<span class="sl-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="sl-stage' +
      (asleep ? ' is-sleeping' : '') +
      '">' +
      '<span class="sl-kicker">' +
      (asleep ? 'Sleeping' : wanted ? 'Waking' : 'Background tab') +
      '</span>' +
      '<strong>' +
      (asleep ? 'Reading is asleep' : wanted ? 'Waking Reading' : 'Reading stays ready') +
      '</strong>' +
      '<small>' +
      (asleep
        ? 'Its memory was released. Nothing was lost.'
        : wanted
          ? 'Reloading the page exactly where you left it.'
          : 'Background tabs may sleep to free memory.') +
      '</small>' +
      '<span class="sl-line"></span><span class="sl-line short"></span>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Dimmed</strong><span>A sleeping tab is quieter than an active one.</span></li>' +
      '<li><strong>02 Sleeping</strong><span>The badge and the zzz say exactly what happened.</span></li>' +
      '<li><strong>03 Wake</strong><span>Click it and the page comes back to its place.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="sl-sleep"' +
      (asleep ? ' disabled' : '') +
      '>Put to sleep</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sl-wake">Wake</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sl-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(sleepMessage || (asleep ? 'Tab sleeping.' : 'Tab awake.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderHoverPreview() {
    const status =
      hoverPreviewMessage ||
      (hoverPreviewClosed
        ? 'The tab is closed. Reopen restores the preview.'
        : hoverPreviewMuted
          ? 'This tab is muted.'
          : 'Hover preview ready.');
    return (
      '<div class="onboarding-hoverpreview">' +
      '<div class="hp-stage">' +
      '<div class="hp-strip" role="tablist" aria-label="Tabs">' +
      '<span class="hp-tab" role="tab" aria-selected="false">Observatory</span>' +
      (hoverPreviewClosed
        ? '<span class="hp-closed-tab">Tab closed</span>'
        : '<span class="hp-tab is-hovered" role="tab" aria-selected="false"><span class="hp-fav" aria-hidden="true">D</span>Docs' +
          (hoverPreviewMuted
            ? '<span class="hp-audio is-muted" aria-hidden="true">' + tourIcon('audio') + '</span>'
            : '<span class="hp-audio is-on" aria-hidden="true">' + tourIcon('audio') + '</span>') +
          '</span>') +
      '<span class="hp-new" aria-hidden="true">+</span>' +
      '</div>' +
      (hoverPreviewClosed
        ? '<div class="hp-closed"><strong>Tab closed</strong><span>The preview and its tab are gone.</span>' +
          '<button type="button" data-onboard="hp-reopen">Reopen tab</button></div>'
        : '<div class="hp-preview" role="group" aria-label="Tab hover preview">' +
          '<div class="hp-thumb" aria-hidden="true"><span class="hp-thumb-bar"></span>' +
          '<span class="hp-thumb-line is-title"></span><span class="hp-thumb-line"></span>' +
          '<span class="hp-thumb-line is-short"></span></div>' +
          '<div class="hp-copy"><strong>VAAYVU documentation</strong>' +
          '<span class="hp-url">github.com/Mahesh-Vanga/.../docs</span></div>' +
          '<div class="hp-actions"><button type="button" class="hp-mute' +
          (hoverPreviewMuted ? ' is-muted' : '') +
          '" data-onboard="hp-mute" aria-pressed="' +
          hoverPreviewMuted +
          '" aria-label="' +
          (hoverPreviewMuted ? 'Unmute tab' : 'Mute tab') +
          '">' +
          tourIcon('audio') +
          '</button><button type="button" class="hp-close" data-onboard="hp-close" aria-label="Close tab">' +
          tourIcon('x') +
          '</button></div></div>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-hoverpreview">' +
      '<li><strong>01 Thumbnail</strong><span>A small page preview, not a second live tab.</span></li>' +
      '<li><strong>02 Title and URL</strong><span>The page name and its address, shortened.</span></li>' +
      '<li><strong>03 Close and mute</strong><span>Both actions stay in the preview.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="hp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderGroupCollapsed() {
    const count = GROUP_TABS.length;
    const tabs = GROUP_TABS.map(
      (title, index) =>
        '<span class="gc-tab' +
        (index === 0 ? ' is-active' : '') +
        '" role="tab" aria-selected="' +
        (index === 0) +
        '">' +
        esc(title) +
        '</span>',
    ).join('');
    return (
      '<div class="onboarding-groupcollapsed">' +
      '<div class="gc-strip" role="tablist" aria-label="Tabs">' +
      '<span class="gc-group' +
      (groupCollapsed ? ' is-collapsed' : '') +
      '">' +
      (groupCollapsed
        ? '<button type="button" class="gc-header" data-onboard="gc-toggle" aria-expanded="false" aria-label="Expand Research group, ' +
          count +
          ' tabs">' +
          '<span class="gc-dot" aria-hidden="true"></span>' +
          '<span class="gc-name">Research</span>' +
          '<span class="gc-count">' +
          count +
          '</span>' +
          '<span class="gc-chevron" aria-hidden="true">&#8250;</span>' +
          '</button>'
        : '<button type="button" class="gc-header" data-onboard="gc-toggle" aria-expanded="true" aria-label="Collapse Research group, ' +
          count +
          ' tabs">' +
          '<span class="gc-dot" aria-hidden="true"></span>' +
          '<span class="gc-name">Research</span>' +
          '<span class="gc-count">' +
          count +
          '</span>' +
          '<span class="gc-chevron is-open" aria-hidden="true">&#8250;</span>' +
          '</button>' +
          '<span class="gc-tabs">' +
          tabs +
          '</span>') +
      '</span>' +
      '<span class="gc-solo">Observatory</span>' +
      '<span class="gc-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="gc-stage">' +
      '<span class="gc-kicker">' +
      (groupCollapsed ? 'Collapsed group' : 'Expanded group') +
      '</span>' +
      '<strong>Research · ' +
      count +
      ' tabs</strong>' +
      '<small>' +
      (groupCollapsed
        ? 'One coloured header stands in for the whole group.'
        : 'Every tab keeps the group colour on its edge.') +
      '</small>' +
      '<span class="gc-line"></span><span class="gc-line short"></span>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Colour</strong><span>The header carries the group colour even when collapsed.</span></li>' +
      '<li><strong>02 Count</strong><span>The number of tabs stays visible at all times.</span></li>' +
      '<li><strong>03 Expand</strong><span>Open the group to reach every tab, collapse to reclaim the strip.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="gc-toggle">' +
      (groupCollapsed ? 'Expand group' : 'Collapse group') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="gc-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(groupMessage || (groupCollapsed ? 'Research group collapsed, ' + count + ' tabs.' : 'Research group expanded, ' + count + ' tabs.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderGroupExpanded() {
    const count = groupExpandedTabs.length;
    const status =
      groupExpandedMessage ||
      (groupExpandedClosed
        ? groupExpandedName + ' group closed.'
        : groupExpandedName + ' group expanded, ' + count + (count === 1 ? ' tab.' : ' tabs.'));
    const tabs = groupExpandedTabs
      .map(
        (title, index) =>
          '<span class="ge-tab' +
          (index === 0 ? ' is-active' : '') +
          '" role="tab" aria-selected="' +
          (index === 0) +
          '"><span class="ge-tab-title">' +
          esc(title) +
          '</span><button type="button" class="ge-tab-close" data-onboard="ge-tab-close" data-ge-title="' +
          esc(title) +
          '" aria-label="Close ' +
          esc(title) +
          '">&#215;</button></span>',
      )
      .join('');
    return (
      '<div class="onboarding-groupexpanded">' +
      '<div class="ge-strip" role="tablist" aria-label="Tabs">' +
      (groupExpandedClosed
        ? '<span class="ge-closed"><span>' + esc(groupExpandedName) + ' group closed</span>' +
          '<button type="button" data-onboard="ge-reopen">Reopen group</button></span>'
        : '<span class="ge-group" style="--group-color:' + groupExpandedColor + '">' +
          '<span class="ge-head"><span class="ge-dot" aria-hidden="true"></span>' +
          '<span class="ge-name">' + esc(groupExpandedName) + '</span>' +
          '<span class="ge-count">' + count + '</span>' +
          '<button type="button" class="ge-btn" data-onboard="ge-edit">Edit</button>' +
          '<button type="button" class="ge-close-group" data-onboard="ge-close" aria-label="Close ' + esc(groupExpandedName) + ' group">&#215;</button></span>' +
          '<span class="ge-tabs">' + (count ? tabs : '<span class="ge-empty">No tabs in this group.</span>') + '</span></span>') +
      '<span class="ge-solo">Observatory</span><span class="ge-new" aria-hidden="true">+</span>' +
      '</div>' +
      '<div class="ge-stage">' +
      '<span class="ge-kicker">' + (groupExpandedClosed ? 'Closed group' : 'Expanded group') + '</span>' +
      '<strong>' + esc(groupExpandedName) + ' · ' + count + ' tabs</strong>' +
      '<small>' + (groupExpandedClosed ? 'Reopen to restore its tabs.' : 'Every tab keeps the group colour on its edge.') + '</small>' +
      '<span class="ge-line"></span><span class="ge-line short"></span>' +
      '</div>' +
      (groupExpandedEditing && !groupExpandedClosed
        ? '<div class="ge-editor"><label>Group name<input data-group-name maxlength="40" value="' + esc(groupExpandedEditName) + '" /></label>' +
          '<span class="ge-editor-label">Group colour</span><div class="ge-colors" role="group" aria-label="Group colour">' +
          GROUP_EXPANDED_COLORS.map(
            (item) =>
              '<button type="button" class="ge-color' +
              (item.color === groupExpandedEditColor ? ' is-active' : '') +
              '" data-onboard="ge-color" data-color="' + item.color + '" aria-label="' + esc(item.name) + '" style="--swatch:' + item.color + '"></button>',
          ).join('') +
          '</div><div class="ge-editor-actions"><button type="button" class="ge-save" data-onboard="ge-save">Save</button>' +
          '<button type="button" class="ge-cancel" data-onboard="ge-cancel">Cancel</button></div></div>'
        : '') +
      '<ol class="onboarding-mainwindow-list is-groupexpanded">' +
      '<li><strong>01 Tabs</strong><span>Every tab stays visible while the group is open.</span></li>' +
      '<li><strong>02 Edit</strong><span>Rename the group and choose its colour.</span></li>' +
      '<li><strong>03 Close</strong><span>Close one tab or the whole group.</span></li>' +
      '<li><strong>04 Group</strong><span>The header keeps the colour and the count.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ge-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' + esc(status) + '</small>' +
      '</div>'
    );
  }

  function renderStackArchive() {
    const query = archiveQuery.trim().toLowerCase();
    const groups = archiveItems
      .map((group) => ({
        ...group,
        tabs: group.tabs.filter(
          (tab) =>
            !query ||
            (tab.title + ' ' + tab.host + ' ' + group.name).toLowerCase().includes(query),
        ),
      }))
      .filter((group) => group.tabs.length);
    const total = archiveItems.reduce((sum, group) => sum + group.tabs.length, 0);
    const status =
      archiveMessage ||
      (archiveItems.length
        ? total + ' archived tabs in ' + archiveItems.length + ' stacks.'
        : 'Nothing archived.');
    const tabRow = (group, tab) =>
      '<button type="button" class="ar-tab" data-onboard="ar-tab" data-ar-group="' +
      group.id +
      '" data-ar-title="' +
      esc(tab.title) +
      '"><span class="ar-tab-copy"><strong>' +
      esc(tab.title) +
      '</strong><small>' +
      esc(tab.host) +
      '</small></span><span class="ar-restore-tab" aria-hidden="true">&#8634;</span></button>';
    return (
      '<div class="onboarding-archive">' +
      '<div class="ar-stage">' +
      '<div class="ar-head"><strong>Archive</strong><span>' +
      archiveItems.length +
      (archiveItems.length === 1 ? ' stack' : ' stacks') +
      '</span></div>' +
      '<label class="ar-search"><span aria-hidden="true">' +
      tourIcon('search') +
      '</span><input type="text" data-archive-search value="' +
      esc(archiveQuery) +
      '" placeholder="Search archived tabs" autocomplete="off" spellcheck="false" /></label>' +
      '<div class="ar-list">' +
      (groups.length
        ? groups
            .map(
              (group) =>
                '<div class="ar-stack"><div class="ar-stack-head"><span class="ar-emoji" aria-hidden="true">' +
                group.emoji +
                '</span><span class="ar-copy"><strong>' +
                esc(group.name) +
                '</strong><small>' +
                esc(group.date) +
                ' · ' +
                group.tabs.length +
                (group.tabs.length === 1 ? ' page' : ' pages') +
                '</small></span><button type="button" class="ar-restore" data-onboard="ar-restore" data-ar-group="' +
                group.id +
                '">Restore</button></div>' +
                '<div class="ar-tabs">' +
                group.tabs.map((tab) => tabRow(group, tab)).join('') +
                '</div></div>',
            )
            .join('')
        : '<p class="ar-empty">' +
          (archiveItems.length ? 'No archived tabs match that search.' : 'Nothing archived.') +
          '</p>') +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-archive">' +
      '<li><strong>01 Stacks</strong><span>A space is archived as a stack of its pages.</span></li>' +
      '<li><strong>02 Restore</strong><span>Restore the whole stack or a single page.</span></li>' +
      '<li><strong>03 Search</strong><span>Filter by page title, host or stack name.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ar-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderSplit2Up() {
    const pane = (side) => {
      const title = splitPanes[side === 'left' ? 0 : 1];
      const isActive = splitActive === side;
      return (
        '<section class="sp-pane' +
        (isActive ? ' is-active' : '') +
        '" data-side="' +
        side +
        '" aria-label="' +
        esc(title) +
        ' pane">' +
        '<header class="sp-head"><span class="sp-dot" aria-hidden="true"></span><span class="sp-title">' +
        esc(title) +
        '</span><span class="sp-ctrl">' +
        '<button type="button" data-onboard="sp-focus" data-side="' +
        side +
        '" aria-pressed="' +
        isActive +
        '" aria-label="Focus ' +
        esc(title) +
        '">&#9678;</button>' +
        '<button type="button" data-onboard="sp-close" data-side="' +
        side +
        '" aria-label="Close ' +
        esc(title) +
        '">&#215;</button>' +
        '</span></header>' +
        '<div class="sp-body"><span class="sp-line"></span><span class="sp-line"></span><span class="sp-line short"></span>' +
        '<span class="sp-block"></span><span class="sp-block short"></span></div>' +
        '</section>'
      );
    };
    const single = !!splitClosed;
    return (
      '<div class="onboarding-split2up">' +
      '<div class="sp-stage' +
      (single ? ' is-single' : '') +
      '" data-active="' +
      splitActive +
      '" style="--split:' +
      splitDivider +
      '%">' +
      (splitClosed === 'left' ? '' : pane('left')) +
      (single
        ? ''
        : '<button type="button" class="sp-divider" data-onboard="sp-divider" role="separator" aria-orientation="vertical" aria-valuemin="25" aria-valuemax="75" aria-valuenow="' +
          splitDivider +
          '" aria-label="Pane divider"><span class="sp-grip" aria-hidden="true">&#8942;</span></button>') +
      (splitClosed === 'right' ? '' : pane('right')) +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Divider</strong><span>Drag the split; each pane keeps its own page.</span></li>' +
      '<li><strong>02 Swap</strong><span>Exchange the two panes without losing either.</span></li>' +
      '<li><strong>03 Close pane</strong><span>The other pane takes the full window.</span></li>' +
      '<li><strong>04 Focus</strong><span>The focused pane owns the omnibox and keyboard.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="sp-swap"' +
      (single ? ' disabled' : '') +
      '>Swap</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sp-reopen"' +
      (single ? '' : ' disabled') +
      '>Reopen pane</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(splitMessage || (single ? 'Single pane, other side closed.' : 'Split view, divider at ' + splitDivider + '%.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderSplitGrid() {
    const panes = splitGridPanes.slice(0, splitGridLayout);
    const status =
      splitGridMessage ||
      (panes.length
        ? splitGridLayout + '-up grid, ' + panes.length + (panes.length === 1 ? ' pane.' : ' panes.')
        : 'No panes open.');
    const pane = (item, index) => {
      const active = splitGridActive === index;
      const tool = (name, label, iconName, disabled) =>
        '<button type="button" class="sg-tool" data-onboard="' +
        name +
        '" data-pane="' +
        index +
        '" aria-label="' +
        label +
        ' in ' +
        esc(item.title) +
        '"' +
        (disabled ? ' disabled' : '') +
        '>' +
        tourIcon(iconName) +
        '</button>';
      return (
        '<section class="sg-pane' +
        (active ? ' is-active' : '') +
        '" data-sg-pane="' +
        index +
        '" aria-label="' +
        esc(item.title) +
        ' pane">' +
        '<header class="sg-head"><span class="sg-dot" aria-hidden="true"></span>' +
        '<button type="button" class="sg-title" data-onboard="sg-focus" data-pane="' +
        index +
        '" aria-pressed="' +
        active +
        '">' +
        esc(item.title) +
        '</button><span class="sg-tools">' +
        tool('sg-back', 'Back', 'back', item.depth <= 0) +
        tool('sg-forward', 'Forward', 'forward', item.depth >= 3) +
        tool('sg-reload', 'Reload', 'reload', false) +
        '<button type="button" class="sg-tool is-close" data-onboard="sg-close" data-pane="' +
        index +
        '" aria-label="Close ' +
        esc(item.title) +
        ' pane">&#215;</button>' +
        '</span></header>' +
        '<div class="sg-page"><span class="sg-host">' +
        esc(item.host) +
        '</span><span class="sg-line"></span><span class="sg-line"></span>' +
        '<span class="sg-line short"></span>' +
        (item.reloads
          ? '<small class="sg-reloads">' + item.reloads + ' reload' + (item.reloads === 1 ? '' : 's') + ' in this pane</small>'
          : '') +
        '</div></section>'
      );
    };
    return (
      '<div class="onboarding-splitgrid">' +
      '<div class="sg-bar">' +
      '<span class="sg-bar-label">' + splitGridLayout + '-up</span>' +
      '<button type="button" class="sg-bar-btn" data-onboard="sg-layout">' +
      (splitGridLayout === 4 ? 'Use 3-up' : 'Use 4-up') +
      '</button>' +
      '<button type="button" class="sg-bar-btn" data-onboard="sg-add"' +
      (splitGridClosed.length ? '' : ' disabled') +
      '>' +
      tourIcon('plus') +
      ' Add pane</button>' +
      '</div>' +
      '<div class="sg-grid is-' +
      splitGridLayout +
      '" data-layout="' +
      splitGridLayout +
      '" role="group" aria-label="Split panes">' +
      (panes.length ? panes.map(pane).join('') : '<p class="sg-empty">No panes open. Add a pane to start again.</p>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-splitgrid">' +
      '<li><strong>01 Grid</strong><span>Three or four panes share the window evenly.</span></li>' +
      '<li><strong>02 Pane</strong><span>Click a pane to give it the omnibox and keyboard.</span></li>' +
      '<li><strong>03 Toolbar</strong><span>Back, forward and reload act on that pane only.</span></li>' +
      '<li><strong>04 Close and add</strong><span>Close a pane, then add it back when you need it.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="sg-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderTabSearch() {
    const results = tabSearchResults();
    const selected = results.find((item) => item.id === tabSearchSelected) || results[0] || null;
    const rows = results.length
      ? results
          .map(
            (item) =>
              '<button type="button" class="ts-row' +
              (selected && selected.id === item.id ? ' is-selected' : '') +
              '" data-onboard="ts-select" data-id="' +
              item.id +
              '" role="option" aria-selected="' +
              !!(selected && selected.id === item.id) +
              '"><span class="ts-mark" aria-hidden="true">' +
              esc(item.title.slice(0, 1)) +
              '</span><span class="ts-row-text"><strong>' +
              esc(item.title) +
              '</strong><small>' +
              esc(item.host) +
              ' · ' +
              esc(item.space) +
              '</small></span></button>',
          )
          .join('')
      : '<div class="ts-empty"><strong>No tabs match</strong><span>Try a title, address or space.</span></div>';
    return (
      '<div class="onboarding-tabsearch">' +
      '<div class="ts-panel">' +
      '<label class="ts-field"><span class="ts-field-icon" aria-hidden="true">' +
      tourIcon('search') +
      '</span><input type="text" data-tab-search value="' +
      esc(tabSearchQuery) +
      '" placeholder="Search tabs" aria-label="Search tabs"></label>' +
      '<div class="ts-results" role="listbox" aria-label="Matching tabs">' +
      rows +
      '</div>' +
      '</div>' +
      (selected
        ? '<div class="ts-preview">' +
          '<span class="ts-preview-label">Preview</span>' +
          '<div class="ts-preview-head"><span class="ts-mark is-large" aria-hidden="true">' +
          esc(selected.title.slice(0, 1)) +
          '</span><div><strong>' +
          esc(selected.title) +
          '</strong><small>' +
          esc(selected.host) +
          ' · ' +
          esc(selected.space) +
          '</small></div></div>' +
          '<span class="ts-line"></span><span class="ts-line"></span><span class="ts-line short"></span>' +
          '<span class="ts-preview-state">' +
          (tabSearchOpened ? 'Opened in a new window' : 'Ready to switch') +
          '</span>' +
          '</div>'
        : '') +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Fuzzy</strong><span>Letters match in order across title, address and space.</span></li>' +
      '<li><strong>02 Preview</strong><span>The selected result is shown before you commit.</span></li>' +
      '<li><strong>03 Switch</strong><span>Jump to the tab, or open it in a new window.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ts-switch"' +
      (selected ? '' : ' disabled') +
      '>Switch to tab</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="ts-new-window"' +
      (selected ? '' : ' disabled') +
      '>New window</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="ts-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(
        tabSearchMessage ||
          (results.length
            ? results.length + (results.length === 1 ? ' tab matches' : ' tabs match') + '.'
            : 'No tabs match.'),
      ) +
      '</small>' +
      '</div>'
    );
  }

  function renderMobileTabGrid() {
    const privateMode = mobileGridPrivateMode;
    const normalCount = mobileGridGroups.reduce((sum, group) => sum + group.tabs.length, 0);
    const privateCount = mobileGridPrivate.length;
    const count = privateMode ? privateCount : normalCount;
    const status =
      mobileGridMessage ||
      (privateMode
        ? privateCount
          ? privateCount + (privateCount === 1 ? ' private tab.' : ' private tabs.')
          : 'No private tabs.'
        : normalCount
          ? normalCount + ' tabs in ' + mobileGridGroups.length + ' groups.'
          : 'No open tabs.');
    const card = (tab, groupId) => {
      const active = mobileGridSelected === tab.title;
      return (
        '<button type="button" class="mg-card' +
        (active ? ' is-active' : '') +
        '" data-onboard="mg-card" data-mg-group="' +
        groupId +
        '" data-mg-title="' +
        esc(tab.title) +
        '" aria-pressed="' +
        active +
        '"><span class="mg-fav" aria-hidden="true">' +
        esc(tab.icon || tab.title.slice(0, 1).toUpperCase()) +
        '</span><span class="mg-card-copy"><strong>' +
        esc(tab.title) +
        '</strong><small>' +
        esc(tab.host) +
        '</small></span></button>'
      );
    };
    const groups = privateMode
      ? [
          {
            id: 'private',
            name: 'Private',
            color: '#296c59',
            tabs: mobileGridPrivate,
          },
        ]
      : mobileGridGroups;
    return (
      '<div class="onboarding-mobilegrid">' +
      '<div class="mg-phone">' +
      '<div class="mg-bar">' +
      '<span class="mg-tabs">' +
      '<button type="button" class="mg-tab' +
      (privateMode ? '' : ' is-active') +
      '" data-onboard="mg-mode" aria-pressed="' +
      (!privateMode) +
      '">Tabs</button>' +
      '<button type="button" class="mg-tab' +
      (privateMode ? ' is-active' : '') +
      '" data-onboard="mg-mode-private" aria-pressed="' +
      privateMode +
      '">Private</button>' +
      '</span>' +
      '<button type="button" class="mg-closeall" data-onboard="mg-close-all"' +
      (count ? '' : ' disabled') +
      '>Close all</button>' +
      '</div>' +
      '<div class="mg-grid' +
      (privateMode ? ' is-private' : '') +
      '">' +
      (count
        ? groups
            .filter((group) => group.tabs.length)
            .map(
              (group) =>
                '<section class="mg-group" style="--mg-color:' +
                group.color +
                '"><header class="mg-group-head"><span class="mg-dot" aria-hidden="true"></span><strong>' +
                esc(group.name) +
                '</strong><span class="mg-count">' +
                group.tabs.length +
                '</span></header><div class="mg-cards">' +
                group.tabs.map((tab) => card(tab, group.id)).join('') +
                '</div></section>',
            )
            .join('')
        : '<div class="mg-empty"><strong>' +
          (privateMode ? 'No private tabs' : 'No open tabs') +
          '</strong><span>' +
          (privateMode
            ? 'Private tabs never join your history.'
            : 'Everything closed. Restore the grid to look again.') +
          '</span><button type="button" data-onboard="mg-restore">Restore tabs</button></div>') +
      '</div>' +
      '<p class="mg-note" role="status">' +
      esc(privateCount ? privateCount + ' private tab' + (privateCount === 1 ? '' : 's') + ' stay out of history.' : 'No private tabs open.') +
      '</p>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-mobilegrid">' +
      '<li><strong>01 Cards</strong><span>Each tab is a card with its icon, title and host.</span></li>' +
      '<li><strong>02 Groups</strong><span>Cards stay under their group and keep its colour.</span></li>' +
      '<li><strong>03 Close all</strong><span>Closes every card in the open view.</span></li>' +
      '<li><strong>04 Private</strong><span>Private cards are separate and never enter history.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="mg-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderMobileTabList() {
    const query = mobileListQuery.trim().toLowerCase();
    const rows = mobileListRows.filter(
      (row) => !query || (row.title + ' ' + row.host + ' ' + row.group).toLowerCase().includes(query),
    );
    const status =
      mobileListMessage ||
      (mobileListQuery.trim()
        ? rows.length + ' of ' + mobileListRows.length + ' tabs match.'
        : mobileListRows.length + ' tabs in a compact list.');
    return (
      '<div class="onboarding-mobilelist">' +
      '<div class="ml-phone">' +
      '<label class="ml-search"><span aria-hidden="true">' +
      tourIcon('search') +
      '</span><input type="text" data-mobile-list-search value="' +
      esc(mobileListQuery) +
      '" placeholder="Search tabs" autocomplete="off" spellcheck="false" />' +
      (mobileListQuery
        ? '<button type="button" class="ml-clear" data-onboard="ml-clear" aria-label="Clear search">&#215;</button>'
        : '') +
      '</label>' +
      '<div class="ml-rows" role="list" aria-label="Tabs">' +
      (rows.length
        ? rows
            .map(
              (row) =>
                '<button type="button" class="ml-row' +
                (mobileListSelected === row.title ? ' is-active' : '') +
                '" role="listitem" data-onboard="ml-card" data-ml-title="' +
                esc(row.title) +
                '" aria-pressed="' +
                (mobileListSelected === row.title) +
                '"><span class="ml-fav" aria-hidden="true">' +
                esc(row.icon || row.title.slice(0, 1).toUpperCase()) +
                '</span><span class="ml-copy"><strong>' +
                esc(row.title) +
                '</strong><small>' +
                esc(row.host) +
                '</small></span><span class="ml-group">' +
                esc(row.group) +
                '</span></button>',
            )
            .join('')
        : '<p class="ml-empty">No tabs match that search.</p>') +
      '</div>' +
      '<p class="ml-note" role="status">' +
      esc(mobileListRows.length + ' open tabs · rows are compact so more fit on screen.') +
      '</p>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-mobilelist">' +
      '<li><strong>01 Rows</strong><span>One short row per tab, with its icon and host.</span></li>' +
      '<li><strong>02 Search</strong><span>Filters by title, host or group as you type.</span></li>' +
      '<li><strong>03 Group tag</strong><span>Each row shows which group it belongs to.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ml-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderGroupEditor() {
    const name = groupEditorName.trim() || 'Untitled group';
    const colors = GROUP_EDITOR_COLORS.map(
      (color) =>
        '<button type="button" class="tge-swatch' +
        (color === groupEditorColor ? ' is-active' : '') +
        '" data-onboard="tge-color" data-color="' +
        color +
        '" aria-pressed="' +
        (color === groupEditorColor) +
        '" aria-label="Group colour ' +
        color +
        '" style="--swatch:' +
        color +
        '"></button>',
    ).join('');
    const emoji = GROUP_EDITOR_EMOJI.map(
      (mark) =>
        '<button type="button" class="tge-emoji' +
        (mark === groupEditorEmoji ? ' is-active' : '') +
        '" data-onboard="tge-emoji" data-emoji="' +
        esc(mark) +
        '" aria-pressed="' +
        (mark === groupEditorEmoji) +
        '" aria-label="Group emoji ' +
        esc(mark) +
        '">' +
        esc(mark) +
        '</button>',
    ).join('');
    return (
      '<div class="onboarding-groupeditor">' +
      '<div class="tge-preview" style="--group-color:' +
      groupEditorColor +
      '">' +
      '<div class="tge-preview-head"><span class="tge-emoji is-large" aria-hidden="true">' +
      esc(groupEditorEmoji) +
      '</span><span class="tge-preview-name">' +
      esc(name) +
      '</span><span class="tge-count">3</span>' +
      (groupEditorSaved ? '<span class="tge-saved">Saved</span>' : '') +
      '</div>' +
      '<span class="tge-tab is-active">Reading list</span>' +
      '<span class="tge-tab">Arc paper</span>' +
      '<span class="tge-tab">Notes</span>' +
      '</div>' +
      '<div class="tge-form">' +
      '<label class="tge-field"><span class="tge-label">Name</span>' +
      '<input type="text" data-group-editor-name value="' +
      esc(groupEditorName) +
      '" maxlength="40" aria-label="Group name"></label>' +
      '<div class="tge-block"><span class="tge-label">Colour</span><div class="tge-swatches">' +
      colors +
      '</div></div>' +
      '<div class="tge-block"><span class="tge-label">Emoji</span><div class="tge-emojis">' +
      emoji +
      '</div></div>' +
      '<div class="tge-sync"><span><strong>Sync group</strong><small>Keep the name, colour and emoji across devices.</small></span>' +
      '<button type="button" class="tge-switch' +
      (groupEditorSync ? ' is-on' : '') +
      '" role="switch" data-onboard="tge-sync" aria-checked="' +
      groupEditorSync +
      '" aria-label="Sync group"><span class="tge-thumb" aria-hidden="true"></span></button></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Name</strong><span>The header uses the name as you type.</span></li>' +
      '<li><strong>02 Colour and emoji</strong><span>Both appear in the tab strip, not just here.</span></li>' +
      '<li><strong>03 Save</strong><span>Save writes the group on this device.</span></li>' +
      '<li><strong>04 Sync</strong><span>When on, the saved group follows your account.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="tge-save">Save group</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="tge-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(
        groupEditorMessage ||
          (groupEditorSync ? 'Sync is on.' : 'Sync is off.'),
      ) +
      '</small>' +
      '</div>'
    );
  }

  function renderTabContentMenu() {
    const labelFor = (id, label) => {
      if (id === 'pin' && tabMenuPinned) return 'Unpin tab';
      if (id === 'mute' && tabMenuMuted) return 'Unmute tab';
      return label;
    };
    const sections = [];
    for (const [id, section, label, shortcut] of TAB_CONTENT_MENU) {
      let group = sections.find((entry) => entry.name === section);
      if (!group) {
        group = { name: section, items: [] };
        sections.push(group);
      }
      group.items.push({ id, label: labelFor(id, label), shortcut });
    }
    const menu = sections
      .map(
        (section) =>
          '<div class="tc-section"><span class="tc-section-label">' +
          section.name +
          '</span>' +
          section.items
            .map(
              (item) =>
                '<button type="button" class="tc-item" role="menuitem" data-onboard="tc-action" data-action="' +
                item.id +
                '"><span class="tc-item-label">' +
                esc(item.label) +
                '</span>' +
                (item.shortcut ? '<kbd class="tc-key">' + item.shortcut + '</kbd>' : '') +
                '</button>',
            )
            .join('') +
          '</div>',
      )
      .join('');
    const badges = [
      tabMenuPinned ? '<span class="tc-badge">Pinned</span>' : '',
      tabMenuMuted ? '<span class="tc-badge">Muted</span>' : '',
      tabMenuGrouped ? '<span class="tc-badge is-group">Research</span>' : '',
      tabMenuClosed ? '<span class="tc-badge is-closed">Closed</span>' : '',
    ].join('');
    return (
      '<div class="onboarding-tabmenu">' +
      '<div class="tc-tab' +
      (tabMenuClosed ? ' is-closed' : '') +
      '" style="--tc-color:#6653bb">' +
      '<span class="tc-fav" aria-hidden="true">A</span>' +
      '<span class="tc-title">Arc paper</span>' +
      '<span class="tc-badges">' +
      badges +
      '</span>' +
      '</div>' +
      '<div class="tc-panel" role="menu" aria-label="Tab actions">' +
      '<div class="tc-head"><strong>Tab actions</strong><span class="tc-count" aria-label="25 actions">25</span></div>' +
      '<div class="tc-scroll">' +
      menu +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Sections</strong><span>Actions are grouped: tab, group, page, share and close.</span></li>' +
      '<li><strong>02 State</strong><span>Pin, mute and group update the badges on the tab.</span></li>' +
      '<li><strong>03 Scope</strong><span>Every action applies to this tab, not the window.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="tc-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="tc-reset">Reset menu</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(tabMenuMessage || '25 actions for Arc paper.') +
      '</small>' +
      '</div>'
    );
  }

  function renderDragReorder() {
    const lifted = dragLift >= 0 ? dragTabs[dragLift] : null;
    const remaining = dragTabs.filter((_, index) => index !== dragLift);
    const status =
      dragMessage ||
      (lifted
        ? 'Lifted ' + lifted + '. Move the gap, then drop.'
        : dragTabs.length + ' tabs. Lift one to start.');
    const tabButton = (title) =>
      '<button type="button" class="dr-tab" data-onboard="dr-lift" data-dr-title="' +
      esc(title) +
      '" aria-pressed="' +
      (title === lifted) +
      '">' +
      esc(title) +
      '</button>';
    const strip = lifted
      ? remaining
          .map(
            (title, index) =>
              (index === dragGap
                ? '<span class="dr-gap" data-dr-gap="' + dragGap + '" aria-hidden="true"></span>'
                : '') + tabButton(title),
          )
          .join('') + (dragGap >= remaining.length ? '<span class="dr-gap" aria-hidden="true"></span>' : '')
      : dragTabs.map(tabButton).join('');
    return (
      '<div class="onboarding-dragreorder">' +
      '<div class="dr-stage' +
      (dragScrolling ? ' is-scrolling' : '') +
      '">' +
      '<div class="dr-strip" role="tablist" aria-label="Tabs">' +
      strip +
      '</div>' +
      (lifted
        ? '<div class="dr-chip" aria-label="Lifted tab"><span class="dr-chip-dot" aria-hidden="true"></span>' +
          esc(lifted) +
          '<small>Lifted</small></div>'
        : '') +
      '</div>' +
      '<div class="dr-controls">' +
      '<button type="button" class="dr-btn" data-onboard="dr-left"' +
      (lifted && dragGap > 0 ? '' : ' disabled') +
      '>Earlier</button>' +
      '<button type="button" class="dr-btn" data-onboard="dr-right"' +
      (lifted && dragGap < remaining.length ? '' : ' disabled') +
      '>Later</button>' +
      '<button type="button" class="dr-btn" data-onboard="dr-scroll" aria-pressed="' +
      dragScrolling +
      '"' +
      (lifted ? '' : ' disabled') +
      '>Auto-scroll</button>' +
      '<button type="button" class="dr-drop" data-onboard="dr-drop"' +
      (lifted ? '' : ' disabled') +
      '>Drop</button>' +
      '<button type="button" class="dr-cancel" data-onboard="dr-cancel"' +
      (lifted ? '' : ' disabled') +
      '>Cancel</button>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-dragreorder">' +
      '<li><strong>01 Lift</strong><span>The tab lifts above the strip.</span></li>' +
      '<li><strong>02 Gap</strong><span>A gap shows exactly where it will land.</span></li>' +
      '<li><strong>03 Auto-scroll</strong><span>The strip follows the pointer near an edge.</span></li>' +
      '<li><strong>04 Drop</strong><span>Dropping commits the new order.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="dr-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderCloseUndo() {
    const tabs = [
      ...undoOpenTabs.map((title) => ({ title, closed: false })),
      ...undoClosedTabs.map((title) => ({ title, closed: true })),
    ]
      .map(
        (tab) =>
          '<span class="uc-tab' +
          (tab.closed ? ' is-closed' : '') +
          '"' +
          (tab.closed ? ' title="Closed, still restorable"' : '') +
          '>' +
          esc(tab.title) +
          '</span>',
      )
      .join('');
    const closedCount = undoClosedTabs.length;
    const progress = Math.max(0, Math.min(8, undoSeconds)) / 8;
    return (
      '<div class="onboarding-undo">' +
      '<div class="uc-stage">' +
      '<div class="uc-strip"><span class="uc-strip-label">Tabs</span>' +
      (tabs || '<span class="uc-empty-strip">No tabs open</span>') +
      '<button type="button" class="uc-close-all" data-onboard="uc-close-all">Close all</button>' +
      '</div>' +
      '<div class="uc-page"><span class="uc-page-kicker">' +
      (undoOpenTabs.length ? 'One tab left' : 'All tabs closed') +
      '</span><strong>' +
      (undoOpenTabs.length ? esc(undoOpenTabs[0]) : 'Nothing open') +
      '</strong><span class="uc-line"></span><span class="uc-line short"></span></div>' +
      (undoToast && closedCount
        ? '<div class="uc-toast" role="status">' +
          '<span class="uc-timer" style="--undo:' +
          progress +
          '" aria-label="' +
          undoSeconds +
          ' seconds left"><strong>' +
          undoSeconds +
          's</strong><small>undo</small></span>' +
          '<span class="uc-copy"><strong>' +
          closedCount +
          (closedCount === 1 ? ' tab closed' : ' tabs closed') +
          '</strong><small>Undo available for ' +
          undoSeconds +
          ' second' +
          (undoSeconds === 1 ? '' : 's') +
          '.</small></span>' +
          '<button type="button" class="uc-undo" data-onboard="uc-undo">Undo</button>' +
          '<button type="button" class="uc-dismiss" data-onboard="uc-dismiss" aria-label="Dismiss toast">&#215;</button>' +
          '</div>'
        : '<div class="uc-toast is-passive"><span class="uc-copy"><strong>No undo pending</strong><small>Closed tabs stay in History.</small></span></div>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 8 seconds</strong><span>The toast counts down and then leaves History as the only route back.</span></li>' +
      '<li><strong>02 Undo</strong><span>Restores every tab in the batch, in order.</span></li>' +
      '<li><strong>03 Close all</strong><span>Closes the rest and refreshes the same toast.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="uc-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="uc-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(undoMessage || (undoToast ? 'Undo available for ' + undoSeconds + 's.' : 'No undo pending.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderTearOff() {
    const lifted = tearOffLifted;
    const detached = tearOffDetached;
    const status =
      tearOffMessage ||
      (detached
        ? detached + ' is in its own window.'
        : lifted
          ? 'Ghost window: ' + lifted + '. Drop to detach, or cancel.'
          : tearOffTabs.length + ' tabs in the main window. Lift one to preview a new window.');
    const tabButton = (title) =>
      '<button type="button" class="tp-tab' +
      (title === lifted ? ' is-lifted' : '') +
      '" data-onboard="tp-lift" data-tp-title="' +
      esc(title) +
      '" aria-pressed="' +
      (title === lifted) +
      '"' +
      (detached ? ' disabled' : '') +
      '>' +
      esc(title) +
      '</button>';
    const strip = tearOffTabs
      .map((title) => (title === lifted ? '<span class="tp-gap" aria-hidden="true"></span>' : tabButton(title)))
      .join('');
    return (
      '<div class="onboarding-tearoff">' +
      '<div class="tp-stage">' +
      '<section class="tp-window" aria-label="Main window">' +
      '<header class="tp-titlebar"><span class="tp-dots" aria-hidden="true"><i></i><i></i><i></i></span><span class="tp-window-name">Main window</span></header>' +
      '<div class="tp-strip" role="tablist" aria-label="Tabs">' +
      strip +
      '</div>' +
      '<div class="tp-page"><span class="tp-line"></span><span class="tp-line"></span><span class="tp-line short"></span></div>' +
      '</section>' +
      (lifted
        ? '<aside class="tp-ghost" aria-label="Ghost window preview"><header class="tp-ghost-bar"><span class="tp-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>New window</span></header><strong>' +
          esc(lifted) +
          '</strong><small>Ghost preview · drop to detach</small></aside>'
        : '') +
      (detached
        ? '<aside class="tp-detached" aria-label="Detached window"><header class="tp-ghost-bar"><span class="tp-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>New window</span></header><strong>' +
          esc(detached) +
          '</strong><small>Detached window</small><button type="button" class="tp-reattach" data-onboard="tp-reattach">Reattach</button></aside>'
        : '') +
      '</div>' +
      '<div class="tp-controls">' +
      '<button type="button" class="tp-drop" data-onboard="tp-drop"' +
      (lifted ? '' : ' disabled') +
      '>Drop to detach</button>' +
      '<button type="button" class="tp-cancel" data-onboard="tp-cancel"' +
      (lifted ? '' : ' disabled') +
      '>Cancel</button>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-tearoff">' +
      '<li><strong>01 Ghost window</strong><span>A preview of the new window follows the tab.</span></li>' +
      '<li><strong>02 Drop</strong><span>Dropping outside the strip commits the detach.</span></li>' +
      '<li><strong>03 Detach</strong><span>The tab leaves this window and opens in its own.</span></li>' +
      '<li><strong>04 Reattach</strong><span>Bring the tab back without losing it.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="tp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderAudioMixer() {
    const allMuted = mixerTabs.every((tab) => tab.muted);
    const rows = mixerTabs
      .map((tab) => {
        const active = mixerActive === tab.id;
        return (
          '<div class="mx-row' +
          (active ? ' is-active' : '') +
          (tab.muted ? ' is-muted' : '') +
          '" data-mixer-row="' +
          tab.id +
          '">' +
          '<span class="mx-mark" aria-hidden="true">' +
          esc(tab.title.slice(0, 1)) +
          '</span>' +
          '<span class="mx-id"><strong>' +
          esc(tab.title) +
          '</strong><small>' +
          esc(tab.host) +
          '</small></span>' +
          '<span class="mx-meter" aria-hidden="true">' +
          (tab.muted
            ? '<i class="is-off"></i><i class="is-off"></i><i class="is-off"></i>'
            : '<i style="height:' +
              Math.max(3, Math.round(tab.volume * 0.14)) +
              'px"></i><i style="height:' +
              Math.max(3, Math.round(tab.volume * 0.1)) +
              'px"></i><i style="height:' +
              Math.max(3, Math.round(tab.volume * 0.12)) +
              'px"></i>') +
          '</span>' +
          '<input class="mx-volume" type="range" min="0" max="100" step="1" value="' +
          tab.volume +
          '" data-mixer-volume data-id="' +
          tab.id +
          '" aria-label="' +
          esc(tab.title) +
          ' volume">' +
          '<span class="mx-percent">' +
          (tab.muted ? 'Muted' : tab.volume + '%') +
          '</span>' +
          '<button type="button" class="mx-mute' +
          (tab.muted ? ' is-on' : '') +
          '" data-onboard="mx-mute" data-id="' +
          tab.id +
          '" aria-pressed="' +
          tab.muted +
          '" aria-label="' +
          (tab.muted ? 'Unmute ' : 'Mute ') +
          esc(tab.title) +
          '"><span aria-hidden="true">' +
          (tab.muted ? '\u2715' : '\u266A') +
          '</span></button>' +
          '<button type="button" class="mx-focus' +
          (active ? ' is-active' : '') +
          '" data-onboard="mx-focus" data-id="' +
          tab.id +
          '" aria-pressed="' +
          active +
          '">' +
          (active ? 'Focused' : 'Focus') +
          '</button>' +
          '</div>'
        );
      })
      .join('');
    return (
      '<div class="onboarding-mixer">' +
      '<div class="mx-panel">' +
      '<div class="mx-head"><strong>Audio mixer</strong><span class="mx-count">' +
      mixerTabs.length +
      ' tabs</span></div>' +
      rows +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Per-tab volume</strong><span>Each slider changes that tab only.</span></li>' +
      '<li><strong>02 Mute</strong><span>Mute keeps the level; unmute returns to it.</span></li>' +
      '<li><strong>03 Focus</strong><span>Focus brings the tab forward without touching its sound.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="mx-mute-all">' +
      (allMuted ? 'Unmute all' : 'Mute all') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="mx-reset">Reset levels</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="mx-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(mixerMessage || (allMuted ? 'All tabs muted.' : mixerTabs.length + ' tabs in the mixer.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderRecentlyClosed() {
    const total = recentlyClosed.reduce((sum, group) => sum + group.items.length, 0);
    const status =
      recentlyClosedMessage ||
      (total ? total + ' recently closed items.' : 'Nothing recently closed. Restored items reopen in the main window.');
    return (
      '<div class="onboarding-recentlyclosed">' +
      '<div class="rc-panel">' +
      '<header class="rc-head"><strong>Recently closed</strong><span>' +
      total +
      (total === 1 ? ' item' : ' items') +
      '</span></header>' +
      '<div class="rc-list">' +
      (total
        ? recentlyClosed
            .filter((group) => group.items.length)
            .map(
              (group) =>
                '<section class="rc-section" aria-label="' +
                esc(group.name) +
                '"><header class="rc-section-head"><span class="rc-section-name">' +
                esc(group.name) +
                '</span><span class="rc-section-count">' +
                group.items.length +
                '</span></header>' +
                group.items
                  .map(
                    (item) =>
                      '<button type="button" class="rc-row" data-onboard="rc-restore" data-rc-section="' +
                      group.id +
                      '" data-rc-id="' +
                      item.id +
                      '" aria-label="' +
                      esc(group.verb + ' ' + item.title) +
                      '"><span class="rc-icon" aria-hidden="true">' +
                      (group.id === 'tabs' ? 'T' : group.id === 'windows' ? 'W' : 'G') +
                      '</span><span class="rc-copy"><strong>' +
                      esc(item.title) +
                      '</strong><small>' +
                      esc(item.detail) +
                      '</small></span><span class="rc-when">' +
                      esc(item.when) +
                      '</span><span class="rc-restore">' +
                      esc(group.verb) +
                      '</span></button>',
                  )
                  .join('') +
                '</section>',
            )
            .join('')
        : '<div class="rc-empty"><strong>Nothing recently closed</strong><span>Tabs, windows and groups you close show up here.</span></div>') +
      '</div>' +
      '</div>' +
      '<div class="rc-actions">' +
      '<button type="button" class="rc-restore-all" data-onboard="rc-restore-all"' +
      (total ? '' : ' disabled') +
      '>Restore all</button>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-recentlyclosed">' +
      '<li><strong>01 Tabs</strong><span>Closed tabs, newest first.</span></li>' +
      '<li><strong>02 Windows</strong><span>A whole window with its tab count.</span></li>' +
      '<li><strong>03 Groups</strong><span>A closed tab group and its pages.</span></li>' +
      '<li><strong>04 Restore</strong><span>Restore one item or everything at once.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="rc-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderTabSync() {
    const devices = syncDevices
      .map((device) => {
        const tabs = device.tabs
          .map((tab) => {
            const key = device.id + ':' + tab.id;
            const opened = syncOpened.includes(key);
            return (
              '<span class="sy-tab' +
              (opened ? ' is-opened' : '') +
              '"><span class="sy-tab-id"><strong>' +
              esc(tab.title) +
              '</strong><small>' +
              esc(tab.host) +
              '</small></span>' +
              '<button type="button" data-onboard="sy-open" data-device="' +
              device.id +
              '" data-tab="' +
              tab.id +
              '" aria-label="Open ' +
              esc(tab.title) +
              ' from ' +
              esc(device.name) +
              '">' +
              (opened ? 'Opened' : 'Open') +
              '</button></span>'
            );
          })
          .join('');
        return (
          '<div class="sy-device">' +
          '<div class="sy-device-head"><span class="sy-mark" aria-hidden="true">' +
          esc(device.name.slice(0, 1)) +
          '</span><span class="sy-device-id"><strong>' +
          esc(device.name) +
          '</strong><small>' +
          esc(device.meta) +
          ' · ' +
          device.tabs.length +
          (device.tabs.length === 1 ? ' tab' : ' tabs') +
          '</small></span></div>' +
          '<div class="sy-tabs">' +
          tabs +
          '</div></div>'
        );
      })
      .join('');
    const sendTargets = syncDevices
      .map((device) => {
        const sent = syncSentTo.includes(device.id);
        return (
          '<button type="button" class="sy-send-btn' +
          (sent ? ' is-sent' : '') +
          '" data-onboard="sy-send" data-device="' +
          device.id +
          '" aria-pressed="' +
          sent +
          '">' +
          (sent ? 'Sent' : 'Send') +
          '<small>' +
          esc(device.name) +
          '</small></button>'
        );
      })
      .join('');
    return (
      '<div class="onboarding-sync">' +
      '<div class="sy-panel">' +
      '<div class="sy-head"><strong>Tab sync</strong><span class="sy-count">' +
      syncDevices.length +
      ' devices</span></div>' +
      devices +
      '</div>' +
      '<div class="sy-send">' +
      '<div class="sy-current"><span class="sy-mark is-current" aria-hidden="true">A</span>' +
      '<span class="sy-device-id"><strong>Arc paper</strong><small>This device · arxiv.org</small></span></div>' +
      '<span class="sy-send-label">Send this tab to</span>' +
      '<div class="sy-send-grid">' +
      sendTargets +
      '</div></div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Other devices</strong><span>Each device lists the tabs it has open.</span></li>' +
      '<li><strong>02 Open</strong><span>Pull a tab from another device into this window.</span></li>' +
      '<li><strong>03 Send</strong><span>Push this tab to one device, then the chip reads Sent.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="sy-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sy-reset">Reset panel</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(syncMessage || syncDevices.length + ' other devices available.') +
      '</small>' +
      '</div>'
    );
  }

  function renderMemoryPanel() {
    const inUse = memoryTabs.reduce((sum, tab) => sum + (tab.discarded ? 0 : tab.ram), 0);
    const protectedCount = memoryTabs.filter((tab) => tab.protected).length;
    const status =
      memoryMessage ||
      inUse +
        ' MB across ' +
        memoryTabs.length +
        ' tabs' +
        (protectedCount ? ' · ' + protectedCount + ' protected' : '') +
        '.';
    return (
      '<div class="onboarding-memorypanel">' +
      '<div class="mp-panel">' +
      '<header class="mp-head"><strong>Tab memory</strong><span>' +
      inUse +
      ' MB</span></header>' +
      '<div class="mp-rows">' +
      memoryTabs
        .map(
          (tab) =>
            '<div class="mp-row' +
            (tab.protected ? ' is-protected' : '') +
            (tab.discarded ? ' is-discarded' : '') +
            '"><span class="mp-fav" aria-hidden="true">' +
            esc(tab.icon) +
            '</span><span class="mp-copy"><strong>' +
            esc(tab.title) +
            '</strong><small>' +
            esc(tab.host) +
            '</small></span><span class="mp-ram">' +
            (tab.discarded ? '0 MB' : tab.ram + ' MB') +
            '</span>' +
            (tab.protected ? '<span class="mp-badge">Protected</span>' : '') +
            (tab.discarded ? '<span class="mp-badge is-discarded">Discarded</span>' : '') +
            '<span class="mp-controls">' +
            '<button type="button" class="mp-protect" data-onboard="mem-protect" data-id="' +
            tab.id +
            '" aria-pressed="' +
            tab.protected +
            '">' +
            (tab.protected ? 'Unprotect' : 'Protect') +
            '</button>' +
            '<button type="button" class="mp-discard" data-onboard="mem-discard" data-id="' +
            tab.id +
            '"' +
            (tab.protected || tab.discarded ? ' disabled' : '') +
            '>Discard</button>' +
            (tab.discarded
              ? '<button type="button" class="mp-reload" data-onboard="mem-reload" data-id="' + tab.id + '">Reload</button>'
              : '') +
            '</span></div>',
        )
        .join('') +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-memorypanel">' +
      '<li><strong>01 Per-tab RAM</strong><span>Every row shows the memory that tab holds.</span></li>' +
      '<li><strong>02 Discard</strong><span>Discarding frees the RAM and leaves the tab in place.</span></li>' +
      '<li><strong>03 Protect</strong><span>Protected tabs cannot be discarded.</span></li>' +
      '<li><strong>04 Reload</strong><span>Reloading a discarded tab brings its page and RAM back.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="mem-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderPrivateTabs() {
    const count = privateTabs.length;
    const status =
      privateTabsMessage ||
      (count
        ? count + ' private tabs open. History stays empty.'
        : 'Private window closed. Nothing was written to history.');
    return (
      '<div class="onboarding-privatetabs">' +
      '<div class="pvt-window">' +
      '<header class="pvt-bar"><span class="pvt-mask" aria-hidden="true">&#9673;</span><strong>Private</strong><span class="pvt-bar-note">Not saved to history</span></header>' +
      (count
        ? '<div class="pvt-tabs" role="tablist" aria-label="Private tabs">' +
          privateTabs
            .map(
              (title, index) =>
                '<span class="pvt-tab' +
                (index === 0 ? ' is-active' : '') +
                '" role="tab" aria-selected="' +
                (index === 0) +
                '"><span class="pvt-fav" aria-hidden="true">&#9673;</span>' +
                esc(title) +
                '</span>',
            )
            .join('') +
          '</div>' +
          '<div class="pvt-page"><span class="pvt-line"></span><span class="pvt-line"></span><span class="pvt-line short"></span></div>'
        : '<div class="pvt-empty"><strong>Private window closed</strong><span>Its tabs and their history are gone.</span></div>') +
      '<div class="pvt-history"><span class="pvt-history-label">History</span><strong>0 entries</strong><small>Private tabs never write to history, and nothing here is kept after the window closes.</small></div>' +
      '</div>' +
      '<div class="pvt-controls">' +
      '<button type="button" class="pvt-new" data-onboard="pvt-new">New private tab</button>' +
      (count
        ? '<button type="button" class="pvt-close" data-onboard="pvt-close">Close private window</button>'
        : '<button type="button" class="pvt-new" data-onboard="pvt-reopen">Reopen private window</button>') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-privatetabs">' +
      '<li><strong>01 Private styling</strong><span>The dark window and mask mark private mode.</span></li>' +
      '<li><strong>02 No history</strong><span>Nothing from this window is written to history.</span></li>' +
      '<li><strong>03 New tab</strong><span>New private tabs keep the same styling and stay out of history.</span></li>' +
      '<li><strong>04 Close</strong><span>Closing drops the tabs and leaves history empty.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="pvt-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderMobileOverflow() {
    const query = overflowQuery.trim().toLowerCase();
    const visible = overflowTabs.filter((tab) => !query || tab.title.toLowerCase().includes(query));
    const rows = visible.length
      ? visible
          .map(
            (tab, index) =>
              '<span class="mo-row"><span class="mo-index">' +
              (index + 1) +
              '</span><span class="mo-title">' +
              esc(tab.title) +
              '</span></span>',
          )
          .join('')
      : '<span class="mo-empty">' +
        (overflowTabs.length ? 'No tabs match.' : 'No tabs open. New tab starts again.') +
        '</span>';
    return (
      '<div class="onboarding-overflow">' +
      '<div class="mo-phone">' +
      '<div class="mo-top"><span class="mo-dot" aria-hidden="true"></span><span class="mo-top-title">Vaayvu</span><span class="mo-count">' +
      overflowTabs.length +
      '</span></div>' +
      '<div class="mo-sheet" role="dialog" aria-label="Tab overflow menu">' +
      '<span class="mo-grabber" aria-hidden="true"></span>' +
      '<div class="mo-head"><strong>Tabs</strong><span class="mo-head-count">' +
      overflowTabs.length +
      (overflowTabs.length === 1 ? ' open' : ' open') +
      '</span></div>' +
      (overflowSearch
        ? '<label class="mo-search"><span class="mo-search-icon" aria-hidden="true">' +
          tourIcon('search') +
          '</span><input type="text" data-overflow-search value="' +
          esc(overflowQuery) +
          '" placeholder="Search tabs" aria-label="Search tabs"></label>'
        : '') +
      '<div class="mo-list">' +
      rows +
      '</div>' +
      '<div class="mo-actions">' +
      '<button type="button" class="mo-action is-primary" data-onboard="mo-new">' +
      tourIcon('plus') +
      ' New tab</button>' +
      '<button type="button" class="mo-action' +
      (overflowSearch ? ' is-on' : '') +
      '" data-onboard="mo-search" aria-pressed="' +
      overflowSearch +
      '">' +
      tourIcon('search') +
      ' Search</button>' +
      '<button type="button" class="mo-action is-danger' +
      (overflowConfirm ? ' is-confirm' : '') +
      '" data-onboard="mo-close-all">' +
      (overflowConfirm ? 'Confirm close all' : 'Close all') +
      '</button>' +
      '</div>' +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Close all</strong><span>First tap asks, second tap closes every tab.</span></li>' +
      '<li><strong>02 New tab</strong><span>Adds one tab and updates the count at once.</span></li>' +
      '<li><strong>03 Search</strong><span>Opens a field and filters the sheet as you type.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="mo-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="mo-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(overflowMessage || overflowTabs.length + ' tabs in the overflow sheet.') +
      '</small>' +
      '</div>'
    );
  }

  function renderTabSwipe() {
    const count = swipeTabs.length;
    const activeTitle = swipeTabs[swipeIndex] || swipeTabs[0] || '';
    const pages = swipeTabs
      .map(
        (title, index) =>
          '<section class="tsw-page" data-swipe-page="' +
          index +
          '" aria-hidden="' +
          (index !== swipeIndex) +
          '"><span class="tsw-kicker">Tab ' +
          (index + 1) +
          ' of ' +
          count +
          '</span><strong>' +
          esc(title) +
          '</strong><small>' +
          ['arxiv.org', 'vaayvu.com', 'notes.example.com'][index] +
          '</small><span class="tsw-line"></span><span class="tsw-line"></span><span class="tsw-line short"></span>' +
          '<span class="tsw-block"></span></section>',
      )
      .join('');
    const dots = swipeTabs
      .map(
        (title, index) =>
          '<button type="button" class="tsw-dot' +
          (index === swipeIndex ? ' is-active' : '') +
          '" data-onboard="sw-dot" data-index="' +
          index +
          '" aria-label="Show ' +
          esc(title) +
          '" aria-current="' +
          (index === swipeIndex) +
          '"></button>',
      )
      .join('');
    return (
      '<div class="onboarding-swipe">' +
      '<div class="tsw-head"><strong>Tab swipe</strong><span class="tsw-position">' +
      (swipeIndex + 1) +
      ' / ' +
      count +
      '</span></div>' +
      '<div class="tsw-viewport' + (swipeDragging ? ' is-dragging' : '') + '" data-swipe-stage>' +
      '<div class="tsw-track" style="width:' +
      count * 100 +
      '%;transform:translateX(calc(' +
      -swipeIndex * (100 / count) +
      '% + ' +
      swipeDragX +
      'px))">' +
      pages +
      '</div>' +
      '</div>' +
      '<div class="tsw-hint" aria-hidden="true"><span class="tsw-arrow">&#8249;</span>Swipe between tabs<span class="tsw-arrow">&#8250;</span></div>' +
      '<div class="tsw-dots">' +
      dots +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Swipe</strong><span>Drag left or right; the tab follows your finger.</span></li>' +
      '<li><strong>02 Settle</strong><span>A short drag snaps back; a full one changes tab.</span></li>' +
      '<li><strong>03 Dots</strong><span>Tap a dot to jump without swiping.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="sw-prev"' +
      (swipeIndex === 0 ? ' disabled' : '') +
      '>&#8249; Previous tab</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sw-next"' +
      (swipeIndex === count - 1 ? ' disabled' : '') +
      '>Next tab &#8250;</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="sw-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(swipeMessage || esc(activeTitle) + ' · ' + (swipeIndex + 1) + ' of ' + count) +
      '</small>' +
      '</div>'
    );
  }

  function renderEmptyTabState() {
    const empty = emptyTabCount === 0;
    const tabs = Array.from({ length: emptyTabCount }, (_, index) => index + 1)
      .map(
        (number) =>
          '<span class="et-tab' +
          (number === emptyTabCount ? ' is-active' : '') +
          '">New tab ' +
          number +
          '</span>',
      )
      .join('');
    return (
      '<div class="onboarding-empty">' +
      '<div class="et-frame">' +
      '<div class="et-strip" role="tablist" aria-label="Tabs">' +
      (tabs || '<span class="et-empty-tab">No tabs</span>') +
      '<button type="button" class="et-plus" data-onboard="et-new" aria-label="Open a new tab">+</button>' +
      '</div>' +
      '<div class="et-stage">' +
      (empty
        ? '<span class="et-mark" aria-hidden="true">+</span>' +
          '<strong>No tabs open</strong>' +
          '<small>Open a new tab to start browsing. Nothing was lost.</small>' +
          '<button type="button" class="et-cta" data-onboard="et-new">New tab <kbd>\u2318T</kbd></button>'
        : '<span class="et-kicker">New tab</span>' +
          '<strong>Start typing an address</strong>' +
          '<small>Search or enter a URL in the omnibox.</small>' +
          '<span class="et-line"></span><span class="et-line short"></span>') +
      '</div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 No tabs</strong><span>The strip stays honest and shows an empty state.</span></li>' +
      '<li><strong>02 New tab</strong><span>The CTA opens one tab and the strip updates.</span></li>' +
      '<li><strong>03 Fresh start</strong><span>An empty window never pretends a page is loaded.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="et-new">New tab</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="et-reset">Reset</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="et-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(emptyTabMessage || (empty ? 'No tabs open.' : emptyTabCount + ' tab' + (emptyTabCount === 1 ? '' : 's') + ' open.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderLoadedPage() {
    return (
      '<div class="onboarding-loaded">' +
      '<div class="ld-window">' +
      '<div class="ld-chrome">' +
      '<div class="ld-tabstrip"><span class="ld-dots" aria-hidden="true"><i></i><i></i><i></i></span>' +
      '<span class="ld-tab is-active">Reading the wind</span><span class="ld-new" aria-hidden="true">+</span></div>' +
      '<div class="ld-toolbar">' +
      '<button type="button" class="ld-tool" data-onboard="ld-reload" aria-label="Reload page">' +
      tourIcon('reload') +
      '</button>' +
      '<span class="ld-omnibox"><span class="ld-lock" aria-hidden="true"></span>vaayvu.com/atlas/loaded-page</span>' +
      '<button type="button" class="ld-tool" data-onboard="ld-status-toggle" aria-pressed="' +
      contentStatusShown +
      '" aria-label="Toggle status bar">' +
      (contentStatusShown ? 'Hide status' : 'Show status') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<article class="ld-page" aria-label="Loaded article">' +
      '<span class="ld-kicker">Field notes</span>' +
      '<h3>Reading the wind over the ridge</h3>' +
      '<span class="ld-byline">Mira Sol · 6 min read</span>' +
      '<p>The ridge does not block the wind so much as it teaches it a new shape. On the lee side the air folds, slows and settles into something you can measure.</p>' +
      '<p>We walked the line at first light with a small anemometer and a notebook. Every marker told the same story: the gust arrives late, then leaves early.</p>' +
      '<blockquote>“A loaded page should feel finished: content, chrome and status all agree.”</blockquote>' +
      '<p>The rest of the route follows the contour, past the cairn and down toward the water.</p>' +
      '</article>' +
      (contentStatusShown
        ? '<div class="ld-status" role="status"><span class="ld-status-dot" aria-hidden="true"></span><strong>' +
          (contentReloads ? 'Reloaded' : 'Loaded') +
          '</strong><span>Secure connection</span><span class="ld-spacer"></span><span>18.4 KB</span><span>Ready</span></div>'
        : '') +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Content</strong><span>A real article column, not a placeholder page.</span></li>' +
      '<li><strong>02 Status</strong><span>Loaded, secure and ready, or hidden on request.</span></li>' +
      '<li><strong>03 Chrome</strong><span>Tab, omnibox and reload belong to the same window.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ld-reload">Reload</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="ld-status-toggle">' +
      (contentStatusShown ? 'Hide status bar' : 'Show status bar') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="ld-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(contentMessage || (contentStatusShown ? 'Page loaded with status visible.' : 'Page loaded, status hidden.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderBackForwardMenu() {
    const entries = bfSide === 'back' ? BF_BACK_DEFAULT : BF_FORWARD_DEFAULT;
    const visible = bfFull ? entries : entries.slice(0, 2);
    const label = bfSide === 'back' ? 'Back' : 'Forward';
    const verb = bfSide === 'back' ? 'Went back to ' : 'Went forward to ';
    const status =
      bfMessage ||
      (bfFull
        ? 'Full ' + bfSide + ' history, ' + entries.length + ' titles.'
        : label + ' history, ' + visible.length + ' of ' + entries.length + ' titles.');
    return (
      '<div class="onboarding-bfmenu">' +
      '<div class="bf-stage">' +
      '<div class="bf-toolbar" role="group" aria-label="History buttons">' +
      '<button type="button" class="bf-btn' +
      (bfSide === 'back' ? ' is-active' : '') +
      '" data-onboard="bf-side" data-side="back" aria-pressed="' +
      (bfSide === 'back') +
      '">' +
      tourIcon('back') +
      'Back<span class="bf-count">' +
      BF_BACK_DEFAULT.length +
      '</span></button>' +
      '<button type="button" class="bf-btn' +
      (bfSide === 'forward' ? ' is-active' : '') +
      '" data-onboard="bf-side" data-side="forward" aria-pressed="' +
      (bfSide === 'forward') +
      '">' +
      tourIcon('forward') +
      'Forward<span class="bf-count">' +
      BF_FORWARD_DEFAULT.length +
      '</span></button>' +
      '</div>' +
      '<div class="bf-menu" role="menu" aria-label="' +
      label +
      ' history">' +
      '<header class="bf-head"><strong>' +
      label +
      ' history</strong><span>' +
      entries.length +
      ' titles</span></header>' +
      visible
        .map(
          (item) =>
            '<button type="button" class="bf-row' +
            (bfSelected === item.id ? ' is-selected' : '') +
            '" role="menuitem" data-onboard="bf-jump" data-id="' +
            item.id +
            '"><span class="bf-dot" aria-hidden="true"></span><span class="bf-copy"><strong>' +
            esc(item.title) +
            '</strong><small>' +
            esc(item.host) +
            '</small></span><span class="bf-when">' +
            esc(item.when) +
            '</span></button>',
        )
        .join('') +
      '<button type="button" class="bf-full" data-onboard="bf-full">' +
      (bfFull ? 'Show recent pages only' : 'Show full history') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<div class="bf-controls">' +
      '<button type="button" class="bf-longpress" data-onboard="bf-longpress">Long-press for full history</button>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-bfmenu">' +
      '<li><strong>01 Long-press</strong><span>Holding Back or Forward opens the full list.</span></li>' +
      '<li><strong>02 Titles</strong><span>Every entry shows the page title and host.</span></li>' +
      '<li><strong>03 Jump</strong><span>Choosing a title moves to that page.</span></li>' +
      '<li><strong>04 Full history</strong><span>Recent pages first, older pages behind Show full history.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="bf-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(status) +
      '</small>' +
      '</div>'
    );
  }

  function renderDnsError() {
    const offline = dnsOffline;
    return (
      '<div class="onboarding-dns">' +
      '<div class="de-window">' +
      '<div class="de-chrome">' +
      '<div class="de-tabstrip"><span class="de-tab is-active"><span class="de-tab-mark" aria-hidden="true">!</span>' +
      esc(dnsHost) +
      '</span><span class="de-new" aria-hidden="true">+</span></div>' +
      '<div class="de-toolbar">' +
      '<button type="button" class="de-tool" data-onboard="de-back" aria-label="Back">' +
      tourIcon('back') +
      '</button>' +
      '<button type="button" class="de-tool" data-onboard="de-reload" aria-label="Reload">' +
      tourIcon('reload') +
      '</button>' +
      '<span class="de-omnibox"><span class="de-warn" aria-hidden="true">!</span>https://' +
      esc(dnsHost) +
      '</span>' +
      '</div></div>' +
      '<div class="de-error">' +
      '<span class="de-icon" aria-hidden="true">!</span>' +
      '<span class="de-kicker">' +
      (offline ? 'Offline' : 'DNS error') +
      '</span>' +
      '<h3>' +
      (offline ? 'You are offline' : 'This site can\u2019t be reached') +
      '</h3>' +
      '<p>' +
      (offline
        ? 'Vaayvu could not look up ' +
          esc(dnsHost) +
          ' because this device has no network connection. Reconnect, then retry.'
        : esc(dnsHost) +
          '\u2019s domain name could not be resolved. Check the address for a typo, or search for it instead.') +
      '</p>' +
      (offline ? '' : '<span class="de-code">DNS_PROBE_FINISHED_NXDOMAIN</span>') +
      (dnsQuery
        ? '<div class="de-search"><span class="de-search-label">Search instead</span><strong>Search for \u201c' +
          esc(dnsQuery) +
          '\u201d</strong><small>The address opens in search, not as a site.</small></div>'
        : '') +
      '<div class="de-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="de-retry">Retry</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="de-search">Search instead</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="de-offline">' +
      (offline ? 'Go online' : 'Go offline') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<div class="de-status"><span class="de-status-dot' +
      (offline ? ' is-offline' : '') +
      '" aria-hidden="true"></span><strong>' +
      (offline ? 'Offline' : 'DNS lookup failed') +
      '</strong><span>' +
      (offline ? 'No network connection' : 'Secure connection') +
      '</span><span class="de-spacer"></span><span>' +
      (offline ? 'Retry disabled' : dnsRetries ? dnsRetries + (dnsRetries === 1 ? ' retry' : ' retries') : 'Ready') +
      '</span></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Explain</strong><span>Plain language plus the DNS error code, when online.</span></li>' +
      '<li><strong>02 Retry</strong><span>Retry reports the same failure instead of pretending success.</span></li>' +
      '<li><strong>03 Search</strong><span>The address becomes a search instead of a dead link.</span></li>' +
      '<li><strong>04 Offline</strong><span>Offline is named separately from a DNS failure.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="de-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="de-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(dnsMessage || (offline ? 'Offline, retry needs a connection.' : 'DNS lookup failed for ' + dnsHost + '.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderOfflineError() {
    const cache = offlineCacheShown;
    const help = offlineHelpShown;
    return (
      '<div class="onboarding-offline">' +
      '<div class="of-window">' +
      '<div class="of-chrome">' +
      '<div class="of-tabstrip"><span class="of-tab is-active"><span class="of-tab-mark" aria-hidden="true"></span>Reading the wind</span><span class="of-new" aria-hidden="true">+</span></div>' +
      '<div class="of-toolbar">' +
      '<button type="button" class="of-tool" data-onboard="oe-back" aria-label="Back">' +
      tourIcon('back') +
      '</button>' +
      '<button type="button" class="of-tool" data-onboard="oe-reload" aria-label="Reload">' +
      tourIcon('reload') +
      '</button>' +
      '<span class="of-omnibox"><span class="of-offline-chip">Offline</span>vaayvu.com/atlas/reading-the-wind</span>' +
      '</div></div>' +
      '<div class="of-body">' +
      (cache
        ? '<article class="of-cached" aria-label="Cached copy"><span class="of-cached-badge">Cached copy · 2 hours ago</span>' +
          '<h3>Reading the wind over the ridge</h3>' +
          '<span class="of-byline">Mira Sol · saved for offline</span>' +
          '<p>The ridge does not block the wind so much as it teaches it a new shape. This copy was saved while the page was still online.</p>' +
          '<p>The rest of the route follows the contour, past the cairn and down toward the water.</p></article>'
        : '<div class="of-error"><span class="of-icon" aria-hidden="true">&#8764;</span>' +
          '<span class="of-kicker">Offline</span>' +
          '<h3>You\u2019re offline</h3>' +
          '<p>This page needs a connection. A cached copy from 2 hours ago is saved on this device.</p>' +
          '<span class="of-note">Nothing is lost; the cache is read-only.</span></div>') +
      (help
        ? '<div class="of-help"><strong>Network help</strong>' +
          '<ol><li>Check Wi-Fi or mobile data.</li><li>Turn airplane mode off, then on.</li><li>Restart the router if other devices are offline.</li></ol>' +
          '<small>Vaayvu keeps trying only when the system reports a connection.</small></div>'
        : '') +
      '<div class="of-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="oe-cache">' +
      (cache ? 'Hide cached copy' : 'View cached copy') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="oe-retry">Retry</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="oe-help">' +
      (help ? 'Hide network help' : 'Network help') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<div class="of-status"><span class="of-status-dot" aria-hidden="true"></span><strong>Offline</strong><span>' +
      (cache ? 'Reading cached copy' : 'No connection') +
      '</span><span class="of-spacer"></span><span>' +
      (offlineErrorRetries ? offlineErrorRetries + (offlineErrorRetries === 1 ? ' retry' : ' retries') : 'Cached copy ready') +
      '</span></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Cached copy</strong><span>The saved page is readable without pretending it is live.</span></li>' +
      '<li><strong>02 Retry</strong><span>Retry reports the network still being away.</span></li>' +
      '<li><strong>03 Network help</strong><span>Three concrete checks, not a vague apology.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="oe-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="oe-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(offlineErrorMessage || (cache ? 'Showing the cached copy.' : 'Offline. A cached copy is available.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderLoadingPage() {
    const stopped = contentLoadStopped;
    const loaded = contentLoadProgress >= 100;
    const status = stopped ? 'Stopped' : loaded ? 'Loaded' : contentLoadProgress + '%';
    return (
      '<div class="onboarding-loadingpage">' +
      '<div class="lp-window">' +
      '<div class="lp-chrome">' +
      '<div class="lp-tabstrip"><span class="lp-tab is-active"><span class="lp-spinner' +
      (stopped || loaded ? ' is-off' : '') +
      '" aria-hidden="true"></span>Reading the wind</span><span class="lp-new" aria-hidden="true">+</span></div>' +
      '<div class="lp-toolbar">' +
      '<button type="button" class="lp-tool" data-onboard="lp-back" aria-label="Back">' +
      tourIcon('back') +
      '</button>' +
      '<button type="button" class="lp-tool" data-onboard="lp-stop" aria-label="' +
      (stopped || loaded ? 'Reload page' : 'Stop loading') +
      '">' +
      (stopped || loaded ? tourIcon('reload') : '&#215;') +
      '</button>' +
      '<span class="lp-omnibox">vaayvu.com/atlas/reading-the-wind</span>' +
      '</div></div>' +
      '<div class="lp-progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="' +
      contentLoadProgress +
      '" aria-label="Page load progress"><span class="lp-progress-fill' +
      (stopped ? ' is-stopped' : '') +
      '" style="width:' +
      contentLoadProgress +
      '%"></span></div>' +
      '<div class="lp-page' +
      (stopped ? ' is-stopped' : '') +
      '" aria-busy="' +
      !stopped +
      '">' +
      '<span class="lp-skeleton is-kicker"></span>' +
      '<span class="lp-skeleton is-title"></span>' +
      '<span class="lp-skeleton is-title short"></span>' +
      '<span class="lp-skeleton is-byline"></span>' +
      '<span class="lp-skeleton is-line"></span><span class="lp-skeleton is-line"></span><span class="lp-skeleton is-line short"></span>' +
      '<span class="lp-skeleton is-image"></span>' +
      '<span class="lp-skeleton is-line"></span><span class="lp-skeleton is-line short"></span>' +
      (stopped ? '<span class="lp-stopped-note">Loading stopped. The page is incomplete.</span>' : '') +
      '</div>' +
      '<div class="lp-status"><span class="lp-status-dot' +
      (stopped ? ' is-stopped' : '') +
      '" aria-hidden="true"></span><strong>' +
      status +
      '</strong><span>' +
      (stopped ? 'Incomplete page' : loaded ? 'Ready' : 'Loading content') +
      '</span><span class="lp-spacer"></span><span>' +
      (stopped ? 'Stopped by you' : 'Skeleton until content arrives') +
      '</span></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Progress</strong><span>The bar and tab spinner agree on how far the load has come.</span></li>' +
      '<li><strong>02 Stop</strong><span>Stop freezes the load and says the page is incomplete.</span></li>' +
      '<li><strong>03 Skeleton</strong><span>Placeholders hold the layout without faking content.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="lp-step"' +
      (stopped || loaded ? ' disabled' : '') +
      '>Advance progress</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="lp-stop">' +
      (stopped || loaded ? 'Reload' : 'Stop') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="lp-restart">Restart</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="lp-continue">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(contentLoadMessage || (stopped ? 'Loading stopped at ' + contentLoadProgress + '%.' : loaded ? 'Page loaded.' : 'Loading, ' + contentLoadProgress + '%.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderTimeoutError() {
    const attempts = timeoutMissing;
    const detailRows = [
      ['Address', 'https://example.com/atlas/timeout'],
      ['Waited', '30 seconds'],
      ['Error', 'ERR_TIMED_OUT'],
      ['Attempts', String(attempts)],
      ['Network', 'Online'],
      ['Server', 'No response'],
    ]
      .map(
        ([label, value]) =>
          '<div class="to-row"><span>' + label + '</span><strong>' + esc(value) + '</strong></div>',
      )
      .join('');
    return (
      '<div class="onboarding-timeout">' +
      '<div class="to-window">' +
      '<div class="to-chrome">' +
      '<div class="to-tabstrip"><span class="to-tab is-active"><span class="to-tab-mark" aria-hidden="true">!</span>example.com</span><span class="to-new" aria-hidden="true">+</span></div>' +
      '<div class="to-toolbar">' +
      '<button type="button" class="to-tool" data-onboard="to-back" aria-label="Back">' +
      tourIcon('back') +
      '</button>' +
      '<button type="button" class="to-tool" data-onboard="to-retry" aria-label="Retry">' +
      tourIcon('reload') +
      '</button>' +
      '<span class="to-omnibox"><span class="to-warn" aria-hidden="true"></span>https://example.com/atlas/timeout</span>' +
      '</div></div>' +
      '<div class="to-error">' +
      '<span class="to-icon" aria-hidden="true">&#9201;</span>' +
      '<span class="to-kicker">Timeout</span>' +
      '<h3>This page took too long to respond</h3>' +
      '<p>example.com did not answer within 30 seconds. The server may be busy, or the connection may have dropped.</p>' +
      '<span class="to-code">ERR_TIMED_OUT</span>' +
      (timeoutDetails
        ? '<div class="to-details" role="region" aria-label="Timeout details"><span class="to-details-title">Details</span>' +
          detailRows +
          '</div>'
        : '') +
      '<div class="to-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="to-retry">Retry</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="to-details-toggle">' +
      (timeoutDetails ? 'Hide details' : 'Show details') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<div class="to-status"><span class="to-status-dot" aria-hidden="true"></span><strong>Timed out</strong><span>No response after 30 s</span><span class="to-spacer"></span><span>' +
      (attempts ? attempts + (attempts === 1 ? ' retry' : ' retries') : 'Try again') +
      '</span></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Retry</strong><span>Retry reports another timeout; it never fakes a load.</span></li>' +
      '<li><strong>02 Details</strong><span>Address, wait time, error code, attempts and network state.</span></li>' +
      '<li><strong>03 Status</strong><span>The page is still incomplete and says so.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="to-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="to-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(timeoutMessage || (timeoutDetails ? 'Details shown.' : 'The server did not respond in 30 seconds.')) +
      '</small>' +
      '</div>'
    );
  }

  function renderRendererCrash() {
    return (
      '<div class="onboarding-rendercrash">' +
      '<div class="rc-window">' +
      '<div class="rc-chrome">' +
      '<div class="rc-tabstrip"><span class="rc-tab is-active"><span class="rc-tab-mark" aria-hidden="true">!</span>Docs</span><span class="rc-new" aria-hidden="true">+</span></div>' +
      '<div class="rc-toolbar">' +
      '<button type="button" class="rc-tool" data-onboard="cr-back" aria-label="Back">' +
      tourIcon('back') +
      '</button>' +
      '<button type="button" class="rc-tool" data-onboard="cr-reload" aria-label="Reload page">' +
      tourIcon('reload') +
      '</button>' +
      '<span class="rc-omnibox"><span class="rc-warn" aria-hidden="true"></span>vaayvu.com/atlas/docs</span>' +
      '</div></div>' +
      '<div class="rc-error">' +
      '<span class="rc-icon" aria-hidden="true">&#9785;</span>' +
      '<span class="rc-kicker">Renderer crashed</span>' +
      '<h3>This page stopped responding</h3>' +
      '<p>The process drawing this page stopped unexpectedly. Your other tabs are unaffected, and a snapshot from a few seconds ago is still on this device.</p>' +
      '<span class="rc-code">RENDERER_CRASHED</span>' +
      (rendererRestored
        ? '<div class="rc-snapshot" role="status"><span class="rc-snapshot-badge">Restored snapshot · 12 s ago</span>' +
          '<strong>Docs</strong><span class="rc-line"></span><span class="rc-line short"></span>' +
          '<small>Read-only until the page reloads.</small></div>'
        : '') +
      (rendererReported
        ? '<div class="rc-report-note"><strong>Report queued on this device</strong><small>No telemetry backend is configured in this build.</small></div>'
        : '') +
      '<div class="rc-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="cr-reload">Reload</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="cr-restore">' +
      (rendererRestored ? 'Hide snapshot' : 'Restore') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="cr-report"' +
      (rendererReported ? ' disabled' : '') +
      '>' +
      (rendererReported ? 'Reported' : 'Report') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<div class="rc-status"><span class="rc-status-dot" aria-hidden="true"></span><strong>' +
      (rendererRestored ? 'Snapshot restored' : 'Renderer stopped') +
      '</strong><span>' +
      (rendererRestored ? 'Read-only copy' : 'Other tabs unaffected') +
      '</span><span class="rc-spacer"></span><span>' +
      (rendererReloads ? rendererReloads + (rendererReloads === 1 ? ' reload' : ' reloads') : 'No reload yet') +
      '</span></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list">' +
      '<li><strong>01 Reload</strong><span>Starts the page again without touching the other tabs.</span></li>' +
      '<li><strong>02 Restore</strong><span>Brings back the last snapshot, read-only, before reloading.</span></li>' +
      '<li><strong>03 Report</strong><span>Queues a crash report on this device; no backend is configured.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="cr-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="cr-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(rendererMessage || 'The renderer for this page stopped. Reload, restore or report it.') +
      '</small>' +
      '</div>'
    );
  }

  function renderCertificateError() {
    const info = certificateErrorInfo();
    const detail = (label, value) =>
      '<div class="ce-detail"><span>' + esc(label) + '</span><strong>' + esc(value) + '</strong></div>';
    return (
      '<div class="onboarding-certerror">' +
      '<div class="ce-window">' +
      '<div class="ce-chrome">' +
      '<div class="ce-tabstrip"><span class="ce-tab is-active"><span class="ce-tab-mark" aria-hidden="true"></span>' +
      esc(info.host) +
      '</span></div>' +
      '<div class="ce-toolbar"><span class="ce-omnibox"><span class="ce-lock" aria-hidden="true">&#9888;</span>' +
      esc(info.host) +
      '</span><span class="ce-chip">Not secure</span></div>' +
      '</div>' +
      '<div class="ce-body">' +
      '<div class="ce-alert"><span class="ce-icon" aria-hidden="true">&#9888;</span>' +
      '<span class="ce-kicker">Certificate error</span>' +
      '<h3>This connection is not private</h3>' +
      '<p>' +
      esc(info.reason) +
      ' Vaayvu stopped before loading the page.</p>' +
      (certErrorProceeded
        ? '<span class="ce-banner">You proceeded without certificate checks. This window is not protected.</span>'
        : '') +
      '</div>' +
      (certErrorWhy
        ? '<div class="ce-why" aria-label="Why this is unsafe"><strong>Why this is unsafe</strong>' +
          '<ul><li>' + esc(info.reason) + '</li>' +
          '<li>The certificate names ' + esc(info.issuedTo) + ', and you opened ' + esc(info.host) + '.</li>' +
          '<li>' + esc(info.issuer) + ' is not trusted for this connection (' + esc(info.validity) + ').</li></ul>' +
          '<small>Anyone on this network could read or change the page.</small></div>'
        : '') +
      (certErrorAdvanced
        ? '<div class="ce-advanced" aria-label="Certificate details"><strong>Certificate</strong>' +
          detail('Issued to', info.issuedTo) +
          detail('Issuer', info.issuer) +
          detail('Validity', info.validity) +
          detail('Address', info.host) +
          '</div>'
        : '') +
      '<div class="ce-actions">' +
      '<button type="button" class="ce-btn" data-onboard="ce-why">' +
      (certErrorWhy ? 'Hide why' : 'Why?') +
      '</button>' +
      '<button type="button" class="ce-btn" data-onboard="ce-advanced">' +
      (certErrorAdvanced ? 'Hide advanced' : 'Advanced') +
      '</button>' +
      '<button type="button" class="ce-proceed' +
      (certErrorProceeded ? ' is-done' : '') +
      '" data-onboard="ce-proceed"' +
      (certErrorProceeded ? ' disabled' : '') +
      '>' +
      (certErrorProceeded ? 'Proceeded' : certErrorArmed ? 'Proceed anyway (unsafe)' : 'Proceed (guarded)') +
      '</button>' +
      '<button type="button" class="ce-report' +
      (certErrorReported ? ' is-reported' : '') +
      '" data-onboard="ce-report" aria-pressed="' +
      certErrorReported +
      '">' +
      (certErrorReported ? 'Reported' : 'Report') +
      '</button>' +
      '</div>' +
      '</div>' +
      '<div class="ce-status"><span class="ce-status-dot" aria-hidden="true"></span><strong>' +
      (certErrorProceeded ? 'Unsafe' : 'Blocked') +
      '</strong><span>' +
      esc(certErrorMessage || (certErrorReported ? 'Report queued on this device.' : 'No page data was loaded.')) +
      '</span></div>' +
      '</div>' +
      '<ol class="onboarding-mainwindow-list is-certerror">' +
      '<li><strong>01 Why</strong><span>Three concrete reasons, including the certificate fields.</span></li>' +
      '<li><strong>02 Advanced</strong><span>Issued to, issuer, validity and the address opened.</span></li>' +
      '<li><strong>03 Proceed (guarded)</strong><span>Requires reviewing Advanced, then a second press.</span></li>' +
      '<li><strong>04 Report</strong><span>The report stays on this device; no telemetry backend is configured.</span></li>' +
      '</ol>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="ce-continue">Continue</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="ce-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(certErrorMessage || (certErrorProceeded ? 'Proceeded without certificate checks.' : 'Certificate blocked this page.')) +
      '</small>' +
      '</div>'
    );
  }

