      '<button type="button" class="onboarding-skip" data-onboard="pb-reset">Reset</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(policyMessage || 'Blocked by the Research device policy.') +
      '</small>' +
      '</div>'
