  function makePasswordValue(length, symbols, passphrase) {
    const pick = (list) => list[Math.floor(Math.random() * list.length)];
    if (passphrase) {
      const words = ['harbor', 'cedar', 'lantern', 'meadow', 'ridge', 'wind', 'copper', 'willow', 'summit', 'river', 'amber', 'quiet'];
      const chosen = [];
      while (chosen.length < 4) {
        const word = pick(words);
        if (!chosen.includes(word)) chosen.push(word);
      }
      return chosen.join('-');
    }
    const letters = 'abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ';
    const digits = '23456789';
    const marks = '!@#$%^&*()-_=+';
    const pool = letters + digits + (symbols ? marks : '');
    const chars = [pick(letters), pick(digits)];
    if (symbols) chars.push(pick(marks));
    while (chars.length < length) chars.push(pick(pool));
    for (let i = chars.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      [chars[i], chars[j]] = [chars[j], chars[i]];
    }
    return chars.slice(0, length).join('');
  }

