  function renderPrivacyDashboard() {
    const week = SX.pdRange === '7d';
    const values = week
      ? [['trackers', 'Trackers blocked', 128], ['cookies', 'Cookies blocked', 42], ['fingerprint', 'Fingerprint attempts', 9], ['ads', 'Ads blocked', 310]]
      : [['trackers', 'Trackers blocked', 512], ['cookies', 'Cookies blocked', 168], ['fingerprint', 'Fingerprint attempts', 31], ['ads', 'Ads blocked', 1240]];
    const bars = [38, 52, 44, 68, 58, 72, 46];
    return sxShell(
      'Privacy dashboard',
      '<div class="sx-tabs">' + [['7d', 'This week'], ['30d', '30 days']].map(([v, n]) => '<button type="button" data-onboard="prd-range" data-value="' + v + '" aria-pressed="' + (SX.pdRange === v) + '">' + n + '</button>').join('') + '</div>' +
      '<div class="pd-chart" aria-label="Blocked per day">' + bars.map((h) => '<span style="height:' + h + '%"></span>').join('') + '</div>' +
      '<div class="sx-list">' + values.map(([key, label, n]) =>
        '<div class="sx-row"><span><strong>' + label + '</strong><small>' + n + ' this ' + (week ? 'week' : '30 days') + '</small></span><button type="button" data-onboard="prd-detail" data-key="' + key + '">' + (SX.pdDetail === key ? 'Hide' : 'Details') + '</button></div>'
      ).join('') + '</div>' +
      (SX.pdDetail
        ? '<div class="sx-note"><strong>' + (values.find(([k]) => k === SX.pdDetail) || ['', '', 0])[1] + '</strong><span>' +
          (SX.pdDetail === 'fingerprint' ? 'Canvas, fonts and screen probes were normalised. No raw fingerprint was stored.' :
           SX.pdDetail === 'cookies' ? 'Third-party cookies were blocked; first-party session cookies stay.' :
           SX.pdDetail === 'trackers' ? 'Requests matched the local tracker list and were stopped before connect.' :
           'Ad requests were blocked by the Rasha Shield list.') +
          '</span></div>'
        : '') +
      '<div class="sx-actions"><button type="button" data-onboard="pd-reset">Reset week</button></div>',
      '<li><strong>01 Weekly</strong><span>Seven-day totals with a per-day chart.</span></li><li><strong>02 Trackers and cookies</strong><span>Counts link to a plain explanation.</span></li><li><strong>03 Fingerprint</strong><span>Attempts normalised locally, never stored.</span></li>',
      SX.pdMsg || (week ? 'This week · 128 trackers, 42 cookies, 9 fingerprint attempts.' : '30 days · 512 trackers, 168 cookies, 31 fingerprint attempts.'),
      'pd-continue'
    );
  }

