  function renderSettingsRoot() {
    const categories = [
      ['s-187', 'Appearance', 'Theme, accent, tabs, sidebar, motion'],
      ['s-188', 'Tabs and spaces', 'Position, close behaviour, sleep, groups, split'],
      ['s-189', 'Search and omnibox', 'Engines, suggestions, actions, AI'],
      ['s-190', 'Privacy', 'Cookies, fingerprint, HTTPS, DNS, clear'],
      ['s-191', 'Rasha ad blocker', 'Categories, custom hosts, pauses'],
      ['s-192', 'Passwords and autofill', 'Vault, passkeys, addresses, cards'],
      ['s-194', 'Downloads', 'Location, ask, scan, speed, metered'],
      ['s-195', 'Languages and translate', 'Language, spellcheck, translate'],
      ['s-197', 'System and performance', 'Memory, battery, GPU, startup, proxy'],
    ];
    const q = SX.settingsQuery.trim().toLowerCase();
    const rows = categories.filter(([, name, detail]) => !q || name.toLowerCase().includes(q) || detail.toLowerCase().includes(q));
    return sxShell(
      'Settings root',
      '<input class="sx-input" type="text" data-settings-search value="' + esc(SX.settingsQuery) + '" placeholder="Search settings" aria-label="Search settings">' +
      '<div class="sx-note"><strong>Sync status</strong><span>' + (SX.settingsQuery ? 'Filtering settings' : 'Not signed in · local settings only') + '</span></div>' +
      '<div class="sx-list">' + rows.map(([target, name, detail]) =>
        '<button type="button" class="sx-row is-button" data-onboard="set-open" data-target="' + target + '"><span><strong>' + name + '</strong><small>' + detail + '</small></span><span class="sx-badge">' + target + '</span></button>'
      ).join('') + (!rows.length ? '<span class="sx-muted">No settings match.</span>' : '') + '</div>' +
      '<div class="sx-actions"><button type="button" data-onboard="set-more">More settings</button></div>',
      '<li><strong>01 Search</strong><span>Filters titles and help text.</span></li><li><strong>02 Sections</strong><span>Nine core categories, each with a stable target.</span></li><li><strong>03 Sync status</strong><span>Effective local state is stated.</span></li>',
      SX.settingsMsg || (q ? rows.length + ' settings match.' : 'Settings root.'),
      'set-continue'
    );
  }

