  function renderAiSettingsScreen() {
    const seg = (action, current, options) => '<span class="sx-tabs">' + options.map(([v, n]) => '<button type="button" data-onboard="' + action + '" data-value="' + v + '" aria-pressed="' + (current === v) + '">' + n + '</button>').join('') + '</span>';
    return sxShell(
      'AI settings',
      '<div class="sx-row"><span><strong>Provider</strong></span>' + seg('aic-provider', SX.aicProvider, [['local', 'On-device'], ['cloud', 'Cloud']]) + '</div>' +
      '<div class="sx-row"><span><strong>Model</strong></span>' + seg('aic-model', SX.aicModel, [['Vaayvu local', 'Vaayvu local'], ['Cloud standard', 'Cloud standard'], ['Cloud max', 'Cloud max']]) + '</div>' +
      '<div class="sx-row"><span><strong>Retention</strong></span>' + seg('aic-retention', SX.aicRetention, [['session', 'Session'], ['30d', '30 days'], ['none', 'None']]) + '</div>' +
      '<div class="sx-row"><span><strong>Train on my data</strong><small>Off by default</small></span><button type="button" data-onboard="aic-training" aria-pressed="' + SX.aicTraining + '">' + (SX.aicTraining ? 'On' : 'Off') + '</button></div>' +
      '<div class="sx-actions"><button type="button" data-onboard="aic-save">Save</button></div>',
      '<li><strong>01 Provider</strong><span>On-device or cloud.</span></li><li><strong>02 Model</strong><span>Three model choices.</span></li><li><strong>03 Retention and training</strong><span>Session, 30 days or none; training off by default.</span></li>',
      SX.aicMsg || 'AI settings · on-device · Vaayvu local · session retention.',
      'aic-continue'
    );
  }

  function renderModelPicker() {
    const cloud = SX.mpProvider === 'cloud';
    const model = cloud
      ? SX.mpSpeed === 'quality' ? 'Cloud max' : 'Cloud standard'
      : 'Vaayvu local · 3B';
    const cost = cloud
      ? SX.mpSpeed === 'quality'
        ? 'About 2,400 tokens per answer · paid plan'
        : 'About 1,200 tokens per answer · included in the free plan'
      : 'No network · no per-request cost';
    return sxShell(
      'Model picker',
      '<div class="sx-tabs">' + [['local', 'On-device'], ['cloud', 'Cloud']].map(([v, n]) => '<button type="button" data-onboard="mp-provider" data-value="' + v + '" aria-pressed="' + (SX.mpProvider === v) + '">' + n + '</button>').join('') + '</div>' +
      '<div class="sx-tabs">' + [['fast', 'Fast'], ['balanced', 'Balanced'], ['quality', 'Best quality']].map(([v, n]) => '<button type="button" data-onboard="mp-speed" data-value="' + v + '" aria-pressed="' + (SX.mpSpeed === v) + '">' + n + '</button>').join('') + '</div>' +
      '<div class="sx-note"><strong>' + esc(model) + '</strong><span>' + (cloud ? 'Sends the chosen context to your sync server.' : 'Runs on this device; nothing leaves it.') + '</span></div>' +
      '<div class="sx-list"><div class="sx-row"><span><strong>Provider</strong><small>' + (cloud ? 'Cloud' : 'On-device') + '</small></span><span class="sx-badge">' + (cloud ? 'Network' : 'Local') + '</span></div>' +
      '<div class="sx-row"><span><strong>Speed</strong><small>' + esc(SX.mpSpeed) + '</small></span></div>' +
      '<div class="sx-row"><span><strong>Cost</strong><small>' + esc(cost) + '</small></span></div></div>' +
      '<div class="sx-actions"><button type="button" data-onboard="mp-use">Use this model</button></div>',
      '<li><strong>01 Provider</strong><span>On-device or cloud.</span></li><li><strong>02 Speed or quality</strong><span>Fast, balanced or best quality.</span></li><li><strong>03 Cost</strong><span>What a request uses before you commit.</span></li>',
      SX.mpMsg || (cloud ? 'Cloud · ' + model + '. Network requests will be used.' : 'On-device · ' + model + ' · no network.'),
      'mp-continue'
    );
  }

  function renderPlansUpgrade() {
    const plans = [
      { id: 'free', name: 'Free', price: '₹0', note: '60 requests / month' },
      { id: 'plus', name: 'Plus', price: SX.plCycle === 'yearly' ? '₹1,999 / yr' : '₹199 / mo', note: '2,000 requests / month' },
      { id: 'pro', name: 'Pro', price: SX.plCycle === 'yearly' ? '₹4,999 / yr' : '₹499 / mo', note: 'Unlimited fair use' },
    ];
    return sxShell(
      'Quota/paywall',
      '<div class="sx-tabs">' + [['monthly', 'Monthly'], ['yearly', 'Yearly · save 2 months']].map(([v, n]) => '<button type="button" data-onboard="pl-cycle" data-value="' + v + '" aria-pressed="' + (SX.plCycle === v) + '">' + n + '</button>').join('') + '</div>' +
      '<div class="sx-note"><strong>Assistant quota</strong><span>' + (SX.usePeriod === 'week' ? '31% used this week' : '68% used this month') + ' · warn at ' + SX.useWarn + '%.</span></div>' +
      '<div class="sx-list">' + plans.map((p) =>
        '<div class="sx-row"><span><strong>' + p.name + (p.id === SX.plCurrent ? ' · current' : '') + '</strong><small>' + p.price + ' · ' + p.note + '</small></span>' +
        (p.id === SX.plCurrent
          ? '<span class="sx-badge">Active</span>'
          : '<button type="button" data-onboard="pl-pick" data-id="' + p.id + '" aria-pressed="' + (SX.plPick === p.id) + '">' + (SX.plPick === p.id ? 'Selected' : 'Choose') + '</button>') +
        '</div>').join('') + '</div>' +
      (SX.plPick && !SX.plConfirm ? '<div class="sx-error"><strong>Change to ' + SX.plPick + '?</strong><small>Billing starts today; cancel any time.</small><button type="button" data-onboard="pl-confirm">Confirm change</button></div>' : '') +
      (SX.plConfirm ? '<div class="sx-notes"><strong>' + SX.plCurrent + ' plan active</strong><span>Receipt sent to your account email. Manage in S-219.</span></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="pl-restore">Restore purchase</button><button type="button" data-onboard="pl-billing">Billing (S-219)</button><button type="button" data-onboard="pl-compare">Compare all features</button></div>',
      '<li><strong>01 Cycle</strong><span>Monthly or yearly.</span></li><li><strong>02 Plan</strong><span>Choose, then confirm the change.</span></li><li><strong>03 Restore</strong><span>Recover an existing purchase.</span></li>',
      SX.plMsg || ('Current plan: ' + SX.plCurrent + ' · billed ' + SX.plCycle + '.'),
      'pl-continue'
    );
  }

  function renderAiError() {
    const local = SX.aeState === 'local';
    return sxShell(
      'AI error/offline',
      '<div class="sx-error"><strong>' + (local ? 'On-device fallback active' : 'Cloud model did not respond') + '</strong><small>' +
        (local
          ? 'The answer runs on this device. Your question was not sent again.'
          : 'The sync server timed out. Your question is kept so you can retry or switch to the on-device model.') +
        '</small></div>' +
      '<div class="sx-list"><div class="sx-row"><span><strong>Provider</strong><small>' + (local ? 'On-device' : 'Cloud') + '</small></span><span class="sx-badge">' + (local ? 'Local' : 'Offline') + '</span></div>' +
      '<div class="sx-row"><span><strong>Question</strong><small>Kept in this window</small></span></div>' +
      '<div class="sx-row"><span><strong>Sent again</strong><small>' + (local ? 'No' : 'Nothing until you choose') + '</small></span></div></div>' +
      '<div class="sx-actions">' +
      (local
        ? '<button type="button" data-onboard="ae-reset">Try cloud again</button>'
        : '<button type="button" data-onboard="ae-retry">Retry</button>' +
          '<button type="button" data-onboard="ae-local">Use on-device model</button>') +
      '</div>',
      '<li><strong>01 Error</strong><span>The failure is named, not hidden.</span></li><li><strong>02 Retry</strong><span>Retry never pretends to succeed while offline.</span></li><li><strong>03 Local fallback</strong><span>Run the question on this device.</span></li>',
      SX.aeMsg || (local ? 'On-device fallback · nothing sent.' : 'Cloud request failed · question kept.'),
      'ae-continue'
    );
  }

  function renderAiConsent() {
    const granted = Object.values(SX.ncScopes).filter(Boolean).length;
    return sxShell(
      'AI onboarding',
      '<div class="sx-note"><strong>What it can do</strong><span>Summarize a page, compare open tabs, rewrite a selection, or answer with citations.</span></div>' +
      '<div class="sx-chips"><span class="sx-badge">Ask this page</span><span class="sx-badge">Compare tabs</span><span class="sx-badge">Rewrite</span></div>' +
      '<div class="sx-note"><strong>What you allow</strong><span>Each scope is separate. Turning one on does not turn on the others.</span></div>' +
      '<div class="sx-list">' + [
        ['page', 'Page content', 'Send the visible text of the page you are asking about'],
        ['selection', 'Selected text', 'Send only the passage you highlight'],
        ['history', 'Chat history', 'Include earlier turns for continuity'],
        ['memory', 'Saved memory', 'Use remembered preferences'],
      ].map(([key, name, note]) =>
        '<div class="sx-row"><span><strong>' + name + '</strong><small>' + note + '</small></span><button type="button" data-onboard="nc-scope" data-key="' + key + '" aria-pressed="' + SX.ncScopes[key] + '">' + (SX.ncScopes[key] ? 'Allowed' : 'Blocked') + '</button></div>'
      ).join('') + '</div>' +
      '<div class="sx-row"><span><strong>Destination</strong><small>Where the request is processed</small></span><span class="sx-tabs">' +
        [['local', 'On-device'], ['cloud', 'Cloud']].map(([v, n]) => '<button type="button" data-onboard="nc-dest" data-value="' + v + '" aria-pressed="' + (SX.ncDest === v) + '">' + n + '</button>').join('') + '</span></div>' +
      '<div class="sx-row"><span><strong>I understand and consent</strong><small>Consent version 3 · withdraw any time</small></span><button type="button" data-onboard="nc-ack" aria-pressed="' + SX.ncAck + '">' + (SX.ncAck ? 'Checked' : 'Check') + '</button></div>' +
      (SX.ncState === 'granted' ? '<div class="sx-notes"><strong>Consent granted</strong><span>' + granted + ' scopes · ' + SX.ncDest + ' processing · recorded locally.</span></div>' : '') +
      (SX.ncState === 'declined' ? '<div class="sx-error"><strong>Consent declined</strong><small>AI features stay off until you grant consent.</small></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="nc-grant">Grant consent</button><button type="button" data-onboard="nc-decline">Decline</button>' +
      (SX.ncState === 'granted' ? '<button type="button" data-onboard="nc-withdraw">Withdraw</button>' : '') + '</div>',
      '<li><strong>01 Scopes</strong><span>Page, selection, history, memory.</span></li><li><strong>02 Destination</strong><span>On-device or cloud.</span></li><li><strong>03 Grant or withdraw</strong><span>Consent is explicit and reversible.</span></li>',
      SX.ncMsg || (SX.ncState === 'unset' ? 'Not granted · 0 scopes.' : SX.ncState + ' · ' + granted + ' scopes.'),
      'nc-continue'
    );
  }

