  function renderCheckout() {
    const plan = SX.acctPlan === 'free' ? 'pro' : SX.acctPlan;
    const yearly = SX.acctCycle !== 'monthly';
    const base = plan === 'family' ? (yearly ? 3499 : 349) : yearly ? 1999 : 199;
    const tax = Math.round(base * 0.18 * 100) / 100;
    const total = Math.round((base + tax) * 100) / 100;
    return sxShell(
      'Checkout',
      '<div class="sx-note"><strong>' + plan.charAt(0).toUpperCase() + plan.slice(1) + ' plan · ' + (yearly ? 'yearly' : 'monthly') + '</strong><span>Renews automatically until cancelled.</span></div>' +
      '<div class="sx-list"><div class="sx-row"><span><strong>Subtotal</strong><small>₹' + base.toLocaleString('en-IN') + '</small></span></div>' +
      '<div class="sx-row"><span><strong>Tax (18% GST)</strong><small>₹' + tax.toLocaleString('en-IN') + '</small></span></div>' +
      '<div class="sx-row"><span><strong>Total</strong><small>₹' + total.toLocaleString('en-IN') + '</small></span></div></div>' +
      '<div class="sx-tabs">' + [['card', 'Card'], ['apple', 'Apple Pay'], ['google', 'Google Pay']].map(([v, n]) => '<button type="button" data-onboard="co-method" data-value="' + v + '" aria-pressed="' + (SX.coMethod === v) + '">' + n + '</button>').join('') + '</div>' +
      (SX.coMethod === 'card'
        ? '<input class="sx-input" type="text" data-co-card placeholder="Card number" aria-label="Card number"><div class="sx-row"><input class="sx-input" type="text" data-co-expiry placeholder="MM/YY" aria-label="Expiry"><input class="sx-input" type="text" data-co-cvc placeholder="CVC" aria-label="CVC"></div>'
        : '<div class="sx-note"><strong>' + (SX.coMethod === 'apple' ? 'Apple Pay' : 'Google Pay') + '</strong><span>Uses the wallet on this device. No card details are stored by Vaayvu.</span></div>') +
      '<div class="sx-row"><span><strong>I agree to the terms and privacy notice</strong><small>Required before paying</small></span><button type="button" data-onboard="co-terms" aria-pressed="' + SX.coTerms + '">' + (SX.coTerms ? 'Accepted' : 'Review') + '</button></div>' +
      (SX.coDone ? '<div class="sx-notes"><strong>Checkout complete</strong><span>' + esc(SX.coMsg) + '</span></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="co-pay">Pay ₹' + total.toLocaleString('en-IN') + '</button></div>',
      '<li><strong>01 Method</strong><span>Card, Apple Pay or Google Pay.</span></li><li><strong>02 Tax</strong><span>Subtotal, GST and total shown before paying.</span></li><li><strong>03 Terms</strong><span>Explicit acceptance required.</span></li>',
      SX.coMsg || ('Total ₹' + total.toLocaleString('en-IN') + ' · ' + SX.coMethod + '.'),
      'co-continue'
    );
  }

