    const content = {
      elements: ['<main class="page">', '  <h1>Reading the wind</h1>', '  <p>The ridge does not block the wind.</p>', '</main>'],
      console: ['> document.title', '"Reading the wind"', '> navigator.onLine', 'true'],
      network: ['GET /atlas/ridge · 200 · 18.4 KB · 42 ms', 'GET /assets/vaayvu.svg · 200 · 3.1 KB · 8 ms'],
      performance: ['First paint 220 ms', 'DOMContentLoaded 310 ms', 'Long tasks: none over 50 ms'],
      memory: ['JS heap 24.6 MB', 'DOM nodes 812', 'Detached nodes 0'],
      application: ['localStorage: 3 keys', 'Cache storage: 1 cache · 1.8 MB', 'Service worker: none'],
      security: ['HTTPS · valid certificate', 'Mixed content: none', 'Rasha Shield: active'],
      lighthouse: SX.dvRun ? ['Performance 96', 'Accessibility 100', 'Best practices 100', 'SEO 92'] : ['Run Lighthouse to measure this page.'],
    }[SX.dvTab] || [];
