  function renderDeleteAccount() {
    let body;
    if (SX.daState === 'scheduled') {
      body = '<div class="sx-error"><strong>Deletion scheduled</strong><small>Account closes on 27 Dec 2026. You can still cancel.</small><button type="button" data-onboard="da-cancel">Cancel deletion</button></div>' +
        '<div class="sx-actions"><button type="button" data-onboard="da-export">Export data (S-225)</button></div>';
    } else if (SX.daState === 'deleted') {
      body = '<div class="sx-notes"><strong>Account deleted</strong><span>Signed out on this device; local data untouched.</span></div>';
    } else if (SX.daOpen) {
      body = '<div class="sx-error"><strong>Confirm deletion</strong><small>Type DELETE and enter your password.</small>' +
        '<input class="sx-input" type="text" data-da-typed value="' + esc(SX.daTyped) + '" placeholder="Type DELETE" aria-label="Type DELETE">' +
        '<input class="sx-input" type="password" data-da-pass placeholder="Password" aria-label="Password">' +
        '<div class="sx-actions"><button type="button" data-onboard="da-confirm">Schedule deletion</button><button type="button" data-onboard="da-close">Cancel</button></div></div>';
    } else {
      body = '<div class="sx-actions"><button type="button" data-onboard="da-export">Export data first (S-225)</button><button type="button" data-onboard="da-open">Delete account</button></div>';
    }
    return sxShell(
      'Delete account',
      '<div class="sx-list"><span class="sx-group-name">What happens</span>' +
      '<div class="sx-row"><span><strong>Synced data is erased</strong><small>Bookmarks, history, settings and memory</small></span></div>' +
      '<div class="sx-row"><span><strong>Subscriptions stop</strong><small>Billing ends at the close of the current period</small></span></div>' +
      '<div class="sx-row"><span><strong>Local profile stays</strong><small>Remove it separately in S-183 if you want</small></span></div></div>' +
      '<div class="sx-note"><strong>30-day grace period</strong><span>Sign in again within 30 days to cancel the deletion.</span></div>' +
      body,
      '<li><strong>01 Consequences</strong><span>Exactly what is erased and what stays.</span></li><li><strong>02 Grace period</strong><span>Thirty days to change your mind.</span></li><li><strong>03 Confirmation</strong><span>Type DELETE and re-enter your password.</span></li>',
      SX.daMsg || (SX.daState === 'scheduled' ? 'Deletion scheduled · 30-day grace.' : 'Account active.'),
      'da-continue'
    );
  }

