  function renderOneTimeSheet() {
    return sxShell(
      'Permission one-time session sheet',
      '<div class="sx-note"><strong>Camera request</strong><span>notes.example (embedded on reading.example) wants to use the camera for this session only.</span></div>' +
      '<div class="sx-list">' +
      '<div class="sx-row"><span><strong>Requesting origin</strong><small>https://notes.example · embedded frame</small></span></div>' +
      '<div class="sx-row"><span><strong>Top-level origin</strong><small>https://reading.example</small></span></div>' +
      '<div class="sx-row"><span><strong>Lifetime</strong><small>Until this tab closes or 10 minutes, whichever comes first</small></span></div>' +
      '<div class="sx-row"><span><strong>Platform permission</strong><small>Camera available · OS permission already granted</small></span></div></div>' +
      (SX.posExplain ? '<div class="sx-note"><strong>What this allows</strong><span>Only notes.example in this frame, only camera, only for the stated lifetime. Navigating the frame to another origin requires a new request.</span></div>' : '') +
      (SX.posState === 'allowed' ? '<div class="sx-notes"><strong>Allowed once</strong><span>Expires at tab close or in 10 minutes. No persistent grant was saved.</span></div>' : '') +
      (SX.posState === 'denied' ? '<div class="sx-note"><strong>Denied</strong><span>The page receives no camera access. Denial is not converted into a persistent allow after restart.</span></div>' : '') +
      '<div class="sx-actions">' + (SX.posState ? '' : '<button type="button" data-onboard="pos-allow">Allow once</button><button type="button" data-onboard="pos-deny">Deny</button>') + '<button type="button" data-onboard="pos-explain">' + (SX.posExplain ? 'Hide details' : 'Detailed scope') + '</button></div>',
      '<li><strong>01 Scope</strong><span>Requester and top-level origins.</span></li><li><strong>02 Lifetime</strong><span>Tab close or ten minutes.</span></li><li><strong>03 Boundary</strong><span>Cross-origin navigation needs a new grant.</span></li>',
      SX.posMsg || 'Camera · notes.example in reading.example · one time.',
      'pos-done'
    );
  }

  function renderClipboardWarning() {
    const read = SX.ccwMode === 'read';
    return sxShell(
      'Clipboard cross-origin warning',
      '<div class="sx-note"><strong>' + (read ? 'Read from clipboard' : 'Replace clipboard contents') + '</strong><span>' +
        (read ? 'notes.example wants to read what you copied elsewhere.' : 'notes.example wants to write to the clipboard, replacing what is there now.') + '</span></div>' +
      '<div class="sx-tabs">' + [['write', 'Write request'], ['read', 'Read request']].map(([v, n]) => '<button type="button" data-onboard="ccw-mode" data-value="' + v + '" aria-pressed="' + (SX.ccwMode === v) + '">' + n + '</button>').join('') + '</div>' +
      '<div class="sx-list">' +
      '<div class="sx-row"><span><strong>Origin</strong><small>https://notes.example · embedded frame on reading.example</small></span></div>' +
      '<div class="sx-row"><span><strong>Operation</strong><small>' + (read ? 'clipboard.readText' : 'clipboard.writeText') + '</small></span></div>' +
      '<div class="sx-row"><span><strong>User activation</strong><small>Present · triggered by your copy action</small></span></div>' +
      '<div class="sx-row"><span><strong>OS permission</strong><small>Clipboard access available</small></span></div>' +
      '<div class="sx-row"><span><strong>Sensitive content</strong><small>' + (read ? 'Clipboard contents stay hidden until you allow' : 'New text is not shown to this page before it writes') + '</small></span></div></div>' +
      (SX.ccwOrigin ? '<div class="sx-note"><strong>Origin detail</strong><span>https://notes.example uses a valid certificate. Redirected frames must request clipboard access again; a redirect cannot inherit this prompt.</span></div>' : '') +
      (SX.ccwState ? '<div class="sx-' + (SX.ccwState === 'allowed' ? 'notes' : 'note') + '"><strong>' + (SX.ccwState === 'allowed' ? 'Allowed once' : 'Denied') + '</strong><span>' +
        (SX.ccwState === 'allowed' ? (read ? 'This frame can read the clipboard for this action only.' : 'This frame may replace the clipboard once.') : 'The clipboard was left unchanged.') + '</span></div>' : '') +
      '<div class="sx-actions">' + (SX.ccwState ? '' : '<button type="button" data-onboard="ccw-allow">Allow once</button><button type="button" data-onboard="ccw-deny">Deny</button>') + '<button type="button" data-onboard="ccw-origin">Inspect origin</button></div>',
      '<li><strong>01 Operation</strong><span>Reading and replacing are distinct.</span></li><li><strong>02 Content</strong><span>Hidden until authorization.</span></li><li><strong>03 Redirect</strong><span>A redirected origin must ask again.</span></li>',
      SX.ccwMsg || (read ? 'Read request · clipboard hidden until allowed.' : 'Write request · replaces clipboard once.'),
      'ccw-done'
    );
  }

  function renderDownloadQuarantine() {
    return sxShell(
      'Dangerous download quarantine',
      '<div class="sx-note"><strong>invoice-2026.exe · quarantined</strong><span>Stored non-executable. Quarantined files cannot auto-open or run, even if you double-click the list entry.</span></div>' +
      '<div class="sx-list">' +
      '<div class="sx-row"><span><strong>Download ID</strong><small>dl-8842 · 4.2 MB</small></span></div>' +
      '<div class="sx-row"><span><strong>Verified origin</strong><small>https://files.example · certificate verified · no redirects</small></span></div>' +
      '<div class="sx-row"><span><strong>Detection</strong><small>Suspected trojan · heuristic signature match</small></span><span class="sx-badge is-warn">Suspected</span></div>' +
      '<div class="sx-row"><span><strong>Classification</strong><small>Suspected, not proven malicious. The file is withheld pending review.</small></span></div>' +
      '<div class="sx-row"><span><strong>File availability</strong><small>' + (SX.ddqRemoved ? 'File removed from this device' : 'File present in quarantine storage') + '</small></span></div></div>' +
      (SX.ddqArmed ? '<div class="sx-error"><strong>Remove the quarantined file?</strong><small>This deletes the local copy. Cancelling leaves it exactly as it is.</small><div class="sx-actions"><button type="button" data-onboard="ddq-remove-confirm">Remove file</button><button type="button" data-onboard="ddq-cancel">Cancel deletion</button></div></div>' : '') +
      (SX.ddqRemoved ? '<div class="sx-notes"><strong>File removed</strong><span>The quarantined copy is gone; the download list entry is cleared.</span></div>' : '') +
      (SX.ddqReport ? '<div class="sx-note"><strong>False-positive review requested</strong><span>Submitted: file digest, detection name and origin. No browsing history or local paths.</span></div>' : '') +
      '<div class="sx-actions">' + (SX.ddqRemoved ? '' : '<button type="button" data-onboard="ddq-remove">Remove file</button>') + '<button type="button" data-onboard="ddq-report">Request false-positive review</button></div>',
      '<li><strong>01 Detection</strong><span>Suspected is not proven.</span></li><li><strong>02 Quarantine</strong><span>Cannot auto-open or execute.</span></li><li><strong>03 Remove</strong><span>Explicit confirmation; cancel keeps the file.</span></li>',
      SX.ddqMsg || 'Quarantined · suspected trojan · file cannot open.',
      'ddq-done'
    );
  }

  function renderDownloadResume() {
    return sxShell(
      'Download resumed after restart',
      '<div class="sx-note"><strong>Archive.zip · interrupted at 42%</strong><span>Partial file kept after restart. Resuming reuses the saved bytes only when the server validators still match.</span></div>' +
      '<div class="sx-list">' +
      '<div class="sx-row"><span><strong>Partial file</strong><small>Downloads/Archive.zip.partial · 361 MB of 860 MB</small></span></div>' +
      '<div class="sx-row"><span><strong>Byte offset</strong><small>361,234,432 bytes verified</small></span></div>' +
      '<div class="sx-row"><span><strong>Server range support</strong><small>Accept-Ranges: bytes</small></span><span class="sx-badge">Supported</span></div>' +
      '<div class="sx-row"><span><strong>Validators</strong><small>ETag v7-abc matches · Last-Modified matches</small></span>' + (SX.drsValidator ? '<span class="sx-badge is-warn">Changed</span>' : '<span class="sx-badge">Match</span>') + '</div>' +
      '<div class="sx-row"><span><strong>Destination access</strong><small>Downloads folder writable · 148 GB free</small></span></div></div>' +
      '<label class="sx-field"><span>New destination (for a restart)</span><input class="sx-input" type="text" data-drs-dest value="' + esc(SX.drsDest) + '" placeholder="Downloads/Archive (1).zip"></label>' +
      (SX.drsConflict ? '<div class="sx-note"><strong>Destination exists</strong><span>Choose keep both or replace explicitly.</span><div class="sx-actions"><button type="button" data-onboard="drs-keep">Keep both</button><button type="button" data-onboard="drs-replace">Replace existing</button></div></div>' : '') +
      (SX.drsState === 'resumed' ? '<div class="sx-notes"><strong>Resume started</strong><span>Continuing from the verified byte offset. Completion waits for the final size and checksum check.</span></div>' : '') +
      (SX.drsState === 'restarted' ? '<div class="sx-notes"><strong>Restarted into a new destination</strong><span>Fresh download started; the partial file was kept.</span></div>' : '') +
      (SX.drsState === 'cancelled' ? '<div class="sx-note"><strong>Cancelled</strong><span>The partial file is still on disk and can be resumed later.</span></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="drs-resume">Resume download</button><button type="button" data-onboard="drs-restart">Restart into destination</button><button type="button" data-onboard="drs-cancel">Cancel</button><button type="button" data-onboard="drs-validator">Simulate changed validator</button></div>',
      '<li><strong>01 Partial</strong><span>Offset and server range support.</span></li><li><strong>02 Validators</strong><span>Mismatch blocks unsafe concatenation.</span></li><li><strong>03 Destination</strong><span>Conflicts need keep-both or replace.</span></li>',
      SX.drsMsg || '361 MB verified · validators match · resume available.',
      'drs-done'
    );
  }

  function renderDownloadIntegrity() {
    const digest = SX.dhvDigest === 'computed' ? 'sha256 5c19…8f2b' : SX.dhvDigest === 'failed' ? 'Not available — computation failed' : 'Not calculated yet';
    return sxShell(
      'Download hash and origin verification',
      '<div class="sx-note"><strong>Archive.zip · 860 MB</strong><span>Digest and origin checks are local. A matching unsigned hash is not proof of publisher authenticity.</span></div>' +
      '<div class="sx-list">' +
      '<div class="sx-row"><span><strong>Source origin</strong><small>https://files.example · certificate verified</small></span></div>' +
      '<div class="sx-row"><span><strong>Redirect chain</strong><small>https://files.example → https://cdn.files.example · both shown</small></span></div>' +
      '<div class="sx-row"><span><strong>Local digest</strong><small>' + esc(digest) + '</small></span>' + (SX.dhvDigest === 'computed' ? '<span class="sx-badge">Calculated</span>' : SX.dhvDigest === 'failed' ? '<span class="sx-badge is-warn">Failed</span>' : '') + '</div>' +
      '<div class="sx-row"><span><strong>Expected digest provenance</strong><small>User-supplied · no authenticated publisher hash provided</small></span></div>' +
      '<div class="sx-row"><span><strong>Publisher signature</strong><small>Unavailable · the server offers no signed digest</small></span><span class="sx-badge is-warn">Unavailable</span></div></div>' +
      '<label class="sx-field"><span>Expected digest (optional)</span><input class="sx-input" type="text" data-dhv-expected value="' + esc(SX.dhvExpected) + '" placeholder="Paste a sha256 value"></label>' +
      '<div class="sx-actions"><button type="button" data-onboard="dhv-calc">Calculate local digest</button><button type="button" data-onboard="dhv-compare">Compare expected</button><button type="button" data-onboard="dhv-fail">Simulate hash failure</button><button type="button" data-onboard="dhv-record">Export verification record</button></div>' +
      (SX.dhvCompare === 'match' ? '<div class="sx-notes"><strong>Digest matches the value you supplied</strong><span>This confirms the file matches your expected value. It is not publisher authenticity because no signed digest exists.</span></div>' : '') +
      (SX.dhvCompare === 'mismatch' ? '<div class="sx-error"><strong>Digest mismatch</strong><small>The file does not match the expected value. Do not open it.</small></div>' : '') +
      (SX.dhvCompare === 'missing' ? '<div class="sx-note"><strong>No expected digest</strong><span>Enter a value to compare, or rely on the signature when one exists.</span></div>' : '') +
      (SX.dhvRecord ? '<div class="sx-note"><strong>Verification record ready</strong><span>Contains origins, local digest, expected value source and result. Excludes cookies, tokens and local file paths.</span></div>' : ''),
      '<li><strong>01 Origins</strong><span>Source and every redirect.</span></li><li><strong>02 Digest</strong><span>Local hash and provenance.</span></li><li><strong>03 Authenticity</strong><span>Unsigned match is not publisher proof.</span></li>',
      SX.dhvMsg || 'Digest not calculated · publisher signature unavailable.',
      'dhv-done'
    );
  }

