  function renderHistoryAudit() {
    const chosen = Object.keys(SX.hdaSel).filter((k) => SX.hdaSel[k]).length;
    return sxShell(
      'AI history deletion audit',
      '<div class="sx-note"><strong>Local and provider retention differ</strong><span>Deleting locally does not erase a provider copy. Provider deletion is requested separately and reported truthfully.</span></div>' +
      '<div class="sx-list"><span class="sx-group-name">Conversations</span>' +
      '<div class="sx-row"><span><strong>Ridge survey questions</strong><small>12 Nov · local only</small></span><button type="button" data-onboard="hda-toggle" data-key="c1" aria-pressed="' + SX.hdaSel.c1 + '">' + (SX.hdaSel.c1 ? 'Selected' : 'Keep') + '</button></div>' +
      '<div class="sx-row"><span><strong>Field notes summary</strong><small>10 Nov · provider copy exists</small></span><button type="button" data-onboard="hda-toggle" data-key="c2" aria-pressed="' + SX.hdaSel.c2 + '">' + (SX.hdaSel.c2 ? 'Selected' : 'Keep') + '</button></div></div>' +
      (SX.hdaPreview ? '<div class="sx-note"><strong>Preview</strong><span>' + (chosen ? 'Removes ' + chosen + ' local conversation(s). Provider deletion will be queued where a copy exists. Audit metadata (IDs, timestamps, outcome) is retained.' : 'Nothing selected.') + '</span></div>' : '') +
      (SX.hdaArmed ? '<div class="sx-error"><strong>Delete selected history?</strong><small>Local removal happens now; provider erasure is pending until acknowledged.</small><div class="sx-actions"><button type="button" data-onboard="hda-confirm">Delete selected</button><button type="button" data-onboard="hda-cancel">Cancel</button></div></div>' : '') +
      (SX.hdaDone ? '<div class="sx-list"><span class="sx-group-name">Outcomes</span>' +
        '<div class="sx-row"><span><strong>Local conversations</strong><small>Deleted · ' + chosen + ' selected</small></span><span class="sx-badge">Completed</span></div>' +
        '<div class="sx-row"><span><strong>Provider copy</strong><small>' + (SX.hdaFail ? 'Deletion request failed · retriable' : 'Deletion request pending acknowledgment') + '</small></span><span class="sx-badge is-warn">Pending</span></div>' +
        '<div class="sx-row"><span><strong>Audit record</strong><small>IDs, times and outcome only · conversation content removed</small></span></div></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="hda-preview">Preview removal</button><button type="button" data-onboard="hda-delete">Delete selected</button><button type="button" data-onboard="hda-fail">Simulate provider failure</button></div>',
      '<li><strong>01 Selection</strong><span>Local and provider scopes shown.</span></li><li><strong>02 Delete</strong><span>Local first, provider separately.</span></li><li><strong>03 Audit</strong><span>Minimal metadata only.</span></li>',
      SX.hdaMsg || (chosen + ' conversation(s) selected; nothing deleted yet.'),
      'hda-done'
    );
  }

