  function renderCleanupRule() {
    const validHost = /^(?=.{1,253}$)([a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i.test((SX.scrHost||'').trim());
    const cats = [SX.scrCookies&&'cookies', SX.scrCache&&'cache', SX.scrStorage&&'site storage'].filter(Boolean);
    return sxShell(
      'Automatic site cleanup rule editor',
      '<div class="sx-note"><strong>Exact host only · opt-in</strong><span>Data is removed for the exact host shown. Parent domains and subdomains are never included by this rule.</span></div>' +
      '<label class="sx-field"><span>Exact host</span><input class="sx-input" type="text" data-scr-host value="' + esc(SX.scrHost) + '"></label>' +
      (SX.scrErr ? '<div class="sx-error"><strong>Check the rule</strong><small>' + esc(SX.scrErr) + '</small></div>' : '') +
      '<div class="sx-list"><span class="sx-group-name">Data categories</span>' +
      '<div class="sx-row"><span><strong>Cookies</strong><small>' + (SX.scrCookies?'Selected':'Not selected') + '</small></span></div>' +
      '<div class="sx-row"><span><strong>Cache</strong><small>' + (SX.scrCache?'Selected':'Not selected') + '</small></span></div>' +
      '<div class="sx-row"><span><strong>Site storage</strong><small>' + (SX.scrStorage?'Selected':'Not selected') + '</small></span></div>' +
      '<div class="sx-row"><span><strong>Scope</strong><small>news.example only · no parent or subdomain</small></span></div>' +
      '<div class="sx-row"><span><strong>Clear on</strong><small>Tab close · not browser close</small></span></div></div>' +
      (SX.scrPreview ? '<div class="sx-note"><strong>Preview · ' + (cats.length ? cats.join(', ') : 'nothing selected') + '</strong><span>2 active tabs on news.example share this storage; closing one tab clears it for both. Other origins are untouched.</span></div>' : '') +
      (SX.scrSaved ? '<div class="sx-notes"><strong>Rule saved</strong><span>Exact-host cleanup for news.example; unrelated origins preserved.</span></div>' : '') +
      (SX.scrMsg ? '<div class="sx-note"><strong>Status</strong><span>' + esc(SX.scrMsg) + '</span></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="scr-cookies">Toggle cookies</button><button type="button" data-onboard="scr-cache">Toggle cache</button><button type="button" data-onboard="scr-storage">Toggle site storage</button><button type="button" data-onboard="scr-preview">Preview cleanup</button><button type="button" data-onboard="scr-domain">Try whole domain</button><button type="button" data-onboard="scr-save">Save rule</button></div>',
      '<li><strong>01 Host</strong><span>Exact origin only.</span></li><li><strong>02 Categories</strong><span>Explicit and visible.</span></li><li><strong>03 Shared</strong><span>Warn on active tabs.</span></li>',
      SX.scrMsg || 'Exact-host rule draft · not saved.',
      'scr-done'
    );
  }

