  function renderAtlasCard(id) {
    const c = ATLAS_CARDS[id];
    const shown = SX.atlasScreen === id && SX.atlasMsg;
    return sxShell(
      c.title,
      c.note + '<div class="sx-list">' + c.rows + '</div>' +
        (shown ? '<div class="sx-note"><strong>Status</strong><span>' + esc(SX.atlasMsg) + '</span></div>' : '') +
        '<div class="sx-actions">' + c.actions.map(([action, label]) => '<button type="button" data-onboard="' + action + '">' + label + '</button>').join('') + '</div>',
      c.labels,
      shown || c.idle,
      id + '-done'
    );
  }

