  Object.keys(ADS_CARDS).forEach((id) => { ADS_ACTIONS[id + '-done'] = ''; });

  function renderAdCard(id) {
    const c = ADS_CARDS[id];
    const shown = SX.adScreen === id && SX.adMsg;
    let rows = id === 'a-015' && SX.ar15State === 'paid'
      ? c.rows.replace('Pending · awaiting provider', 'Paid · settled by a verified callback')
      : c.rows;
    if (id === 'a-019' && SX.ar19Exited) {
      rows = rows.replace('Stops immediately on withdrawal', 'Stopped · enrollment withdrawn');
    }
    return sxShell(
      c.title,
      c.note + '<div class="sx-list">' + rows + '</div>' +
        (shown ? '<div class="sx-note"><strong>Status</strong><span>' + esc(SX.adMsg) + '</span></div>' : '') +
        '<div class="sx-actions">' + c.actions.map(([action, label]) => '<button type="button" data-onboard="' + action + '">' + label + '</button>').join('') + '</div>',
      c.labels,
      shown || c.idle,
      id + '-done'
    );
  }

  function renderFaultContainment() {
    return sxShell(
      'Faulty rule containment',
      '<div class="sx-note"><strong>Rule R-9130 · generation 5</strong><span>Quarantined after a false-positive report. The known-good signed generation is retained for authorized rollback.</span></div>' +
      '<div class="sx-list">' +
      '<div class="sx-row"><span><strong>Impacted generation</strong><small>5 · one rule quarantined</small></span></div>' +
      '<div class="sx-row"><span><strong>Known-good generation</strong><small>4 · signed · rollback available</small></span></div>' +
      '<div class="sx-row"><span><strong>Corpus metrics</strong><small>Precision 0.94 · recall 0.88 · false positives 3 of 104</small></span></div>' +
      '<div class="sx-row"><span><strong>Matcher cost</strong><small>0.4 ms median · 2 unsupported semantics</small></span></div>' +
      '<div class="sx-row"><span><strong>Scope of evidence</strong><small>Labeled corpus only · no universal claim from one ad-test page</small></span></div></div>' +
      (SX.frcRolled ? '<div class="sx-notes"><strong>Rollback complete</strong><span>Generation 4 active; engine security and custom rules unaffected.</span></div>' : '') +
      (SX.frcMsg ? '<div class="sx-note"><strong>Status</strong><span>' + esc(SX.frcMsg) + '</span></div>' : '') +
      '<div class="sx-actions"><button type="button" data-onboard="frc-rollback">Authorize rollback</button><button type="button" data-onboard="frc-metrics">Run corpus metrics</button></div>',
      '<li><strong>01 Containment</strong><span>Rule quarantined.</span></li><li><strong>02 Rollback</strong><span>Signed known-good retained.</span></li><li><strong>03 Evidence</strong><span>Labeled corpus; no overclaim.</span></li>',
      SX.frcMsg || 'R-9130 quarantined · generation 4 recoverable.',
      'frc-done'
    );
  }

  function renderUnsupported() {
    const info = unsupportedInfo();
    if (!info) return '';
    const details = [];
    if (info.current) details.push('This device: ' + esc(info.current));
    if (info.minimum) details.push('Minimum: ' + esc(info.minimum));
    const hasLegacy = !!info.legacyUrl;
    return (
      '<div class="onboarding-unsupported">' +
      '<div class="onboarding-import-status" data-status="unavailable">' +
      '<strong>This system is below the minimum Vaayvu supports</strong>' +
      '<small>' +
      (details.length ? details.join(' · ') : 'The operating system did not meet the supported floor.') +
      '</small>' +
      '</div>' +
      (info.why ? '<p class="onboarding-update-empty">' + esc(info.why) + '</p>' : '') +
      '<div class="onboarding-actions">' +
      (hasLegacy
        ? '<button type="button" class="onboarding-primary" data-onboard="unsupported-download">Download older version</button>'
        : '') +
      '<button type="button" class="' +
      (hasLegacy ? 'onboarding-skip' : 'onboarding-primary') +
      '" data-onboard="unsupported-continue">' +
      (hasLegacy ? 'Continue anyway' : 'Continue') +
      '</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(
        unsupportedMessage ||
          (hasLegacy
            ? 'Older builds may not receive security updates.'
            : 'No older build is published for this device.'),
      ) +
      '</small>' +
      '</div>'
    );
  }

  function renderWhatsNew() {
    const info = releaseInfo();
    if (!info) return '';
    const links = info.links.length
      ? '<div class="onboarding-whatsnew-links">' +
        info.links
          .map(
            (link) =>
              '<button type="button" class="onboarding-whatsnew-link" data-tour-link="' +
              esc(link.tour) +
              '">' +
              esc(link.label) +
              '</button>',
          )
          .join('') +
        '</div>'
      : '';
    return (
      '<div class="onboarding-whatsnew">' +
      '<p class="onboarding-update-meta">Version ' +
      esc(info.version) +
      (info.date ? ' · ' + esc(info.date) : '') +
      '</p>' +
      '<ul class="onboarding-update-notes">' +
      info.notes.map((line) => '<li>' + esc(line) + '</li>').join('') +
      '</ul>' +
      links +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="whatsnew-done">Continue</button>' +
      '</div>' +
      '<small class="onboarding-step-label">These notes match the version installed on this device.</small>' +
      '</div>'
    );
  }

  function renderUpdate() {
    const info = updateInfo();
    if (!info) return '';
    const meta = [];
    meta.push(info.size ? esc(info.size) : 'Size unavailable');
    if (info.date) meta.push(esc(info.date));
    if (info.current) meta.push('Installed ' + esc(info.current));
    const notes = info.notes.length
      ? '<ul class="onboarding-update-notes">' +
        info.notes.map((line) => '<li>' + esc(line) + '</li>').join('') +
        '</ul>'
      : '<p class="onboarding-update-empty">This release fixes bugs and keeps the same features.</p>';
    return (
      '<div class="onboarding-update">' +
      '<p class="onboarding-update-badge"><span class="onboarding-update-dot" aria-hidden="true"></span>Version ' +
      esc(info.version) +
      ' is ready</p>' +
      (meta.length ? '<p class="onboarding-update-meta">' + meta.join(' · ') + '</p>' : '') +
      notes +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="install-update"' +
      (updateBusy ? ' disabled aria-busy="true"' : '') +
      '>' +
      (updateBusy ? 'Installing…' : 'Install &amp; relaunch') +
      '</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="later-update"' +
      (updateBusy ? ' disabled' : '') +
      '>Later</button>' +
      '</div>' +
      '<small class="onboarding-step-label" role="status">' +
      esc(updateMessage || 'Vaayvu restarts and your tabs come back.') +
      '</small>' +
      '</div>'
    );
  }

  function renderDefaultBrowser() {
    return (
      '<ul class="onboarding-values">' + DEFAULT_VALUES.map((line) => '<li>' + line + '</li>').join('') + '</ul>' +
      '<div class="onboarding-actions">' +
      '<button type="button" class="onboarding-primary" data-onboard="default">Set as default</button>' +
      '<button type="button" class="onboarding-skip" data-onboard="notnow">Not now</button>' +
      '</div>' +
      '<small class="onboarding-step-label">Opens your device’s default-browser setting</small>'
    );
  }

